        // ========== marked 配置（版本敏感，集中在此，配 index.html 的锁版本） ==========
        // 关键：marked 自 v12 起已移除 setOptions({ highlight })，若继续用旧写法，
        // 高亮会「静默失效」（不报错，只是没有 hljs 类名）。必须通过 renderer.code 接入。
        // 同时新版 marked 把 renderer 方法从位置参数 (code, infostring) 改为 token 对象，
        // 这里两种签名都兼容，避免上游小改动导致渲染异常（版本不匹配时只告警不报错）。
        const MARKED_MAJOR_EXPECTED = 12;

        function highlightToHtml(code, lang) {
            if (typeof hljs === 'undefined') return escapeHtml(code);
            try {
                if (lang && hljs.getLanguage(lang)) {
                    return hljs.highlight(code, { language: lang, ignoreIllegals: true }).value;
                }
                return hljs.highlightAuto(code).value;
            } catch (e) {
                console.warn('[marked] 代码高亮失败，降级为纯文本:', e);
                return escapeHtml(code);
            }
        }

        if (typeof marked !== 'undefined' && typeof marked.use === 'function') {
            const markedVersion = String(marked.version || '');
            const markedMajor = parseInt(markedVersion.split('.')[0], 10);
            if (markedMajor && markedMajor !== MARKED_MAJOR_EXPECTED) {
                console.warn(`[marked] 当前版本 ${markedVersion || '未知'} 与已验证的 v${MARKED_MAJOR_EXPECTED} 不一致，`
                    + `Markdown 渲染产物可能有差异（index.html 已锁定 ${MARKED_MAJOR_EXPECTED}.x，请勿改回 latest）。`);
            }

            const _defaultRenderer = (typeof marked.Renderer === 'function') ? new marked.Renderer() : null;

            marked.use({
                breaks: true,
                gfm: true,
                renderer: {
                    // 代码块：自己拼 <pre><code>，交给 highlight.js
                    code(codeOrToken, infostring) {
                        const legacy = typeof codeOrToken !== 'object' || codeOrToken === null;
                        const raw = String(legacy ? (codeOrToken ?? '') : (codeOrToken.text ?? ''));
                        const langRaw = String(legacy ? (infostring ?? '') : (codeOrToken.lang ?? ''));
                        const lang = langRaw.trim().split(/\s+/)[0];
                        const langClass = lang ? ` language-${escapeHtml(lang)}` : '';
                        return `<pre><code class="hljs${langClass}">${highlightToHtml(raw, lang)}</code></pre>\n`;
                    },
                    // 链接防御：href 缺失或指向 javascript:/data: 时退化为纯文本；
                    // 其余透传 marked 默认实现，保持既有渲染行为不变。
                    link(hrefOrToken, title, text) {
                        const legacy = typeof hrefOrToken !== 'object' || hrefOrToken === null;
                        const href = legacy ? hrefOrToken : hrefOrToken.href;
                        const isUnsafe = !href || /^\s*(?:javascript|data|vbscript)\s*:/i.test(String(href));
                        if (isUnsafe) {
                            const plain = legacy ? String(text ?? href ?? '') : String(hrefOrToken.text ?? href ?? '');
                            return escapeHtml(plain);
                        }
                        if (legacy && _defaultRenderer && typeof _defaultRenderer.link === 'function') {
                            return _defaultRenderer.link(hrefOrToken, title, text);
                        }
                        if (!legacy) {
                            const tokens = hrefOrToken.tokens;
                            const inner = (this && this.parser && Array.isArray(tokens))
                                ? this.parser.parseInline(tokens)
                                : escapeHtml(String(hrefOrToken.text ?? ''));
                            const titleAttr = hrefOrToken.title ? ` title="${escapeHtml(hrefOrToken.title)}"` : '';
                            return `<a href="${escapeHtml(href)}"${titleAttr}>${inner}</a>`;
                        }
                        // 兜底：拿不到默认实现时手工渲染受控 <a>
                        const titleAttr = title ? ` title="${escapeHtml(title)}"` : '';
                        return `<a href="${escapeHtml(href)}"${titleAttr}>${escapeHtml(String(text ?? href))}</a>`;
                    }
                }
            });
        } else if (typeof marked !== 'undefined') {
            console.warn('[marked] 未找到 marked.use()，代码高亮与 breaks/gfm 配置将被跳过');
        }

        function runInitStep(name, fn) {
            try {
                return fn();
            } catch (error) {
                console.error(`[启动] ${name} 失败，已跳过:`, error);
                return undefined;
            }
        }

        async function init() {
            // 每一步单独兜住：手机上某一项数据损坏或某个模块未加载时，
            // 不能再让整段启动中断 —— 否则角色列表、聊天记录和其余按钮全部不出现。
            runInitStep('角色数据', loadAllFriendsData);
            runInitStep('用户名', loadUserName);
            runInitStep('用户头像', loadUserAvatar);
            await runInitStep('聊天记录', () => loadThreadManager());
            runInitStep('聊天设置', loadChatSettings);
            runInitStep('表情面板', initEmojiPicker);
            runInitStep('API 设置', loadApiSettings);
            runInitStep('实验室设置', loadLaboratory3DSettings);
            runInitStep('3D 实验室', () => window.Laboratory3D?.init?.());
            runInitStep('知识库设置', loadKnowledgeSettings);
            runInitStep('自动备份设置', loadAutoBackupSettings);
            runInitStep('角色卡导出格式', initCharExportSettingsPanel);
            runInitStep('上下文 token 面板', initContextPanel);
            runInitStep('增强功能开关', renderFeatureFlagPanel);
            runInitStep('主题', initThemeMode);
            runInitStep('图片预览', initImagePreview);
            runInitStep('语音输入', initVoiceInput);
            runInitStep('指令面板', initCommandPanel);
            runInitStep('角色列表', renderFriendList);


            runInitStep('打开上次对话', () => {
                // 「角色卡市场」等页面用 ?friend=<id> 指定要打开的角色：
                // 优先于「上次聊的角色」，但只有该角色确实在主站里时才生效。
                let requestedId = '';
                try { requestedId = new URLSearchParams(location.search).get('friend') || ''; } catch (e) { requestedId = ''; }
                if (requestedId && friendsData[requestedId]) { switchFriend(requestedId); return; }
                const lastChatId = localStorage.getItem('lastChatId');
                if (lastChatId && friendsData[lastChatId]) switchFriend(lastChatId);
                else switchFriend('silverwolf');
            });


            runInitStep('恢复输入草稿', restoreMessageDraft);

            // 【启动对账】「打开网站时当前角色的聊天记录没显示、点别的角色再回来才出现」
            // 的最后一道防线：无论首次渲染是被异常中断、被防抖竞态吞掉还是被任何
            // 启动期模块干扰，只要当前角色有消息而画面上一条气泡都没有，
            // 就强制补一次渲染。正常情况下每次检查都是零成本（一次 querySelector）。
            //
            // 旧版只在 900ms 查一次 —— 用户环境里依然偶发：脚本加载器是异步的，
            // 某些补丁/模块在 900ms 之后才加载完成并干扰渲染，一次性对账管不到。
            // 现在改成「看门狗」：前 30 秒内按指数间隔复查（1s/2s/4s/8s/15s/30s），
            // 并在窗口 load、标签页切回可见时各查一次。任何一次发现
            // 「有消息但一条气泡都没有」就补渲染；补渲染成功即停止后续检查。
            const verifyChatRendered = (why) => {
                try {
                    if (!currentFriendId) return false;
                    if (!getMessages().length) return false;
                    const box = document.getElementById('chat-messages');
                    if (box && box.querySelectorAll('.message').length > 0) return true; // 健康
                    console.warn('[启动] 对账(' + why + '): 当前角色有', getMessages().length, '条消息但画面为空，已自动补渲染');
                    renderMessages(currentFriendId, { forceBottom: true });
                    return true;
                } catch (e) { return false; }
            };
            runInitStep('首次渲染对账', () => {
                const delays = [900, 2000, 4000, 8000, 15000, 30000];
                let idx = 0;
                const tick = () => {
                    const healthy = verifyChatRendered('t+' + delays[idx] + 'ms');
                    idx += 1;
                    // 一旦确认画面健康（或补渲染过），剩余的检查就没必要了；
                    // 但如果既不健康又补渲染失败（异常），继续按计划重试。
                    if (idx < delays.length && !healthy) setTimeout(tick, delays[idx] - delays[idx - 1]);
                };
                setTimeout(tick, delays[0]);
                // 窗口 load：所有同步脚本执行完的时点，补一次检查
                if (document.readyState === 'complete') verifyChatRendered('load-immediate');
                else window.addEventListener('load', () => setTimeout(() => verifyChatRendered('window-load'), 300), { once: true });
                // 手机切后台回来 / 选中别的窗口再切回：这类时刻常伴随渲染丢失的反馈
                document.addEventListener('visibilitychange', () => {
                    if (document.visibilityState === 'visible') setTimeout(() => verifyChatRendered('visible'), 200);
                }, { passive: true });
            });

            runInitStep('角色选项', renderFriendOptions);
            runInitStep('视口检测', checkViewport);
            runInitStep('气泡样式', initBubbleStyleSelector);
            runInitStep('背景', loadBackground);   // 修复：以前从未调用，导致刷新后自定义背景丢失

            // 注册 Service Worker 用于 PWA。
            // 不包在 window.load 里：手机上若某个资源卡住，load 永远不来，
            // 新版本就没法接管，用户会一直停在打不开的旧页面。
            if ('serviceWorker' in navigator) {
                navigator.serviceWorker.register('sw.js').then(registration => {
                    dbgLog('Service Worker 注册成功:', registration.scope);
                    // SW 无法读取本页面的 localStorage，调试开关只能显式下发；
                    // 注册成功后同步一次，避免 SW 用默认值覆盖用户的选择。
                    syncServiceWorkerDebugState(registration);
                    const waiting = registration.waiting;
                    if (waiting) waiting.postMessage({ type: 'SKIP_WAITING' });
                    registration.addEventListener('updatefound', () => {
                        const worker = registration.installing;
                        worker?.addEventListener('statechange', () => {
                            if (worker.state === 'installed' && navigator.serviceWorker.controller) {
                                worker.postMessage({ type: 'SKIP_WAITING' });
                            }
                        });
                    });
                }).catch(error => {
                    // 注册失败是真实故障（离线能力全无），必须用 error 级别暴露
                    console.error('Service Worker 注册失败:', error);
                });
            }

            // 虚拟滚动：实际滚动容器是 .chat-messages，不是它的父级 .chat-area。
            // 监听父级会导致消息较多时滚动状态永远不更新，从而出现空白、无法继续滚动的问题。
            if (chatMessages) {
                chatMessages.addEventListener('scroll', () => {
                    requestAnimationFrame(handleScrollForVirtual);
                }, { passive: true });
            }

            // IndexedDB 自动迁移旧数据
            if ('indexedDB' in window) {
                IndexedDBStorage.migrateFromLocalStorage()
                    .then(() => restoreFriendsDataFromIndexedDB())
                    .catch(() => {});
            }

            // 全屏模式：按已保存的设置恢复（loadChatSettings 里也会同步一次勾选框）
            runInitStep('全屏模式', () => applyFullscreenMode(getChatSettings().enableFullscreenMode === true));

            // ========== AI 主动冒泡功能（低概率） ==========
            runInitStep('群聊主动发言', startGroupChatProactiveBubble);

            // 上线问候：当前聊天界面的角色（群聊则是最活跃的成员）先发一句
            runInitStep('上线问候', maybeSendOnlineGreeting);
        }

        // ========== AI 主动冒泡功能 ==========
        let proactiveBubbleTimer = null;
        let lastUserActivityTime = Date.now();

        // 记录用户活动时间
        function updateUserActivity() {
            lastUserActivityTime = Date.now();
        }

        function startGroupChatProactiveBubble() {
            if (proactiveBubbleTimer) return;

            // 每 3 分钟检查一次是否要主动冒泡
            proactiveBubbleTimer = setInterval(() => {
                // 只在群聊中生效
                if (!isGroupChat()) return;

                const idleMinutes = (Date.now() - lastUserActivityTime) / 60000;
                const rhythm = getGroupRhythm(groupManager[currentFriendId]);
                if (!rhythm.interrupt || idleMinutes < rhythm.proactiveIdle) return;

                // 冷场后按群设置的概率开口，不再用固定 5%。
                if (Math.random() > rhythm.proactiveChance) return;

                // 随机选一个 AI 主动冒泡
                const group = groupManager[currentFriendId];
                if (!group) return;

                normalizeGroupState(group);
                const ids = (group.memberIds || []).filter(id => friendsData[id] && !isGroupMemberMuted(group, id));
                if (ids.length === 0) return;

                const randomMember = ids[Math.floor(Math.random() * ids.length)];
                
                // 主动说一句话
                callGroupMemberAI('（群聊冷场了，请你主动说一句话来活跃气氛，或者对当前话题发表一下看法。）', currentFriendId, randomMember);

            }, 3 * 60 * 1000); // 每 3 分钟检查一次
        }

        function checkViewport() {
            const width = window.innerWidth;
            const height = window.innerHeight;
            const isPortraitTablet = (width >= 769 && width <= 1024 && height > width);

            if ((width <= 768 || isPortraitTablet) && !isMobileView) {
                setMobileView(true);
            } else if (width > 768 && !isPortraitTablet && isMobileView) {
                setMobileView(false);
            }
        }

        function setMobileView(mobile) {
            isMobileView = mobile;
            if (mobile) {
                appContainer?.classList.add('mobile-view');
                sidebar?.classList.add('hidden');
                sidebarOverlay?.classList.remove('show');
                if (viewToggleIcon) viewToggleIcon.className = 'ri-computer-line';
            } else {
                appContainer?.classList.remove('mobile-view');
                sidebar?.classList.remove('hidden');
                sidebarOverlay?.classList.remove('show');
                if (viewToggleIcon) viewToggleIcon.className = 'ri-smartphone-line';
            }
            setLocalStorageSafely('isMobileView', mobile.toString());
        }

        viewToggleBtn?.addEventListener('click', () => {
            setMobileView(!isMobileView);
        });

        /* ------------------------------------------------------------
           侧边栏开关统一入口
           过去开/关逻辑散落在汉堡按钮、遮罩、聊天区点击、角色项点击四处，
           每处都手写 classList，漏掉任何一处（比如 aria-expanded）就会出现
           「遮罩没了但侧边栏还在」这类不同步的状态。统一成三个函数。
 */
        function isSidebarOpen() {
            return Boolean(sidebar && !sidebar.classList.contains('hidden'));
        }

        function openSidebar() {
            if (!sidebar) return;
            sidebar.classList.remove('hidden');
            sidebarOverlay?.classList.add('show');
            mobileMenuBtn?.setAttribute('aria-expanded', 'true');
        }

        function closeSidebar() {
            if (!sidebar) return;
            sidebar.classList.add('hidden');
            sidebarOverlay?.classList.remove('show');
            mobileMenuBtn?.setAttribute('aria-expanded', 'false');
        }

        window.closeSidebar = closeSidebar;

        mobileMenuBtn?.addEventListener('click', (e) => {
            e.stopPropagation();
            // 汉堡按钮改成「切换」：打开状态下再点一次就收起。
            // 旧实现只会 remove('hidden')，一旦其它关闭路径失效（例如动效残留），
            // 用户连这个按钮都救不回来。
            isSidebarOpen() ? closeSidebar() : openSidebar();
        });

        sidebarOverlay?.addEventListener('click', closeSidebar);

        /* 侧边栏内部的关闭按钮。
           手机上 .sidebar 的 z-index(100) 高于 .mobile-menu-btn(10)，
           侧边栏一展开就把汉堡按钮盖住，用户点不到 —— 表现就是
           「汉堡菜单打开侧边栏后关不掉」。这个按钮在侧边栏里面，
           跟着浮层一起移动，任何动效/层级异常下都点得到。 */
        document.getElementById('sidebar-close-btn')?.addEventListener('click', (e) => {
            e.stopPropagation();
            closeSidebar();
        });

        chatArea?.addEventListener('click', () => {
            if (isMobileView && isSidebarOpen()) closeSidebar();
            toggleAvatarMenu(false);
            toggleAiAvatarMenu(false);
            toggleFriendContextMenu(false);
        });

        // Esc 收起侧边栏（桌面端键盘操作与无障碍要求）
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && isSidebarOpen() && isMobileView) closeSidebar();
        });

        // 点到侧边栏以外的任何地方都收起：遮罩层级被动效/浮层盖住时也能关。
        document.addEventListener('click', (e) => {
            if (!isMobileView || !isSidebarOpen()) return;
            const target = e.target;
            if (sidebar.contains(target) || mobileMenuBtn?.contains(target)) return;
            // 弹窗、菜单、角色卡等浮层里的点击不算「点外面」，避免误关
            if (target.closest?.('.modal-overlay.show, .friend-context-menu.show, .avatar-menu.show, #command-panel.show, #emoji-picker.show, #board-game')) return;
            closeSidebar();
        });

        window.addEventListener('resize', checkViewport);

        const savedMobileView = localStorage.getItem('isMobileView');
        if (savedMobileView === 'true') {
            setMobileView(true);
        }

        // ========== 表情面板：我的表情 / 内置表情包（支持自定义分组） ==========
        // 结构：标签页（我的 / 崩铁）→ 分组 chips → 表情网格 → 底栏。
        // 内置表情包不落地：图片全部引用官方 CDN，缩略图由 OSS 参数实时裁切，
        // 只有 50KB 的清单文件进包，站点体积基本不变。
        const EMOJI_CHARS = ['😀', '😃', '😄', '😁', '😆', '😅', '🤣', '😂', '🙂', '🙃', '😉', '😊', '😇', '🥰', '😍', '🤩', '😘', '😗', '😚', '😙', '🥲', '😋', '😛', '😜', '🤪', '😝', '🤑', '🤗', '🤭', '🤫', '🤔', '🤐', '🤨', '😐', '😑', '😶', '😏', '😒', '🙄', '😬', '😌', '😔', '😪', '🤤', '😴', '😷', '🤒', '🤕', '🤢', '🤮', '🤧', '🥵', '🥶', '🥴', '😵', '🤯', '🤠', '🥳', '😎', '🤓', '🧐', '😕', '😟', '🙁', '☹️', '😮', '😯', '😲', '😳', '🥺', '😦', '😧', '😨', '😰', '😥', '😢', '😭', '😱', '😖', '😣', '😞', '😓', '😩', '😫', '🥱', '😤', '😡', '😠', '🤬', '😈', '👿', '💀', '☠️', '💩', '🤡', '👹', '👺', '👻', '👽', '👾', '🤖', '😺', '😸', '😹', '😻', '😼', '😽', '🙀', '😿', '😾', '❤️', '🧡', '💛', '💚', '💙', '💜', '🖤', '🤍', '🤎', '💔', '❣️', '💕', '💞', '💓', '💗', '💖', '💘', '💝', '💟', '👍', '👎', '👏', '🙌', '👐', '🤲', '🤝', '🙏', '✌️', '🤞', '🤟', '🤘', '🤙', '👋', '🖐️', '✋', '🖖', '👌', '🤌', '🤏', '👈', '👉', '👆', '👇', '☝️', '✊', '👊', '🤛', '🤜', '💪', '🦾'];

        // OSS 图片处理参数：列表用 180px 缩略图，发送用 640px（原图常常 10MB）
        const EP_THUMB_SUFFIX = '?x-oss-process=image/resize,w_180/format,webp/quality,q_85';
        const EP_SEND_SUFFIX = '?x-oss-process=image/resize,w_640/format,webp/quality,q_90';
        const EP_PAGE_SIZE = 96;
        const epState = { tab: 'mine', mineGroup: 'all', srGroup: 'all', query: '', srPage: EP_PAGE_SIZE, chips: [] };
        let chipsScrollMemory = 0;   // 分组条横向滚动位置（重绘 chips 会把它清零）
        let chipsThumbResizeBound = false;

        // 面板里的文案大量是「动态拼数字」的（共 N 个 / 已显示 X of Y），
        // i18n.js 的短语表只做「整段完全相等」匹配，接不住这种句子，
        // 所以这里直接按当前语言取一份。静态词条仍走短语表。
        function epIsEn() {
            try { return !!(window.SiteI18n && window.SiteI18n.getLang && window.SiteI18n.getLang() === 'en'); }
            catch (e) { return false; }
        }
        function epT(zh, en) { return epIsEn() ? en : zh; }

        function getBuiltinPacks() {
            const packs = window.__MY_SW_STICKER_PACKS;
            return packs && typeof packs === 'object' ? packs : {};
        }

        function builtinImageUrl(pack, path, kind) {
            return pack.base + path + (kind === 'send' ? EP_SEND_SUFFIX : EP_THUMB_SUFFIX);
        }

        // ---- 分组存取 ----
        function loadStickerGroups() {
            let raw;
            try { raw = JSON.parse(localStorage.getItem('myStickerGroups') || '[]'); }
            catch (e) { raw = []; }
            if (!Array.isArray(raw)) raw = [];
            const seen = new Set();
            return raw.map(g => {
                if (!g || typeof g !== 'object') return null;
                const id = String(g.id || '').trim();
                const name = String(g.name || '').trim();
                if (!id || !name || seen.has(id)) return null;
                seen.add(id);
                return { id, name };
            }).filter(Boolean);
        }

        function saveStickerGroups(list) {
            setLocalStorageSafely('myStickerGroups', JSON.stringify(list), '表情分组');
        }

        function makeStickerGroupId() {
            return 'g' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
        }

        function stickerGroupName(id) {
            if (!id) return '';
            const hit = loadStickerGroups().find(g => g.id === id);
            return hit ? hit.name : '';
        }

        // ---- 面板骨架 ----
        function buildEmojiPickerShell() {
            emojiPicker.innerHTML = '';
            emojiPicker.classList.add('ep-panel');
            emojiPicker.classList.remove('ep-chars');

            const head = document.createElement('div');
            head.className = 'ep-head';
            head.innerHTML = `
                <div class="ep-tabs" role="tablist">
                    <button type="button" class="ep-tab" data-ep-tab="mine" role="tab">${epT('我的表情', 'My stickers')}</button>
                    <button type="button" class="ep-tab" data-ep-tab="sr" role="tab">${epT('崩铁表情', 'Star Rail')}</button>
                </div>
                <button type="button" class="ep-icon" data-ep-act="manage" title="${epT('管理分组', 'Manage groups')}"><i class="ri-folder-settings-line"></i></button>
                <button type="button" class="ep-icon" data-ep-act="close" title="${epT('关闭', 'Close')}"><i class="ri-close-line"></i></button>`;
            head.addEventListener('click', (e) => {
                const tabBtn = e.target.closest('[data-ep-tab]');
                if (tabBtn) {
                    const tab = tabBtn.dataset.epTab;
                    if (epState.tab !== tab) {
                        epState.tab = tab;
                        epState.query = '';
                        epState.srPage = EP_PAGE_SIZE;
                        const input = emojiPicker.querySelector('#ep-search');
                        if (input) input.value = '';
                        renderEmojiPicker();
                    }
                    return;
                }
                const actBtn = e.target.closest('[data-ep-act]');
                if (!actBtn) return;
                if (actBtn.dataset.epAct === 'close') toggleEmojiPicker(false);
                if (actBtn.dataset.epAct === 'manage') openStickerGroupManager();
            });

            const search = document.createElement('div');
            search.className = 'ep-search';
            search.innerHTML = '<i class="ri-search-line"></i><input id="ep-search" type="text" autocomplete="off" placeholder="'
                + epT('搜索备注或分组', 'Search notes or groups') + '">';
            const searchInput = search.querySelector('input');
            searchInput.addEventListener('input', () => {
                epState.query = searchInput.value;
                epState.srPage = EP_PAGE_SIZE;
                renderEmojiPicker();
            });
            // 面板里的按键不能漏到全局（Esc 关面板、方向键控输入框等）
            searchInput.addEventListener('keydown', (e) => {
                e.stopPropagation();
                if (e.key === 'Escape') toggleEmojiPicker(false);
            });

            const chips = document.createElement('div');
            chips.className = 'ep-chips';
            chips.id = 'ep-chips';
            bindChipsScroll(chips);

            // 分组多到 30+ 个时横向滑太慢，右上角常驻一个「全部分组」入口
            const chipMore = document.createElement('button');
            chipMore.type = 'button';
            chipMore.className = 'ep-chip-more';
            chipMore.id = 'ep-chip-more';
            chipMore.innerHTML = '<i class="ri-list-unordered"></i>';
            chipMore.title = epT('全部分组', 'All groups');
            chipMore.addEventListener('click', (e) => {
                e.stopPropagation();
                showGroupJumpSheet();
            });
            const chipbar = document.createElement('div');
            chipbar.className = 'ep-chipbar';

            // 自绘横向滚动条（原生条在 macOS / overlay 模式下会被系统藏起来，
            // 用户就完全看不出这排分组还能往右滚）
            const chipTrack = document.createElement('div');
            chipTrack.className = 'ep-chipbar-track';
            chipTrack.hidden = true;
            const chipThumb = document.createElement('div');
            chipThumb.className = 'ep-chipbar-thumb';
            chipTrack.appendChild(chipThumb);
            bindChipsThumbDrag(chipTrack);

            chips.addEventListener('scroll', syncChipsThumb, { passive: true });
            if (!chipsThumbResizeBound) {
                chipsThumbResizeBound = true;
                window.addEventListener('resize', syncChipsThumb);
            }
            chipbar.append(chips, chipTrack, chipMore);

            const grid = document.createElement('div');
            grid.className = 'ep-grid';
            grid.id = 'ep-grid';
            grid.addEventListener('scroll', () => {
                if (epState.tab !== 'sr') return;
                if (grid.scrollTop + grid.clientHeight < grid.scrollHeight - 80) return;
                const rendered = Number(grid.dataset.rendered || 0);
                if (rendered < Number(grid.dataset.total || 0)) {
                    epState.srPage = rendered + EP_PAGE_SIZE;
                    renderEmojiPicker({ append: true });
                }
            });
            // 格子才 50px 宽，名字塞不进去；鼠标移上去时把底栏的统计换成这张的名字
            grid.addEventListener('mouseover', (e) => {
                const tile = e.target.closest && e.target.closest('.ep-tile');
                const name = tile && tile.dataset.remark;
                if (!name) return;
                const count = emojiPicker.querySelector('#ep-foot .ep-count');
                if (!count) return;
                if (!count.dataset.orig) count.dataset.orig = count.textContent;
                count.textContent = name;
                count.classList.add('ep-count-hover');
            });
            grid.addEventListener('mouseleave', () => {
                const count = emojiPicker.querySelector('#ep-foot .ep-count');
                if (!count || !count.dataset.orig) return;
                count.textContent = count.dataset.orig;
                delete count.dataset.orig;
                count.classList.remove('ep-count-hover');
            });

            const foot = document.createElement('div');
            foot.className = 'ep-foot';
            foot.id = 'ep-foot';

            emojiPicker.append(head, search, chipbar, grid, foot);
        }

        // 分组条能横滚，但桌面鼠标既看不到滚动条、也不会横滑 —— 这里补三条通路：
        // 竖向滚轮映射成横向、按住鼠标拖动、触屏走原生（pointerType==='touch' 直接放行）。
        function bindChipsScroll(box) {
            if (!box || box.dataset.scrollBound === '1') return;
            box.dataset.scrollBound = '1';

            box.addEventListener('wheel', (e) => {
                if (box.scrollWidth <= box.clientWidth + 1) return;
                const delta = Math.abs(e.deltaY) > Math.abs(e.deltaX) ? e.deltaY : e.deltaX;
                if (!delta) return;
                const before = box.scrollLeft;
                box.scrollLeft = before + (e.deltaMode === 1 ? delta * 16 : delta);
                if (box.scrollLeft !== before) e.preventDefault();
            }, { passive: false });

            let tracking = false;
            let moved = false;
            let startX = 0;
            let startLeft = 0;

            const stopDrag = () => {
                if (!tracking) return;
                tracking = false;
                box.classList.remove('dragging');
                document.removeEventListener('pointermove', onMove, true);
                document.removeEventListener('pointerup', stopDrag, true);
                document.removeEventListener('pointercancel', stopDrag, true);
                // 拖动松手时浏览器还会补一次 click，别让它顺手选中某个分组
                if (moved) {
                    const swallow = (ev) => { ev.stopPropagation(); ev.preventDefault(); };
                    box.addEventListener('click', swallow, { capture: true, once: true });
                    setTimeout(() => box.removeEventListener('click', swallow, true), 0);
                }
            };
            const onMove = (e) => {
                if (!tracking) return;
                const dx = e.clientX - startX;
                if (!moved && Math.abs(dx) < 5) return;
                moved = true;
                box.scrollLeft = startLeft - dx;
                e.preventDefault();
            };

            box.addEventListener('pointerdown', (e) => {
                if (e.pointerType === 'touch' || e.button !== 0) return;
                if (box.scrollWidth <= box.clientWidth + 1) return;
                tracking = true;
                moved = false;
                startX = e.clientX;
                startLeft = box.scrollLeft;
                box.classList.add('dragging');
                document.addEventListener('pointermove', onMove, true);
                document.addEventListener('pointerup', stopDrag, true);
                document.addEventListener('pointercancel', stopDrag, true);
            });
        }

        // 自绘滚动条与 chips 的滚动状态保持一致
        function syncChipsThumb() {
            if (!emojiPicker) return;
            const box = emojiPicker.querySelector('#ep-chips');
            const track = emojiPicker.querySelector('.ep-chipbar-track');
            if (!box || !track) return;
            const thumb = track.firstElementChild;
            const max = box.scrollWidth - box.clientWidth;
            const bar = emojiPicker.querySelector('.ep-chipbar');
            if (max <= 1) {
                // 分组少到根本不用滚：滚动条和「全部分组」按钮都没意义
                track.hidden = true;
                if (bar) bar.classList.add('no-scroll');
                return;
            }
            track.hidden = false;
            if (bar) bar.classList.remove('no-scroll');
            const trackW = track.clientWidth || 1;
            const w = Math.max(24, Math.round(trackW * (box.clientWidth / box.scrollWidth)));
            thumb.style.width = w + 'px';
            thumb.style.left = Math.round((box.scrollLeft / max) * Math.max(0, trackW - w)) + 'px';
        }

        // 自绘滚动条：按住滑块拖、点轨道空白跳
        function bindChipsThumbDrag(track) {
            if (!track || track.dataset.dragBound === '1') return;
            track.dataset.dragBound = '1';
            const thumb = track.firstElementChild;

            let dragging = false;
            let startX = 0;
            let startLeft = 0;
            let ratio = 1;

            const onMove = (e) => {
                if (!dragging) return;
                const box = emojiPicker.querySelector('#ep-chips');
                if (!box) return;
                box.scrollLeft = startLeft + (e.clientX - startX) * ratio;
                e.preventDefault();
            };
            const stop = () => {
                if (!dragging) return;
                dragging = false;
                track.classList.remove('active');
                document.removeEventListener('pointermove', onMove, true);
                document.removeEventListener('pointerup', stop, true);
                document.removeEventListener('pointercancel', stop, true);
            };

            track.addEventListener('pointerdown', (e) => {
                const box = emojiPicker.querySelector('#ep-chips');
                if (!box || e.button !== 0) return;
                const max = box.scrollWidth - box.clientWidth;
                if (max <= 1) return;
                e.preventDefault();
                e.stopPropagation();
                const w = thumb.offsetWidth || 24;
                const rect = track.getBoundingClientRect();
                if (!thumb.contains(e.target)) {
                    // 点轨道空白：滑块中心跳到指针处
                    const pos = Math.max(0, Math.min(e.clientX - rect.left - w / 2, Math.max(0, rect.width - w)));
                    box.scrollLeft = (pos / Math.max(1, rect.width - w)) * max;
                }
                dragging = true;
                startX = e.clientX;
                startLeft = box.scrollLeft;
                ratio = max / Math.max(1, track.clientWidth - w);
                track.classList.add('active');
                document.addEventListener('pointermove', onMove, true);
                document.addEventListener('pointerup', stop, true);
                document.addEventListener('pointercancel', stop, true);
            });
        }

        // 把某个分组切过来（chips 与「全部分组」浮层共用）
        function applyStickerGroup(id) {
            if (epState.tab === 'sr') epState.srGroup = id;
            else epState.mineGroup = id;
            epState.srPage = EP_PAGE_SIZE;
            const g = emojiPicker.querySelector('#ep-grid');
            if (g) g.scrollTop = 0;
            renderEmojiPicker();
        }

        // 「全部分组」浮层：30+ 个分组横着滑太慢，列出来一次点到位
        function showGroupJumpSheet() {
            document.getElementById('ep-group-jump')?.remove();
            const list = Array.isArray(epState.chips) ? epState.chips : [];
            if (!list.length) return;

            const active = epState.tab === 'sr' ? epState.srGroup : epState.mineGroup;
            const sheet = document.createElement('div');
            sheet.id = 'ep-group-jump';
            sheet.className = 'ep-sheet';

            const title = document.createElement('div');
            title.className = 'ep-sheet-title';
            title.textContent = epT('全部分组', 'All groups');
            sheet.appendChild(title);

            const listBox = document.createElement('div');
            listBox.className = 'ep-sheet-list';

            let closed = false;
            const close = () => {
                if (closed) return;
                closed = true;
                sheet.remove();
                document.removeEventListener('click', onOutside, true);
            };
            const onOutside = (e) => {
                const t = e.target;
                if (!t || !document.documentElement.contains(t)) return;
                if (!sheet.contains(t)) close();
            };

            list.forEach(c => {
                const row = document.createElement('button');
                row.type = 'button';
                row.className = 'ep-sheet-row' + (c.id === active ? ' current' : '');
                const icon = document.createElement('i');
                icon.className = c.id === 'all'
                    ? 'ri-layout-grid-line'
                    : (c.id === 'ungrouped' ? 'ri-inbox-line' : 'ri-folder-line');
                const text = document.createElement('span');
                text.textContent = c.name;
                row.append(icon, text);
                if (typeof c.n === 'number' && c.n > 0) {
                    const num = document.createElement('em');
                    num.className = 'ep-sheet-num';
                    num.textContent = String(c.n);
                    row.appendChild(num);
                }
                if (c.id === active) {
                    const mark = document.createElement('i');
                    mark.className = 'ri-check-line ep-sheet-check';
                    row.appendChild(mark);
                }
                row.addEventListener('click', () => {
                    close();
                    applyStickerGroup(c.id);
                });
                listBox.appendChild(row);
            });
            sheet.appendChild(listBox);

            const cancel = document.createElement('button');
            cancel.type = 'button';
            cancel.className = 'ep-sheet-cancel';
            cancel.textContent = epT('取消', 'Cancel');
            cancel.addEventListener('click', () => close());
            sheet.appendChild(cancel);

            document.body.appendChild(sheet);
            // 当前分组可能在长列表中间，先把它滚进可视区
            const activeRow = listBox.querySelector('.ep-sheet-row.current');
            if (activeRow) {
                const boxRect = listBox.getBoundingClientRect();
                const rowRect = activeRow.getBoundingClientRect();
                listBox.scrollTop += (rowRect.top - boxRect.top) - listBox.clientHeight / 2 + rowRect.height / 2;
            }

            // 同一次点击不能立刻把刚打开的浮层关掉
            setTimeout(() => document.addEventListener('click', onOutside, true), 0);
        }

        function renderEmojiPicker(opts) {
            if (!emojiPicker) return;
            const append = !!(opts && opts.append === true);
            const grid = emojiPicker.querySelector('#ep-grid');
            const chipsBox = emojiPicker.querySelector('#ep-chips');
            const foot = emojiPicker.querySelector('#ep-foot');
            if (!grid || !chipsBox || !foot) {
                buildEmojiPickerShell();
                const retryGrid = emojiPicker.querySelector('#ep-grid');
                if (!retryGrid) return;
                return renderEmojiPicker(opts);
            }

            const q = String(epState.query || '').trim().toLowerCase();

            emojiPicker.querySelectorAll('.ep-tab').forEach(t => {
                t.classList.toggle('active', t.dataset.epTab === epState.tab);
            });

            // 底栏每次都要重建（追加渲染时计数会变），网格与分组条只在整屏重绘时清
            foot.innerHTML = '';
            if (!append) {
                // 清空会重置 scrollLeft，先记下当前横向位置，重建完再恢复
                chipsScrollMemory = chipsBox.scrollLeft || 0;
                chipsBox.innerHTML = '';
                grid.innerHTML = '';
                grid.scrollTop = 0;
                grid.dataset.rendered = '0';
            }

            let entries = [];
            let chips = [];
            let activeGroup = epState.tab === 'sr' ? epState.srGroup : epState.mineGroup;
            let total = 0;

            if (epState.tab === 'sr') {
                const pack = getBuiltinPacks().sr;
                if (!pack || !Array.isArray(pack.groups)) {
                    grid.innerHTML = '<div class="ep-empty">' + epT('内置表情包没有加载成功', 'The built-in sticker pack failed to load') + '</div>';
                    foot.textContent = '';
                    return;
                }
                chips = [{ id: 'all', name: epT('全部', 'All'), n: pack.groups.reduce((a, g) => a + g.items.length, 0) }]
                    .concat(pack.groups.map(g => ({ id: g.id, name: g.name, n: g.items.length })));

                const rows = [];
                pack.groups.forEach(g => {
                    if (epState.srGroup !== 'all' && epState.srGroup !== g.id) return;
                    let arr = g.items.map(([path, remark]) => ({ path, remark, groupName: g.name }));
                    if (q) {
                        arr = arr.filter(x => x.remark.toLowerCase().includes(q) || x.groupName.toLowerCase().includes(q));
                    }
                    arr.forEach(x => rows.push(x));
                });
                total = rows.length;
                const page = Math.max(EP_PAGE_SIZE, epState.srPage);
                entries = rows.slice(0, page).map(r => ({ type: 'sticker', builtin: r, pack }));
            } else {
                const stickers = loadMyStickers();
                const groups = loadStickerGroups();
                const effectiveGroup = s => (s.group && groups.some(g => g.id === s.group)) ? s.group : '';
                const ungroupedCount = stickers.filter(s => !effectiveGroup(s)).length;
                chips = [
                    { id: 'all', name: epT('全部', 'All'), n: stickers.length },
                    { id: 'ungrouped', name: epT('未分组', 'Ungrouped'), n: ungroupedCount }
                ].concat(groups.map(g => ({
                    id: g.id,
                    name: g.name,
                    n: stickers.filter(s => effectiveGroup(s) === g.id).length
                })));

                const buckets = groups.map(g => ({ id: g.id, name: g.name }));
                buckets.push({ id: '', name: epT('未分组', 'Ungrouped') });
                buckets.forEach(b => {
                    const selected = epState.mineGroup === 'all'
                        || epState.mineGroup === b.id
                        || (epState.mineGroup === 'ungrouped' && b.id === '');
                    if (!selected) return;
                    const arr = stickers
                        .map((s, i) => ({ s, i }))
                        .filter(x => effectiveGroup(x.s) === b.id)
                        .filter(x => {
                            if (!q) return true;
                            const gn = stickerGroupName(effectiveGroup(x.s)).toLowerCase();
                            return String(x.s.remark || '').toLowerCase().includes(q) || gn.includes(q);
                        });
                    if (!arr.length) return;
                    if (!q && epState.mineGroup === 'all') entries.push({ type: 'title', name: b.name });
                    arr.forEach(x => entries.push({ type: 'sticker', sticker: x.s, idx: x.i }));
                });
                total = entries.filter(e => e.type === 'sticker').length;
            }

            grid.dataset.total = String(total);

            // ---- 分组 chips（只在非追加渲染时重建）----
            if (!append) {
                epState.chips = chips;
                chips.forEach(c => {
                    const btn = document.createElement('button');
                    btn.type = 'button';
                    btn.className = 'ep-chip' + (c.id === activeGroup ? ' active' : '');
                    const label = document.createElement('span');
                    label.textContent = c.name;
                    btn.appendChild(label);
                    if (typeof c.n === 'number' && c.n > 0) {
                        const num = document.createElement('em');
                        num.textContent = String(c.n);
                        btn.appendChild(num);
                    }
                    btn.addEventListener('click', () => applyStickerGroup(c.id));
                    chipsBox.appendChild(btn);
                });
                // 重绘后恢复横向滚动位置；选中的分组若在视野外（从「全部分组」跳转过来），再居中
                requestAnimationFrame(() => {
                    if (!chipsBox.clientWidth) return;
                    const maxScroll = Math.max(0, chipsBox.scrollWidth - chipsBox.clientWidth);
                    chipsBox.scrollLeft = Math.min(chipsScrollMemory, maxScroll);
                    const activeChip = chipsBox.querySelector('.ep-chip.active');
                    if (activeChip) {
                        const left = activeChip.offsetLeft;
                        const right = left + activeChip.offsetWidth;
                        if (left < chipsBox.scrollLeft || right > chipsBox.scrollLeft + chipsBox.clientWidth) {
                            const target = left - (chipsBox.clientWidth - activeChip.offsetWidth) / 2;
                            chipsBox.scrollLeft = Math.max(0, Math.min(target, maxScroll));
                        }
                    }
                    syncChipsThumb();
                });
            }

            // ---- 网格 ----
            if (epState.tab === 'mine' && !total) {
                const empty = document.createElement('div');
                empty.className = 'ep-empty';
                empty.textContent = q
                    ? epT('没有匹配的表情', 'No matching stickers')
                    : epT('还没有表情，点下面的「添加」或「批量导入」', 'Nothing here yet - use Add or Bulk import below');
                grid.appendChild(empty);
            } else if (epState.tab === 'sr' && !total) {
                const empty = document.createElement('div');
                empty.className = 'ep-empty';
                empty.textContent = q
                    ? epT('没有匹配的表情', 'No matching stickers')
                    : epT('这个分组里没有表情', 'This group is empty');
                grid.appendChild(empty);
            } else {
                const start = append ? Number(grid.dataset.rendered || 0) : 0;
                const slice = entries.slice(start);
                const frag = document.createDocumentFragment();
                slice.forEach(entry => {
                    if (entry.type === 'title') {
                        const t = document.createElement('div');
                        t.className = 'emoji-category-title';
                        t.textContent = entry.name;
                        frag.appendChild(t);
                    } else if (entry.builtin) {
                        frag.appendChild(makeBuiltinStickerTile(entry.builtin, entry.pack));
                    } else {
                        frag.appendChild(makeMineStickerTile(entry.sticker));
                    }
                });
                grid.appendChild(frag);
                grid.dataset.rendered = String(start + slice.length);
            }

            // ---- 底栏 ----
            if (epState.tab === 'mine') {
                const count = document.createElement('span');
                count.className = 'ep-count';
                count.textContent = q
                    ? epT(`匹配 ${total} 个`, `${total} matched`)
                    : epT(`共 ${total} 个`, `${total} in total`);
                foot.appendChild(count);

                const addBtn = document.createElement('button');
                addBtn.type = 'button';
                addBtn.className = 'ep-foot-btn';
                addBtn.innerHTML = '<i class="ri-add-line"></i>' + epT('添加', 'Add');
                addBtn.title = epT('添加图片链接表情', 'Add a sticker by image URL');
                addBtn.addEventListener('click', () => addStickerByUrl());
                foot.appendChild(addBtn);

                const batchBtn = document.createElement('button');
                batchBtn.type = 'button';
                batchBtn.className = 'ep-foot-btn';
                batchBtn.innerHTML = '<i class="ri-upload-2-line"></i>' + epT('批量导入', 'Import');
                batchBtn.title = epT('批量导入表情包（本地图片 / URL）', 'Bulk import stickers (local images / URLs)');
                batchBtn.addEventListener('click', () => batchImportStickers());
                foot.appendChild(batchBtn);
            } else {
                const tip = document.createElement('span');
                tip.className = 'ep-count';
                tip.textContent = total > entries.length
                    ? epT(`已显示 ${entries.length} / 共 ${total} 张 · 继续下滑加载`, `${entries.length} of ${total} - scroll for more`)
                    : epT(`共 ${total} 张 · 图源 米游社`, `${total} stickers - via HoYoLAB wiki`);
                foot.appendChild(tip);
                const pack = getBuiltinPacks().sr;
                if (pack && pack.source) {
                    const link = document.createElement('a');
                    link.className = 'ep-foot-btn';
                    link.href = pack.source;
                    link.target = '_blank';
                    link.rel = 'noopener noreferrer';
                    link.innerHTML = '<i class="ri-external-link-line"></i>' + epT('原词条', 'Source');
                    link.title = epT('在米游社查看原表情包词条', 'Open the original wiki entry');
                    foot.appendChild(link);
                }
            }
        }

        function makeMineStickerTile(stickerItem) {
            const item = document.createElement('div');
            item.className = 'ep-tile';
            const remark = String(stickerItem.remark || '');
            const groupName = stickerGroupName(stickerItem.group);
            item.title = [
                remark || epT('我的表情', 'My sticker'),
                groupName ? epT(`分组：${groupName}`, `Group: ${groupName}`) : '',
                epT('长按：分组 / 备注 / 删除', 'Long-press: group / note / delete')
            ].filter(Boolean).join('\n');

            const img = document.createElement('img');
            img.loading = 'lazy';
            img.decoding = 'async';
            img.alt = remark || epT('我的表情', 'My sticker');
            img.src = stickerItem.url;
            item.appendChild(img);

            item.addEventListener('click', () => {
                sendMessage(stickerItem.url, 'image');
                toggleEmojiPicker(false);
            });
            attachStickerLongPress(item, stickerItem.url);
            return item;
        }

        function makeBuiltinStickerTile(row, pack) {
            const item = document.createElement('div');
            item.className = 'ep-tile ep-tile-builtin';
            item.title = epT(`${row.remark}（${row.groupName}）\n长按：收藏到我的表情`,
                             `${row.remark} (${row.groupName})\nLong-press: save to My stickers`);
            item.dataset.remark = row.remark;

            const img = document.createElement('img');
            img.loading = 'lazy';
            img.decoding = 'async';
            img.alt = row.remark;
            img.src = builtinImageUrl(pack, row.path, 'thumb');
            img.addEventListener('error', () => {
                // 个别图不吃 OSS 参数：回退原图，别留白格子
                if (img.dataset.fb) return;
                img.dataset.fb = '1';
                img.src = pack.base + row.path;
            });
            item.appendChild(img);

            const sendUrl = builtinImageUrl(pack, row.path, 'send');
            item.addEventListener('click', () => {
                sendMessage(sendUrl, 'image');
                toggleEmojiPicker(false);
            });
            attachBuiltinStickerLongPress(item, row, pack);
            return item;
        }

        /** 长按内置表情：收藏进「我的表情」并选择分组 */
        function attachBuiltinStickerLongPress(el, row, pack) {
            let timer = null;
            let fired = false;
            const open = async (e) => {
                if (e && e.cancelable) e.preventDefault();
                fired = true;
                const groupId = await showStickerGroupSheet({
                    title: epT(`收藏「${row.remark}」到分组`, `Save "${row.remark}" to a group`),
                    current: '',
                    allowNew: true
                });
                if (groupId === undefined) return;
                const list = loadMyStickers();
                const url = builtinImageUrl(pack, row.path, 'send');
                if (list.some(s => s.url === url)) {
                    showToast(epT('这个表情已经在「我的表情」里了', 'Already in My stickers'), 'ri-information-line');
                    return;
                }
                list.push({ url, remark: row.remark, autoRemarked: false, group: groupId || '' });
                saveMyStickers(list);
                initEmojiPicker();
                showToast(groupId
                    ? epT(`已收藏到「${stickerGroupName(groupId)}」`, `Saved to "${stickerGroupName(groupId)}"`)
                    : epT('已收藏到「我的表情」', 'Saved to My stickers'), 'ri-star-line');
            };
            el.addEventListener('touchstart', (e) => {
                fired = false;
                timer = setTimeout(() => open(e), 550);
            }, { passive: true });
            ['touchend', 'touchmove', 'touchcancel'].forEach(ev =>
                el.addEventListener(ev, () => { clearTimeout(timer); timer = null; }));
            el.addEventListener('contextmenu', (e) => { e.preventDefault(); open(e); });
            el.addEventListener('click', (e) => {
                if (fired) { e.stopPropagation(); e.preventDefault(); fired = false; }
            }, true);
        }

        /** 「添加图片链接表情」入口（原实现内联在面板里，挪出来给底栏按钮用） */
        async function addStickerByUrl() {
            const url = await Dlg.prompt({
                title: epT('添加表情', 'Add sticker'),
                message: epT('请输入表情图片链接（http(s):// 直链）：', 'Paste a direct image URL (http(s)://):'),
                placeholder: 'https://…/sticker.png',
                okText: epT('添加', 'Add')
            });
            if (!url) return;
            const list = loadMyStickers();
            list.push({ url: url.trim(), remark: '', autoRemarked: false, group: '' });
            saveMyStickers(list);
            initEmojiPicker();
        }

        // ---- 分组选择浮层（长按「移动到分组」/ 收藏时共用） ----
        let stickerGroupSheetResolve = null;
        function showStickerGroupSheet(opts) {
            const options = opts || {};
            document.getElementById('sticker-group-sheet')?.remove();
            if (stickerGroupSheetResolve) { stickerGroupSheetResolve(undefined); stickerGroupSheetResolve = null; }

            return new Promise(resolve => {
                stickerGroupSheetResolve = resolve;
                const groups = loadStickerGroups();
                const sheet = document.createElement('div');
                sheet.id = 'sticker-group-sheet';
                sheet.className = 'ep-sheet';

                const title = document.createElement('div');
                title.className = 'ep-sheet-title';
                title.textContent = options.title || epT('选择分组', 'Choose group');
                sheet.appendChild(title);

                const listBox = document.createElement('div');
                listBox.className = 'ep-sheet-list';

                const addRow = (id, name, isCurrent) => {
                    const row = document.createElement('button');
                    row.type = 'button';
                    row.className = 'ep-sheet-row' + (isCurrent ? ' current' : '');
                    const icon = document.createElement('i');
                    icon.className = id ? 'ri-folder-line' : 'ri-inbox-line';
                    const text = document.createElement('span');
                    text.textContent = name;
                    row.append(icon, text);
                    if (isCurrent) {
                        const mark = document.createElement('i');
                        mark.className = 'ri-check-line ep-sheet-check';
                        row.appendChild(mark);
                    }
                    row.addEventListener('click', () => finish(id));
                    listBox.appendChild(row);
                };

                addRow('', epT('未分组', 'Ungrouped'), (options.current || '') === '');
                groups.forEach(g => addRow(g.id, g.name, options.current === g.id));

                if (options.allowNew !== false) {
                    const newRow = document.createElement('button');
                    newRow.type = 'button';
                    newRow.className = 'ep-sheet-row new';
                    newRow.innerHTML = '<i class="ri-add-line"></i><span>' + epT('新建分组…', 'New group…') + '</span>';
                    newRow.addEventListener('click', async () => {
                        const name = (await Dlg.prompt({
                            title: epT('新建表情分组', 'New sticker group'),
                            message: epT('给分组起个名字（例如：常用 / 开心 / 崩铁限定）：', 'Name this group (e.g. Favourites / Happy / Star Rail):'),
                            placeholder: epT('分组名称', 'Group name'),
                            maxLength: 20,
                            okText: epT('创建', 'Create')
                        }) || '').trim();
                        if (!name) return;
                        const all = loadStickerGroups();
                        if (all.some(g => g.name === name)) {
                            showToast(epT('已经有同名分组了', 'A group with that name already exists'), 'ri-error-warning-line');
                            return;
                        }
                        const g = { id: makeStickerGroupId(), name };
                        all.push(g);
                        saveStickerGroups(all);
                        finish(g.id);
                    });
                    listBox.appendChild(newRow);
                }
                sheet.appendChild(listBox);

                const cancel = document.createElement('button');
                cancel.type = 'button';
                cancel.className = 'ep-sheet-cancel';
                cancel.textContent = epT('取消', 'Cancel');
                cancel.addEventListener('click', () => finish(undefined));
                sheet.appendChild(cancel);

                document.body.appendChild(sheet);

                function finish(val) {
                    sheet.remove();
                    document.removeEventListener('click', onOutside, true);
                    if (stickerGroupSheetResolve === resolve) stickerGroupSheetResolve = null;
                    resolve(val);
                }
                function onOutside(e) {
                    if (!sheet.contains(e.target)) finish(undefined);
                }
                setTimeout(() => document.addEventListener('click', onOutside, true), 0);
            });
        }

        // ---- 分组管理 ----
        function openStickerGroupManager() {
            document.getElementById('sticker-group-manager')?.remove();
            const groups = loadStickerGroups();
            const stickers = loadMyStickers();

            const modal = document.createElement('div');
            modal.id = 'sticker-group-manager';
            modal.className = 'ep-modal';

            const card = document.createElement('div');
            card.className = 'ep-modal-card';

            const head = document.createElement('div');
            head.className = 'ep-modal-head';
            const h = document.createElement('strong');
            h.textContent = epT('表情分组', 'Sticker groups');
            const close = document.createElement('button');
            close.type = 'button';
            close.className = 'ep-icon';
            close.innerHTML = '<i class="ri-close-line"></i>';
            close.addEventListener('click', () => modal.remove());
            head.append(h, close);

            const body = document.createElement('div');
            body.className = 'ep-modal-body';

            const rebuild = () => {
                body.innerHTML = '';
                const fresh = loadStickerGroups();
                const all = loadMyStickers();
                if (!fresh.length) {
                    const empty = document.createElement('p');
                    empty.className = 'ep-empty';
                    empty.textContent = epT('还没有分组。建几个分组，找表情会快很多。', 'No groups yet. A few groups make finding stickers much faster.');
                    body.appendChild(empty);
                }
                fresh.forEach(g => {
                    const row = document.createElement('div');
                    row.className = 'ep-modal-row';
                    const name = document.createElement('span');
                    name.className = 'ep-modal-name';
                    name.textContent = g.name;
                    const num = document.createElement('em');
                    num.textContent = epT(`${all.filter(s => s.group === g.id).length} 个`, `${all.filter(s => s.group === g.id).length}`);
                    const rename = document.createElement('button');
                    rename.type = 'button';
                    rename.className = 'ep-icon';
                    rename.title = epT('重命名', 'Rename');
                    rename.innerHTML = '<i class="ri-edit-line"></i>';
                    rename.addEventListener('click', async () => {
                        const val = (await Dlg.prompt({
                            title: epT('重命名分组', 'Rename group'),
                            message: epT('输入新的分组名称：', 'New name for this group:'),
                            value: g.name,
                            maxLength: 20,
                            okText: epT('保存', 'Save')
                        }) || '').trim();
                        if (!val || val === g.name) return;
                        const list = loadStickerGroups();
                        if (list.some(x => x.name === val && x.id !== g.id)) {
                            showToast(epT('已经有同名分组了', 'A group with that name already exists'), 'ri-error-warning-line');
                            return;
                        }
                        const hit = list.find(x => x.id === g.id);
                        if (hit) hit.name = val;
                        saveStickerGroups(list);
                        rebuild();
                        initEmojiPicker();
                    });
                    const del = document.createElement('button');
                    del.type = 'button';
                    del.className = 'ep-icon danger';
                    del.title = epT('删除分组', 'Delete group');
                    del.innerHTML = '<i class="ri-delete-bin-line"></i>';
                    del.addEventListener('click', async () => {
                        const count = all.filter(s => s.group === g.id).length;
                        const ok = await Dlg.confirm({
                            title: epT('删除分组', 'Delete group'),
                            message: count
                                ? epT(`「${g.name}」里有 ${count} 个表情，删除分组后它们会回到「未分组」，表情本身不会丢。`,
                                      `"${g.name}" holds ${count} stickers. They will fall back to Ungrouped - nothing gets deleted.`)
                                : epT(`确定删除分组「${g.name}」吗？`, `Delete the group "${g.name}"?`),
                            okText: epT('删除', 'Delete'),
                            danger: true
                        });
                        if (!ok) return;
                        saveStickerGroups(loadStickerGroups().filter(x => x.id !== g.id));
                        // 组内表情回落到未分组，避免变成孤儿数据
                        const list = loadMyStickers();
                        let changed = false;
                        list.forEach(s => { if (s.group === g.id) { s.group = ''; changed = true; } });
                        if (changed) saveMyStickers(list);
                        rebuild();
                        initEmojiPicker();
                    });
                    row.append(name, num, rename, del);
                    body.appendChild(row);
                });

                const ungrouped = all.filter(s => !s.group || !fresh.some(g => g.id === s.group)).length;
                const tail = document.createElement('p');
                tail.className = 'ep-modal-hint';
                tail.textContent = epT(
                    `未分组：${ungrouped} 个 · 长按任意表情可以把它们分到组里。`,
                    `Ungrouped: ${ungrouped} - long-press any sticker to move it into a group.`);
                body.appendChild(tail);

                const addBtn = document.createElement('button');
                addBtn.type = 'button';
                addBtn.className = 'ep-modal-add';
                addBtn.innerHTML = '<i class="ri-add-line"></i>' + epT('新建分组', 'New group');
                addBtn.addEventListener('click', async () => {
                    const name = (await Dlg.prompt({
                        title: epT('新建表情分组', 'New sticker group'),
                        message: epT('给分组起个名字（例如：常用 / 开心 / 崩铁限定）：', 'Name this group (e.g. Favourites / Happy / Star Rail):'),
                        placeholder: epT('分组名称', 'Group name'),
                        maxLength: 20,
                        okText: epT('创建', 'Create')
                    }) || '').trim();
                    if (!name) return;
                    const list = loadStickerGroups();
                    if (list.some(g => g.name === name)) {
                        showToast(epT('已经有同名分组了', 'A group with that name already exists'), 'ri-error-warning-line');
                        return;
                    }
                    list.push({ id: makeStickerGroupId(), name });
                    saveStickerGroups(list);
                    rebuild();
                    initEmojiPicker();
                });
                body.appendChild(addBtn);
            };
            rebuild();

            card.append(head, body);
            modal.appendChild(card);
            modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
            document.body.appendChild(modal);
        }

        function initEmojiPicker() {
            if (!emojiPicker) return;
            // 关掉「自定义表情」开关时退回纯 emoji 字符网格（与原行为一致）
            if (!getFeatureToggles().showCustomStickers) {
                emojiPicker.classList.remove('ep-panel');
                emojiPicker.classList.add('ep-chars');
                emojiPicker.innerHTML = '';
                EMOJI_CHARS.forEach(emoji => {
                    const item = document.createElement('div');
                    item.classList.add('emoji-item');
                    item.textContent = emoji;
                    item.addEventListener('click', () => {
                        messageInput.value += emoji;
                        messageInput.focus();
                        toggleEmojiPicker(false);
                    });
                    emojiPicker.appendChild(item);
                });
                return;
            }
            // 一个自定义表情都没有时，直接落在内置表情页，别让用户看到空面板
            const hasCustom = loadMyStickers().length > 0;
            if (!hasCustom && getBuiltinPacks().sr) epState.tab = 'sr';
            buildEmojiPickerShell();
            renderEmojiPicker();
        }

        // 面板里不少文案是运行时拼的（共 N 个 / 已显示 X of Y），不走 i18n 短语表，
        // 切语言后得按新语言重画一遍。
        window.addEventListener('sitelangchange', () => {
            if (emojiPicker && emojiPicker.classList.contains('show')) initEmojiPicker();
        });

        // ========== 表情包管理工具函数（被长按菜单 / AI 调用逻辑共用） ==========
        function loadMyStickers() {
            let raw;
            try { raw = JSON.parse(localStorage.getItem('myStickers') || '[]'); }
            catch (e) { raw = []; }
            if (!Array.isArray(raw)) raw = [];
            const upgraded = raw.map(item => {
                if (typeof item === 'string') {
                    return { url: item, remark: '', autoRemarked: false, group: '' };
                }
                if (item && typeof item === 'object') {
                    return {
                        url: String(item.url || ''),
                        remark: String(item.remark || ''),
                        autoRemarked: Boolean(item.autoRemarked),
                        // 分组 id 为空表示「未分组」；组被删掉时渲染层会把它当未分组
                        group: String(item.group || '')
                    };
                }
                return null;
            }).filter(Boolean);
            if (raw.length && raw.some(i => typeof i === 'string')) {
                try { setLocalStorageSafely('myStickers', JSON.stringify(upgraded), '自定义表情'); } catch (e) {}
            }
            return upgraded;
        }

        function saveMyStickers(list) {
            setLocalStorageSafely('myStickers', JSON.stringify(list), '自定义表情');
        }

        // ========== 表情包批量导入 ==========
        // 支持两种来源：本地图片（可多选）与纯文本图片直链（每行一个）。
        // 一律先按 URL 去重，避免用户重复导入把列表撑成大杂烩。

        /** 从用户粘贴的文本里切出所有明显的图片链接（换行/空格/逗号都算分隔） */
        function parseStickerUrls(text) {
            return String(text || '')
                .split(/[\s,，;；]+/)
                .map(s => s.trim().replace(/^["'<]|["'>]$/g, ''))
                .filter(s => /^(https?:\/\/|data:image\/)/i.test(s));
        }

        /** 按 URL 去重（保留已有条目的备注） */
        function uniqueStickers(list) {
            const seen = new Set();
            const out = [];
            list.forEach(item => {
                const url = String(item && item.url || '').trim();
                if (!url || seen.has(url)) return;
                seen.add(url);
                out.push({ url, remark: String(item.remark || ''), autoRemarked: Boolean(item.autoRemarked), group: String(item.group || '') });
            });
            return out;
        }

        /** 本地图片 → dataURL。默认压到 512px 长边，勾了「不压缩图片」则保留原图。 */
        async function stickerFromFile(file) {
            if (!file || !/^image\//.test(file.type || '')) return null;
            if (window.ImageTools?.compress) {
                try { return await ImageTools.compress(file, 512, 0.85); } catch (e) { /* 回退原图 */ }
            }
            if (window.ImageTools?.readFileAsDataUrl) return await ImageTools.readFileAsDataUrl(file);
            return null;
        }

        /** 多选图片（用完即弃的临时 input，取消时用 window 焦点兜底） */
        function pickStickerFiles() {
            return new Promise(resolve => {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = 'image/*';
                input.multiple = true;
                input.style.display = 'none';
                document.body.appendChild(input);
                let settled = false;
                const finish = (files) => {
                    if (settled) return;
                    settled = true;
                    input.remove();
                    resolve(files || []);
                };
                input.addEventListener('change', () => finish(Array.from(input.files || [])));
                window.addEventListener('focus', () => setTimeout(() => finish([]), 600), { once: true });
                input.click();
            });
        }

        /** 合并写回并返回新增条数 */
        function commitImportedStickers(incoming) {
            const before = loadMyStickers();
            // 当前正停在某个分组里时，导入的表情直接进这个组，省得导入完再一个个搬
            const targetGroup = (epState.mineGroup && epState.mineGroup !== 'all' && epState.mineGroup !== 'ungrouped')
                ? epState.mineGroup
                : '';
            const withGroup = incoming.map(it => ({ ...it, group: it.group || targetGroup }));
            const merged = uniqueStickers([...before, ...withGroup]);
            const added = merged.length - before.length;
            if (added > 0) {
                saveMyStickers(merged);
                initEmojiPicker();
            }
            return added;
        }

        /** 表情面板上的「批量导入」入口 */
        async function batchImportStickers() {
            const picked = await Dlg.choice({
                title: '批量导入表情包',
                message: '选择导入方式：本地图片会压缩后保存（可多选）；URL 每行一个，也支持用空格或逗号分隔。',
                buttons: [
                    { label: '选择本地图片', value: 'file', icon: 'ri-image-add-line', primary: true },
                    { label: '粘贴图片 URL', value: 'url', icon: 'ri-link' }
                ]
            });
            if (!picked) return;

            if (picked === 'file') {
                const files = await pickStickerFiles();
                if (!files.length) return;
                showToast(`正在处理 ${files.length} 张图片…`, 'ri-loader-4-line');
                const incoming = [];
                for (const file of files) {
                    try {
                        const url = await stickerFromFile(file);
                        if (url) incoming.push({ url, remark: '', autoRemarked: false });
                    } catch (e) { /* 单张失败不影响其它 */ }
                }
                const added = commitImportedStickers(incoming);
                showToast(added ? `已导入 ${added} 个表情包` : '没有新增表情包（可能已存在）', added ? 'ri-check-line' : 'ri-information-line');
                return;
            }

            const text = await Dlg.prompt({
                title: '批量导入表情包',
                message: '每行一个图片直链（https://… 或 data:image/…）：',
                multiline: true,
                placeholder: 'https://a.com/1.png\nhttps://a.com/2.gif',
                okText: '导入'
            });
            if (!text) return;
            const urls = parseStickerUrls(text);
            if (!urls.length) {
                showToast('没有识别到有效的图片链接', 'ri-error-warning-line');
                return;
            }
            const added = commitImportedStickers(urls.map(url => ({ url, remark: '', autoRemarked: false })));
            showToast(added ? `已导入 ${added} 个表情包` : '这些链接都已经添加过了', added ? 'ri-check-line' : 'ri-information-line');
        }
        window.batchImportStickers = batchImportStickers;

        function findMyStickerIndex(list, url) {
            return list.findIndex(s => s.url === url);
        }

        function attachStickerLongPress(el, url) {
            if (!el) return;
            let pressTimer = null;
            let triggered = false;
            const start = (e) => {
                triggered = false;
                pressTimer = setTimeout(() => {
                    triggered = true;
                    if (e && e.cancelable) e.preventDefault();
                    showStickerContextMenu(el, url);
                }, 550);
            };
            const cancel = () => { clearTimeout(pressTimer); pressTimer = null; };
            el.addEventListener('touchstart', start, { passive: true });
            el.addEventListener('touchend', cancel);
            el.addEventListener('touchmove', cancel);
            el.addEventListener('touchcancel', cancel);
            el.addEventListener('contextmenu', (e) => {
                e.preventDefault();
                showStickerContextMenu(el, url);
            });
            el.addEventListener('click', (e) => {
                if (triggered) { e.stopPropagation(); e.preventDefault(); triggered = false; }
            }, true);
        }

        function showStickerContextMenu(targetEl, stickerUrl) {
            document.getElementById('sticker-context-menu')?.remove();
            const stickers = loadMyStickers();
            const idx = findMyStickerIndex(stickers, stickerUrl);
            if (idx < 0) return;
            const hasRemark = !!stickers[idx].remark;

            const menu = document.createElement('div');
            menu.id = 'sticker-context-menu';
            menu.style.cssText = `
                position: fixed;
                background: #1a1c23;
                border: 1px solid #444;
                border-radius: 10px;
                box-shadow: 0 12px 32px rgba(0,0,0,0.45);
                padding: 6px 0;
                z-index: 11000;
                min-width: 200px;
                color: #eee;
                font-size: 14px;
            `;
            const makeItem = (icon, text, danger, onClick) => {
                const item = document.createElement('div');
                item.style.cssText = `
                    display: flex;
                    align-items: center;
                    gap: 8px;
                    padding: 10px 14px;
                    cursor: pointer;
                    transition: background 0.15s;
                    color: ${danger ? '#ff7878' : '#eee'};
                `;
                // 【XSS 修复】text 必须转义。
                // 其中一个菜单项的文字是 `修改备注（当前：${stickers[idx].remark}）`，
                // 而 remark 有两个来源：用户手输（无任何过滤）与 AI 自动识图备注
                //（chat.js ensureStickerRemarks 只滤了标点，**没有滤 & 与引号**）。
                // 直接把 remark 插进 innerHTML，等于把 localStorage 里的字符串当 HTML 执行：
                // 备注写成 <img src=x onerror=...> 就会在打开长按菜单时跑任意脚本，
                // 而导入别人的表情包配置也能带着这个备注进来。
                item.innerHTML = `<i class="${icon}"></i><span>${escapeHtml(text)}</span>`;
                item.addEventListener('mouseenter', () => item.style.background = 'rgba(230,199,138,0.12)');
                item.addEventListener('mouseleave', () => item.style.background = '');
                item.addEventListener('click', (e) => {
                    e.stopPropagation();
                    menu.remove();
                    onClick();
                });
                return item;
            };

            menu.appendChild(makeItem(
                'ri-folder-line',
                stickers[idx].group
                    ? epT(`移动到分组（当前：${stickerGroupName(stickers[idx].group) || '未分组'}）`,
                          `Move to group (now: ${stickerGroupName(stickers[idx].group) || 'Ungrouped'})`)
                    : epT('移动到分组', 'Move to group'),
                false,
                async () => {
                    const current = stickers[idx].group || '';
                    const picked = await showStickerGroupSheet({
                        title: epT('移动到分组', 'Move to group'),
                        current,
                        allowNew: true
                    });
                    if (picked === undefined || picked === current) return;
                    // 重读一次：浮层里可能顺手新建了分组
                    const list = loadMyStickers();
                    const at = findMyStickerIndex(list, stickerUrl);
                    if (at < 0) return;
                    list[at].group = picked;
                    saveMyStickers(list);
                    initEmojiPicker();
                    showToast(picked
                        ? epT(`已移到「${stickerGroupName(picked)}」`, `Moved to "${stickerGroupName(picked)}"`)
                        : epT('已移到「未分组」', 'Moved to Ungrouped'), 'ri-folder-line');
                }
            ));

            menu.appendChild(makeItem(
                'ri-edit-line',
                hasRemark ? `修改备注（当前：${stickers[idx].remark}）` : '添加备注',
                false,
                async () => {
                    const newRemark = (await Dlg.prompt({
                        title: hasRemark ? '修改表情备注' : '添加表情备注',
                        message: '备注会显示在表情的悬浮提示里，留空则清除：',
                        value: stickers[idx].remark || '',
                        placeholder: '例如：惊讶',
                        maxLength: 30,
                        okText: '保存'
                    }) || '').trim();
                    stickers[idx].remark = newRemark;
                    stickers[idx].autoRemarked = false;
                    saveMyStickers(stickers);
                    initEmojiPicker();
                    if (typeof showToast === 'function') showToast(newRemark ? '备注已更新' : '备注已清除', 'ri-edit-line');
                }
            ));

            menu.appendChild(makeItem(
                'ri-delete-bin-line',
                '删除该表情',
                true,
                async () => {
                    if (!await Dlg.confirm({ title: '删除表情', message: '确定删除这个表情包吗？', okText: '删除', danger: true })) return;
                    stickers.splice(idx, 1);
                    saveMyStickers(stickers);
                    initEmojiPicker();
                    if (typeof showToast === 'function') showToast('表情已删除', 'ri-delete-bin-line');
                }
            ));

            document.body.appendChild(menu);
            const rect = targetEl.getBoundingClientRect();
            const menuWidth = 220;
            const menuHeight = 100;
            let left = rect.left + rect.width / 2 - menuWidth / 2;
            let top = rect.bottom + 8;
            left = Math.max(8, Math.min(window.innerWidth - menuWidth - 8, left));
            if (top + menuHeight > window.innerHeight) top = rect.top - menuHeight - 8;
            menu.style.left = left + 'px';
            menu.style.top = top + 'px';

            setTimeout(() => {
                const off = (e) => {
                    if (!menu.contains(e.target)) {
                        menu.remove();
                        document.removeEventListener('click', off, true);
                        document.removeEventListener('touchstart', off, true);
                    }
                };
                document.addEventListener('click', off, true);
                document.addEventListener('touchstart', off, true);
            }, 0);
        }

        // 暴露工具函数给其他模块（AI 调用 / 自动备注等会用到）
        window.loadMyStickers = loadMyStickers;
        window.saveMyStickers = saveMyStickers;
        window.findMyStickerIndex = findMyStickerIndex;
        window.showStickerContextMenu = showStickerContextMenu;
        window.attachStickerLongPress = attachStickerLongPress;

        // ========== 表情包占位符解析（AI → 表情气泡） ==========
        // 协议：AI 输出中可以出现 [sticker:N] / [[sticker:N]] 这样的占位符，N 是表情在用户「我的表情」中的下标。
        // 返回 { segments: [{type:'text'|'sticker', content|sticker}], hasSticker: boolean }
        // 注意：正则严格要求成对闭合，避免「[sticker:0」+「]]」这种切分导致 URL 残留。
        const STICKER_PLACEHOLDER_REGEX = /\[+\s*sticker\s*:\s*(\d+)\s*\]+/gi;
        function parseStickerPlaceholders(text, stickerList) {
            if (!text || !Array.isArray(stickerList) || !stickerList.length) {
                return { segments: text ? [{ type: 'text', content: text }] : [], hasSticker: false };
            }
            const segments = [];
            let lastIndex = 0;
            let m;
            let found = false;
            // 每次 exec 前重置 lastIndex，防止全局正则跨调用残留
            STICKER_PLACEHOLDER_REGEX.lastIndex = 0;
            while ((m = STICKER_PLACEHOLDER_REGEX.exec(text)) !== null) {
                const idx = parseInt(m[1], 10);
                if (idx >= 0 && idx < stickerList.length) {
                    found = true;
                    if (m.index > lastIndex) segments.push({ type: 'text', content: text.slice(lastIndex, m.index) });
                    segments.push({ type: 'sticker', sticker: stickerList[idx] });
                    lastIndex = m.index + m[0].length;
                }
            }
            if (!found) {
                return { segments: [{ type: 'text', content: text }], hasSticker: false };
            }
            if (lastIndex < text.length) segments.push({ type: 'text', content: text.slice(lastIndex) });
            return { segments, hasSticker: true };
        }

        // 把 AI 输出按表情包占位符 + 分段设置拆分成若干气泡。
        // enableSegmentation=true：每个 sticker 单独成段，文本片段也单独成段。
        // enableSegmentation=false：sticker 插入原位置，文本包夹在中间。
        function splitAiOutputWithStickers(rawText, stickerList, enableSegmentation) {
            if (!rawText) return [];
            const { segments, hasSticker } = parseStickerPlaceholders(rawText, stickerList);
            if (!hasSticker) {
                return [{ type: 'text', content: rawText }];
            }
            if (enableSegmentation) {
                const out = [];
                segments.forEach(seg => {
                    if (seg.type === 'text') {
                        const t = seg.content.trim();
                        if (t) out.push({ type: 'text', content: t });
                    } else {
                        out.push({ type: 'sticker', sticker: seg.sticker });
                    }
                });
                return out;
            }
            const out = [];
            let buf = '';
            const flush = () => {
                const t = buf.trim();
                if (t) out.push({ type: 'text', content: t });
                buf = '';
            };
            segments.forEach(seg => {
                if (seg.type === 'text') buf += seg.content;
                else { flush(); out.push({ type: 'sticker', sticker: seg.sticker }); }
            });
            flush();
            return out;
        }

        // 去掉 AI 输出中已解析为表情包的占位符文字（避免重复显示）
        // 同步使用同一套严格闭合的正则，避免剥离不彻底导致 URL 残留。
        function stripStickerPlaceholders(text) {
            if (!text) return text;
            return text.replace(/\[+\s*sticker\s*:\s*\d+\s*\]+/gi, '').trim();
        }

        // 根据聊天设置生成用于界面展示的 AI 文本。原始回复仍会保存到聊天记录，
        // 因此重新开启「显示思考过程」后，历史消息也可以恢复显示。
        function getDisplayableAiText(text, settings = null) {
            const value = String(text ?? '');
            const chatSettings = settings || (typeof getChatSettings === 'function' ? getChatSettings() : {});
            // [emo:xxx] 是视觉小说模式用的内部控制标记，任何界面下都不该露出来，
            // 所以这一层剥离放在「是否显示思考过程」之前，两种设置下都生效。
            // 同时吃掉流式阶段「刚敲了一半」的标记（如 [emo:hap），否则它会闪现在气泡里。
            // [AFF:n] 是好感度「AI 自主判定」的标记，同理：正常路径下 chat.js 已经
            // 在入库前就吃掉了，这里是第二道保险 —— 历史消息、重新生成、导出、
            // 以及任何绕过 chat.js 的渲染路径都不会把它露给用户。
            const stripped = value
                .replace(/\[\s*(?:emo|emotion|情绪)\s*[:：]\s*[a-zA-Z\u4e00-\u9fa5]{2,12}\s*\]/gi, '')
                .replace(/\[\s*(?:emo|emotion|情绪)\s*[:：][a-zA-Z\u4e00-\u9fa5]{0,12}$/i, '')
                .replace(/\[\s*AFF\s*[:：]\s*-?\d+(?:\.\d+)?\s*\]/gi, '')
                .replace(/\[\s*AFF\s*[:：]?\s*-?\d*$/i, '');
            if (chatSettings.showThinkingProcess !== false) return stripped;

            // 兼容标准 <thinking>...</thinking> / <think>...</think>，以及部分模型误用的
            // <thinking>...<thinking> 成对分隔格式；流式尚未闭合时也会先隐藏至当前末尾。
            return stripped
                .replace(/<(thinking|think)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|<\1\b[^>]*>)/gi, '')
                .replace(/<(thinking|think)\b[^>]*>[\s\S]*$/gi, '')
                .trim();
        }

        window.parseStickerPlaceholders = parseStickerPlaceholders;
        window.splitAiOutputWithStickers = splitAiOutputWithStickers;
        window.stripStickerPlaceholders = stripStickerPlaceholders;
        window.getDisplayableAiText = getDisplayableAiText;

        /* ==================== 模型思考过程（reasoning）====================
           推理模型（DeepSeek-R1 / QwQ / o 系列，以及各家中转站的「深度思考」开关）
           会把思考内容放在响应的 reasoning_content 字段里，与正文 content 分开返回。
           chat.js 负责采集并随消息一起入库（msg.reasoning），本函数只负责把它
           渲染成一个可折叠的块：「已思考（用时 N 秒）」+ 展开后的思考正文。
           注意：思考内容只用于显示，发送历史时仍然只取 content —— 不会多占上下文。
 */
        function reasoningDurationText(ms) {
            const n = Number(ms);
            if (!Number.isFinite(n) || n <= 0) return '';
            const seconds = n / 1000;
            return seconds < 10 ? `${seconds.toFixed(1)} 秒` : `${Math.round(seconds)} 秒`;
        }

        /** 「显示模型的思考过程」开关（默认开：只有当模型真的返回了思考才出现，无副作用） */
        function reasoningPanelEnabled(settings) {
            const cs = settings || (typeof getChatSettings === 'function' ? getChatSettings() : {});
            return cs.showReasoningPanel !== false;
        }

        function buildReasoningBlock(reasoning, ms, options = {}) {
            const text = String(reasoning || '').trim();
            if (!text) return null;
            const panel = document.createElement('div');
            panel.className = 'reasoning-block' + (options.streaming ? ' streaming' : '');

            const head = document.createElement('button');
            head.type = 'button';
            head.className = 'reasoning-head';
            head.setAttribute('aria-label', '展开或收起模型的思考过程');
            const duration = reasoningDurationText(ms);
            const titleText = options.streaming ? '正在思考…' : (duration ? `已思考（用时 ${duration}）` : '已思考');
            head.innerHTML = '<i class="ri-sparkling-2-line"></i>'
                + `<span class="reasoning-title">${titleText}</span>`
                + '<i class="ri-arrow-down-s-line reasoning-chevron"></i>';

            const body = document.createElement('div');
            body.className = 'reasoning-body';
            body.textContent = text;

            panel.appendChild(head);
            panel.appendChild(body);
            // 默认展开（与各家 App 的行为一致）；传 { expanded: false } 则默认收起
            if (options.expanded === false) panel.classList.add('collapsed');
            head.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                panel.classList.toggle('collapsed');
            });
            return panel;
        }

        /** 从任意端点返回的 reasoning 字段里取出纯文本（兼容字符串 / 数组 / 对象） */
        function normalizeReasoningValue(src) {
            if (!src) return '';
            if (typeof src === 'string') return src;
            if (Array.isArray(src)) {
                return src.map(item => (typeof item === 'string' ? item : (item?.text || item?.content || ''))).join('');
            }
            if (typeof src === 'object') return String(src.text || src.content || src.reasoning || '');
            return '';
        }

        window.buildReasoningBlock = buildReasoningBlock;
        window.reasoningPanelEnabled = reasoningPanelEnabled;
        window.reasoningDurationText = reasoningDurationText;
        window.normalizeReasoningValue = normalizeReasoningValue;

        function toggleEmojiPicker(show) {
            const willShow = show === undefined ? !emojiPicker.classList.contains('show') : !!show;
            // 每次打开都重建一次：分组、收藏、备注可能在别处改过（长按菜单 / 分组管理）
            if (willShow) {
                epState.query = '';
                epState.srPage = EP_PAGE_SIZE;
                const oldInput = emojiPicker.querySelector('#ep-search');
                if (oldInput) oldInput.value = '';
                initEmojiPicker();
            }
            if (show === undefined) emojiPicker.classList.toggle('show');
            else show ? emojiPicker.classList.add('show') : emojiPicker.classList.remove('show');
            // 重建时面板可能还是 display:none（量不到宽度），显示出来后再同步一次滚动条
            if (emojiPicker.classList.contains('show')) requestAnimationFrame(syncChipsThumb);
        }

        function toggleMenuElement(menu, show) {
            if (!menu) return;
            const shouldShow = show === undefined ? !menu.classList.contains('show') : show;
            menu.classList.toggle('show', shouldShow);
            menu.hidden = !shouldShow;
        }

        function toggleAvatarMenu(show) {
            toggleMenuElement(avatarContextMenu, show);
        }

        // 记录角色头像菜单的打开时刻：部分浏览器/输入法会在打开菜单的同一帧
        // 再补一次 document 级 click，把刚打开的菜单立刻关掉（表现为「点了没反应」）。
        let aiAvatarMenuOpenedAt = 0;

        function toggleAiAvatarMenu(show) {
            // 打开前根据当前角色是否改过头像决定「恢复默认头像」是否可见，
            // 避免用户看到一条点了没用的菜单项。
            if (show === true) {
                syncAiMenuResetVisibility(currentAiAvatarTarget);
                aiAvatarMenuOpenedAt = Date.now();
            }
            toggleMenuElement(aiAvatarContextMenu, show);
        }

        function syncAiMenuResetVisibility(targetId) {
            if (!aiMenuResetAvatar) return;
            const isGroup = Boolean(targetId && friendsData[targetId]?.isGroup);
            // 群聊头像的「是否自定义」看 groupManager 里有没有单独存过头像，
            // 不能走 isFriendAvatarCustomized（群不是内置角色，永远返回 false）。
            const customized = isGroup
                ? Boolean(groupManager[targetId]?.avatar)
                : (Boolean(targetId) && isFriendAvatarCustomized(targetId));
            aiMenuResetAvatar.style.display = customized ? 'flex' : 'none';
            // 「解散群聊」只在群聊头像的菜单里出现
            if (aiMenuDisbandGroup) aiMenuDisbandGroup.style.display = isGroup ? 'flex' : 'none';
        }

        function toggleFriendContextMenu(show) {
            toggleMenuElement(friendContextMenu, show);
        }


        function toggleFriendGroupModal(show) {
            if (show === undefined) {
                friendGroupModal.classList.toggle('show');
            } else {
                show ? friendGroupModal.classList.add('show') : friendGroupModal.classList.remove('show');
            }
        }

        inputAvatar?.addEventListener('click', (e) => {
            e.stopPropagation();
            toggleAvatarMenu(true);
        });

        menuUploadFile?.addEventListener('click', () => {
            toggleAvatarMenu(false);
            avatarUpload.click();
        });

        // 统一的头像处理入口：读文件 → 允许用户裁切 → 返回最终图片
        // 用户不裁切时直接使用完整原图（见 image-tools.js 的实现）
        async function pickAndCropAvatar(file, title) {
            if (!file) return null;
            if (!/^image\//.test(file.type || '')) {
                showToast('请选择图片文件', 'ri-error-warning-line');
                return null;
            }
            try {
                const raw = await ImageTools.readFileAsDataUrl(file);
                if (!window.ImageTools?.cropImage) return raw;
                return await ImageTools.cropImage(raw, { title: title || '裁切头像' });
            } catch (error) {
                showToast(`图片处理失败：${error.message || error}`, 'ri-error-warning-line');
                return null;
            }
        }

        /**
         * 弹一个临时 file 选择器并等用户选完。
         * 不用页面上那个 hidden 的 #avatar-upload / #friend-avatar-upload：
         * 那几个 input 的 onchange 会被多处改写，切换目标时容易互相覆盖；
         * 临时 input 用完即弃，不存在这种冲突。用户在系统选择器里取消时
         * 不会触发 change，用 window 重新获得焦点兜底，不让 Promise 悬着。
         */
        function pickImageFile() {
            return new Promise(resolve => {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = 'image/*';
                input.style.display = 'none';
                document.body.appendChild(input);
                let settled = false;
                const finish = (file) => {
                    if (settled) return;
                    settled = true;
                    input.remove();
                    resolve(file || null);
                };
                input.addEventListener('change', () => finish((input.files || [])[0]));
                window.addEventListener('focus', () => setTimeout(() => finish(null), 600), { once: true });
                input.click();
            });
        }

        /**
         * 「更换头像」的统一入口。
         * 旧实现是点一下再弹出第二个小菜单（本地文件 / 网络 URL），
         * 两个 fixed 菜单叠在一起，第二个菜单的点击很容易被 document 上的
         * 「点空白处关闭菜单」监听吃掉，用户看到的就是「点了没反应」。
         * 现在直接用站内对话框选来源，点完必定有反馈，桌面与手机同一套行为。
         */
        async function chooseFriendAvatarSource(friendId) {
            if (!friendId || !friendsData[friendId]) return;
            const isGroup = Boolean(friendsData[friendId].isGroup);
            const source = await Dlg.choice({
                title: isGroup ? '更换群头像' : '更换头像',
                message: isGroup
                    ? `为群聊「${getFriendDisplayName(friendId)}」更换头像（只影响群聊容器，不改成员头像）：`
                    : `为「${getFriendDisplayName(friendId)}」更换头像：`,
                buttons: [
                    { label: '从本地图片上传', value: 'file', icon: 'ri-upload-cloud-2-line', primary: true },
                    { label: '使用网络 URL', value: 'url', icon: 'ri-link' },
                    ...(isGroup && groupManager[friendId]?.avatar
                        ? [{ label: '恢复默认群头像', value: 'reset', icon: 'ri-refresh-line' }]
                        : [])
                ]
            });
            if (!source) return;
            if (source === 'reset') { restoreGroupAvatar(friendId); return; }
            if (source === 'file') {
                const file = await pickImageFile();
                if (!file) return;
                const avatar = await pickAndCropAvatar(file, '裁切角色头像');
                if (avatar) updateFriendAvatar(friendId, avatar);
                return;
            }
            const url = await Dlg.prompt({
                title: '设置角色头像',
                message: '请输入头像图片的 URL 地址：',
                value: /^data:/i.test(friendsData[friendId]?.avatar || '') ? '' : (friendsData[friendId]?.avatar || ''),
                placeholder: 'https://…/avatar.png',
                okText: '下一步'
            });
            if (!url || url.trim() === '') return;
            const target = url.trim();
            if (window.ImageTools?.cropImage && !target.startsWith('data:')) {
                try {
                    const cropped = await ImageTools.cropUrl(target, { title: '裁切角色头像' });
                    if (cropped === null) return;      // 用户取消
                    updateFriendAvatar(friendId, cropped);
                    return;
                } catch (e) { /* 加载失败：退回原链接 */ }
            }
            updateFriendAvatar(friendId, target);
        }

        menuSetUrl?.addEventListener('click', async () => {
            toggleAvatarMenu(false);
            const url = await Dlg.prompt({
                title: '设置我的头像',
                message: '请输入头像图片的 URL 地址：',
                value: /^data:/i.test(inputAvatar.src) ? '' : inputAvatar.src,
                placeholder: 'https://…/avatar.png',
                okText: '下一步'
            });
            if (!url || url.trim() === '') return;
            const target = url.trim();
            if (window.ImageTools?.cropImage && !target.startsWith('data:')) {
                try {
                    const cropped = await ImageTools.cropUrl(target, { title: '裁切我的头像' });
                    if (cropped === null) return;      // 用户取消
                    updateMyAvatar(cropped);
                    return;
                } catch (e) { /* 加载失败：退回原链接 */ }
            }
            updateMyAvatar(target);
        });

        aiMenuUploadFile?.addEventListener('click', async () => {
            toggleAiAvatarMenu(false);
            const targetFriendId = currentAiAvatarTarget || currentFriendMenuTarget;
            if (!targetFriendId) return;
            const file = await pickImageFile();
            if (!file) return;
            const avatar = await pickAndCropAvatar(file, '裁切角色头像');
            if (avatar) updateFriendAvatar(targetFriendId, avatar);
        });

        aiMenuSetUrl?.addEventListener('click', async () => {
            toggleAiAvatarMenu(false);
            // 先捕获目标 id：await 期间 currentAiAvatarTarget 可能被其它操作改掉
            const targetId = currentAiAvatarTarget;
            if (!targetId) return;
            const url = await Dlg.prompt({
                title: '设置角色头像',
                message: '请输入头像图片的 URL 地址：',
                value: /^data:/i.test(friendsData[targetId]?.avatar || '') ? '' : (friendsData[targetId]?.avatar || ''),
                placeholder: 'https://…/avatar.png',
                okText: '下一步'
            });
            if (!url || url.trim() === '') return;
            const target = url.trim();
            if (window.ImageTools?.cropImage) {
                const cropped = await ImageTools.cropUrl(target, { title: '裁切角色头像' });
                if (cropped === null) return;
                updateFriendAvatar(targetId, cropped);
                return;
            }
            updateFriendAvatar(targetId, target);
        });

        // 身份互换时,「我的头像」应更新到 AI 发言一侧(真人一侧显示的是 AI 头像)
        function myAvatarSelector() {
            return document.body.classList.contains('identity-swap')
                ? '.message[data-role="other"] .avatar'
                : '.message[data-role="mine"] .avatar';
        }
        function updateMyAvatar(src) {
            inputAvatar.src = src;
            document.querySelectorAll(myAvatarSelector()).forEach(img => {
                img.src = src;
            });
            setLocalStorageSafely('userAvatar', src, '用户头像');
            showToast("头像已更新", "ri-check-line");
        }

        function updateFriendAvatar(friendId, src) {
            if (!friendsData[friendId] || !src) return;
            // 群聊容器的头像走独立存储（groupManager[].avatar），
            // 否则会被 registerGroupFriend 按「第一个成员的头像」覆盖掉，刷新就白改。
            if (friendsData[friendId].isGroup) { updateGroupAvatar(friendId, src); return; }
            const friend = friendsData[friendId];
            if (friend.isCustom && !friend.defaultAvatar) friend.defaultAvatar = friend.avatar;
            friend.avatar = src;
            if (friend.isCustom) {
                saveCustomFriendsData();
            } else {
                const overrides = getStoredFriendAvatarOverrides();
                if (src === getDefaultFriendAvatar(friendId)) delete overrides[friendId];
                else overrides[friendId] = src;
                saveStoredFriendAvatarOverrides(overrides);
            }
            Object.values(groupManager).forEach(group => {
                // 只有「群头像还没被用户单独设置过」时才跟随第一个成员，否则用户
                // 给群设的头像会被成员换头像的动作覆盖掉（表现为“群头像白换了”）。
                if (group.memberIds?.[0] === friendId && friendsData[group.id] && !group.avatar) friendsData[group.id].avatar = src;
            });
            // 群聊容器头像跟随第一个成员（保持原有行为）
            if (currentFriendId === friendId || getMessages().some(msg => msg.friendId === friendId)) {
                currentFriendNameElement.textContent = getFriendDisplayName(currentFriendId);
                // 性能优化：只增量更新已渲染消息中的头像，避免全量重绘
                updateRenderedMessagesAppearance(friendId);
            } else {
                // 即使当前不在这个角色的聊天里，群聊头像也要跟上
                updateRenderedMessagesAppearance(friendId);
            }
            renderFriendList();
            showToast(`${getFriendDisplayName(friendId)} 的头像已更新`, "ri-check-line");
        }

        function restoreFriendAvatar(friendId) {
            if (!friendsData[friendId]) return;
            const defaultAvatar = getDefaultFriendAvatar(friendId);
            friendsData[friendId].avatar = defaultAvatar;
            if (friendsData[friendId].isCustom) saveCustomFriendsData();
            const overrides = getStoredFriendAvatarOverrides();
            delete overrides[friendId];
            saveStoredFriendAvatarOverrides(overrides);
            updateRenderedMessagesAppearance(friendId);
            renderFriendList();
            showToast(`${getFriendDisplayName(friendId)} 的头像已恢复默认`, 'ri-refresh-line');
        }

        // ========== 群聊头像 ==========
        // 群聊容器的头像单独存在 groupManager[groupId].avatar：
        // 不能只写 friendAvatarOverrides —— 那份覆盖数据每次启动都会被 registerGroupFriend
        // 用「第一个成员的头像」重算，刷新之后用户改的群头像就没了。
        function updateGroupAvatar(groupId, src) {
            const group = groupManager[groupId];
            if (!group || !friendsData[groupId] || !src) return;
            group.avatar = src;
            friendsData[groupId].avatar = src;
            saveGroupManager();
            updateRenderedMessagesAppearance(groupId);
            renderFriendList();
            showToast(`群聊「${group.name || '群聊'}」头像已更新`, 'ri-check-line');
        }

        function restoreGroupAvatar(groupId) {
            const group = groupManager[groupId];
            if (!group) return;
            delete group.avatar;
            saveGroupManager();
            // 重新按第一个成员的头像生成（与创建群聊时的默认行为一致）
            registerGroupFriend(group);
            renderFriendList();
            showToast(`群聊「${group.name || '群聊'}」头像已恢复默认`, 'ri-refresh-line');
        }

        aiMenuResetAvatar?.addEventListener('click', () => {
            const targetId = currentAiAvatarTarget;
            toggleAiAvatarMenu(false);
            if (!targetId) return;
            if (friendsData[targetId]?.isGroup) restoreGroupAvatar(targetId);
            else restoreFriendAvatar(targetId);
        });

        function getFriendDisplayName(friendId) {
            const friend = friendsData[friendId];
            if (!friend) return '';
            const remark = getFriendRemark(friendId);
            return remark || friend.name;
        }

        function getFriendRemark(friendId) {
            const settings = readJson('friendSettings', {}, '好友设置');
            return settings[friendId]?.remark || '';
        }

        function setFriendRemark(friendId, remark) {
            const settings = readJson('friendSettings', {}, '好友设置');
            if (!settings[friendId]) settings[friendId] = {};
            settings[friendId].remark = remark;
            setLocalStorageSafely('friendSettings', JSON.stringify(settings));
        }

        function isFriendPinned(friendId) {
            const settings = readJson('friendSettings', {}, '好友设置');
            return settings[friendId]?.pinned || false;
        }

        function setFriendPinned(friendId, pinned) {
            const settings = readJson('friendSettings', {}, '好友设置');
            if (!settings[friendId]) settings[friendId] = {};
            settings[friendId].pinned = pinned;
            setLocalStorageSafely('friendSettings', JSON.stringify(settings));
        }

        function getFriendGroup(friendId) {
            const settings = readJson('friendSettings', {}, '好友设置');
            return settings[friendId]?.group || friendsData[friendId]?.group || '默认';
        }

        function setFriendGroup(friendId, groupName) {
            if (!friendsData[friendId]) return;
            friendsData[friendId].group = groupName;
            const settings = readJson('friendSettings', {}, '好友设置');
            if (!settings[friendId]) settings[friendId] = {};
            settings[friendId].group = groupName;
            setLocalStorageSafely('friendSettings', JSON.stringify(settings));
            if (friendsData[friendId].isCustom) saveCustomFriendsData();
        }

        function renameFriendGroup(oldName, newName) {
            const targetName = (newName || '').trim();
            if (!targetName || targetName === oldName) return;
            Object.keys(friendsData).forEach(friendId => {
                if (getFriendGroup(friendId) === oldName) setFriendGroup(friendId, targetName);
            });
            renderFriendList();
            showToast(`分组已重命名为「${targetName}」`, 'ri-folder-settings-line');
        }

        // ---------- 分组的「存在」不再只靠 friendsData 反推 ----------
        // 原来分组列表 = 硬编码几个 + 角色当前所在组，用户新建一个还没放角色的
        // 空分组，刷新后就消失了。这里补一份 localStorage 自建分组清单（删除时同步移除）。
        const CUSTOM_GROUPS_KEY = 'customFriendGroups';
        const DEFAULT_GROUP_NAME = '默认';

        function readCustomGroups() {
            const list = readJson(CUSTOM_GROUPS_KEY, [], '自建分组');
            return Array.isArray(list) ? list.map(g => String(g || '').trim()).filter(Boolean) : [];
        }

        function writeCustomGroups(list) {
            const uniq = Array.from(new Set((list || []).map(g => String(g || '').trim()).filter(Boolean)));
            setLocalStorageSafely(CUSTOM_GROUPS_KEY, JSON.stringify(uniq), '自建分组');
            return uniq;
        }

        function addCustomGroup(name) {
            const target = String(name || '').trim();
            if (!target || readCustomGroups().includes(target)) return false;
            writeCustomGroups([...readCustomGroups(), target]);
            return true;
        }

        function removeCustomGroup(name) {
            writeCustomGroups(readCustomGroups().filter(g => g !== name));
        }

        /** 全部分组（含自建空分组）：「默认」永远排在最前，其余按中文排序 */
        function collectAllGroups() {
            const allGroups = new Set([DEFAULT_GROUP_NAME, 'AI 助手', '游戏角色', '学习伙伴', '娱乐', '自定义']);
            Object.values(friendsData).forEach(f => allGroups.add(getFriendGroup(f.id)));
            readCustomGroups().forEach(g => allGroups.add(g));
            return Array.from(allGroups).sort((a, b) => {
                if (a === DEFAULT_GROUP_NAME) return -1;
                if (b === DEFAULT_GROUP_NAME) return 1;
                return a.localeCompare(b, 'zh-CN');
            });
        }

        function groupMemberCount(groupName) {
            return Object.values(friendsData).filter(f => getFriendGroup(f.id) === groupName).length;
        }

        function deleteFriendGroup(groupName) {
            if (groupName === DEFAULT_GROUP_NAME) {
                showToast('默认分组不能删除', 'ri-error-warning-line');
                return Promise.resolve(false);
            }
            const count = groupMemberCount(groupName);
            return Dlg.confirm({
                title: '删除分组',
                message: `确定删除分组「${groupName}」吗？` + (count
                    ? `\n\n该分组内的 ${count} 个角色会被移动到「${DEFAULT_GROUP_NAME}」分组（角色与聊天记录都不会被删除）。`
                    : ''),
                okText: '删除分组',
                danger: true
            }).then(ok => {
                if (!ok) return false;
                Object.keys(friendsData).forEach(friendId => {
                    if (getFriendGroup(friendId) === groupName) setFriendGroup(friendId, DEFAULT_GROUP_NAME);
                });
                removeCustomGroup(groupName);
                // 折叠状态一并清掉，否则残留一条永远看不见的记录
                const collapsed = readJson('collapsedGroups', {}, '折叠分组');
                if (groupName in collapsed) {
                    delete collapsed[groupName];
                    setLocalStorageSafely('collapsedGroups', JSON.stringify(collapsed), '折叠分组');
                }
                renderFriendList();
                showToast(`已删除分组「${groupName}」`, 'ri-folder-reduce-line');
                return true;
            });
        }

        // ========== 分组管理界面（右键 / 长按分组标题进入） ==========
        // 原来是浏览器原生 prompt 连问两次（先输操作编号、再输名字）：样式不可控、
        // 手机上几乎没法操作。现在增删改都在同一个站内界面里完成。
        const groupManagerModal = document.getElementById('group-manager-modal');
        const gmListEl = document.getElementById('gm-list');
        const gmCreateBtn = document.getElementById('gm-create-btn');
        const gmDoneBtn = document.getElementById('gm-done-btn');
        const closeGroupManagerBtn = document.getElementById('close-group-manager-modal');
        let groupManagerFocused = '';

        function toggleGroupManager(show) {
            if (!groupManagerModal) return;
            groupManagerModal.classList.toggle('show', !!show);
        }

        function renderGroupManager() {
            if (!gmListEl) return;
            const groups = collectAllGroups();
            gmListEl.innerHTML = groups.map(g => {
                const isDefault = g === DEFAULT_GROUP_NAME;
                const count = groupMemberCount(g);
                return `
                    <div class="gm-item${g === groupManagerFocused ? ' is-focused' : ''}" data-group="${escapeHtml(g)}">
                        <span class="gm-name"><i class="ri-folder-line"></i>${escapeHtml(g)}</span>
                        <span class="gm-count">${count} 个角色</span>
                        <span class="gm-ops">
                            <button type="button" class="gm-op" data-gm-action="rename" ${isDefault ? 'disabled' : ''}
                                title="${isDefault ? '默认分组不可重命名' : '重命名该分组'}"><i class="ri-edit-line"></i></button>
                            <button type="button" class="gm-op gm-op-danger" data-gm-action="delete" ${isDefault ? 'disabled' : ''}
                                title="${isDefault ? '默认分组不可删除' : '删除该分组（角色移入默认分组）'}"><i class="ri-delete-bin-line"></i></button>
                        </span>
                    </div>`;
            }).join('') || '<div class="gm-empty">暂无分组</div>';
        }

        function openGroupManager(groupName) {
            groupManagerFocused = (groupName && collectAllGroups().includes(groupName)) ? groupName : '';
            renderGroupManager();
            toggleGroupManager(true);
        }

        function bindGroupManager() {
            if (!groupManagerModal) return;

            gmListEl?.addEventListener('click', async event => {
                const action = event.target.closest('[data-gm-action]')?.dataset.gmAction;
                if (!action) return;
                const name = event.target.closest('.gm-item')?.dataset.group;
                if (!name) return;

                if (action === 'rename') {
                    const next = await Dlg.prompt({
                        title: '重命名分组',
                        message: `把「${name}」重命名为：`,
                        value: name,
                        placeholder: '新的分组名（不超过 12 字）',
                        maxLength: 12,
                        okText: '重命名'
                    });
                    const target = String(next || '').trim();
                    if (!target || target === name) return;
                    if (collectAllGroups().includes(target)) {
                        showToast(`已有同名分组「${target}」`, 'ri-error-warning-line');
                        return;
                    }
                    // 旧名若是自建的：把名字换成新名，避免旧空分组残留在列表里
                    if (readCustomGroups().includes(name)) {
                        removeCustomGroup(name);
                        addCustomGroup(target);
                    }
                    renameFriendGroup(name, target);
                    groupManagerFocused = target;
                    renderGroupManager();
                }

                if (action === 'delete') {
                    const removed = await deleteFriendGroup(name);
                    if (removed) {
                        if (groupManagerFocused === name) groupManagerFocused = '';
                        renderGroupManager();
                    }
                }
            });

            gmCreateBtn?.addEventListener('click', async () => {
                const next = await Dlg.prompt({
                    title: '新建分组',
                    message: '输入新分组的名字：',
                    placeholder: '例如：二次元同好',
                    maxLength: 12,
                    okText: '创建'
                });
                const target = String(next || '').trim();
                if (!target) return;
                if (collectAllGroups().includes(target)) {
                    showToast(`已有同名分组「${target}」`, 'ri-error-warning-line');
                    return;
                }
                addCustomGroup(target);
                groupManagerFocused = target;
                renderGroupManager();
                renderFriendList();
                showToast(`已创建分组「${target}」，在角色的右键菜单里即可把它移进来`, 'ri-folder-add-line');
            });

            gmDoneBtn?.addEventListener('click', () => toggleGroupManager(false));
            closeGroupManagerBtn?.addEventListener('click', () => toggleGroupManager(false));
            groupManagerModal.addEventListener('click', e => {
                if (e.target === groupManagerModal) toggleGroupManager(false);
            });
        }
        bindGroupManager();

        /** 移动端没有右键：长按分组标题同样进入分组管理 */
        function attachGroupHeaderLongPress(el, groupName) {
            if (!el) return;
            let timer = null;
            let triggered = false;
            const start = () => {
                triggered = false;
                timer = setTimeout(() => {
                    triggered = true;
                    openGroupManager(groupName);
                }, 550);
            };
            const cancel = () => { clearTimeout(timer); timer = null; };
            el.addEventListener('touchstart', start, { passive: true });
            el.addEventListener('touchend', cancel);
            el.addEventListener('touchmove', cancel);
            el.addEventListener('touchcancel', cancel);
            // 长按后紧跟着触发的那次 click 要吞掉，否则打开管理界面的同时会折叠分组
            el.addEventListener('click', e => {
                if (triggered) { e.stopPropagation(); e.preventDefault(); triggered = false; }
            }, true);
        }


        function loadUserName() {
            const storedName = localStorage.getItem('myUserName');
            if (storedName) myUserName = storedName;
            updateUserNameDisplay();
        }
        function loadUserAvatar() {
            const storedAvatar = localStorage.getItem('userAvatar');
            if (storedAvatar) {
                inputAvatar.src = storedAvatar;
                return;
            }
            // localStorage 里没有时从 IndexedDB 补（大尺寸 dataURL 会因配额被降级存储）
            if (typeof IndexedDBStorage !== 'undefined') {
                IndexedDBStorage.getItem('userAvatar').then(value => {
                    if (!value) return;
                    inputAvatar.src = value;
                    document.querySelectorAll(myAvatarSelector()).forEach(img => { img.src = value; });
                }).catch(() => {});
            }
        }
        function saveUserName(newName) {
            if (!newName || newName.trim() === '') return;
            myUserName = newName.trim();
            setLocalStorageSafely('myUserName', myUserName);
            updateUserNameDisplay();
            // 性能优化：只增量更新已渲染消息中的用户名，避免全量重绘
            updateRenderedMessagesAppearance();
        }
        function updateUserNameDisplay() {
            myDisplayNameElement.textContent = myUserName;
        }
        function enableEditUserName() {
            // 已经在编辑中（span 此刻不在文档里）就忽略重复点击，
            // 否则连点两下会叠出两个输入框。
            if (!myDisplayNameElement.isConnected) return;
            const currentText = myDisplayNameElement.textContent;
            const input = document.createElement('input');
            input.type = 'text';
            input.value = currentText;
            input.className = 'name-input';
            input.setAttribute('aria-label', '修改我的名字');
            myDisplayNameElement.replaceWith(input);
            input.focus();
            input.select();

            let settled = false;
            const finishEdit = (commit) => {
                if (settled) return;
                settled = true;
                const nextName = String(input.value || '').trim();
                /* 关键：不管改没改名，都得把原来那个 span 放回 DOM。
                   以前这里只调 saveUserName()，而它 updateUserNameDisplay() 改的
                   是**已经被 replaceWith 换出文档**的那个 span —— 页面上的输入框
                   没人负责移除，于是它就一直挂在那儿，非要刷新才恢复。
                   这就是那个「古早 bug」的真正原因。 */
                if (input.parentNode) input.replaceWith(myDisplayNameElement);
                if (commit && nextName && nextName !== myUserName) saveUserName(nextName);
                else updateUserNameDisplay();
            };

            input.addEventListener('blur', () => finishEdit(true));
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') { e.preventDefault(); finishEdit(true); }
                else if (e.key === 'Escape') { e.preventDefault(); finishEdit(false); }
            });
        }


        async function loadThreadManager() {
            // 优先从 IndexedDB 读取（无配额限制），降级到 localStorage
            let stored = null;
            try {
                stored = await IndexedDBStorage.getItem('threadManager_v2');
                if (stored) {
                    dbgLog('✅ 从 IndexedDB 加载聊天记录成功');
                }
            } catch(e) {
                console.log('⚠️ IndexedDB 读取失败，回退到 localStorage');
            }
            
            // IndexedDB 读不到才用 localStorage
            if (!stored) {
                stored = localStorage.getItem('threadManager_v2');
            }
            
            if (stored) {
                try { threadManager = JSON.parse(stored); } catch (e) { threadManager = {}; }
            }
            // 回滚/旧缓存可能导致 IndexedDB 里只剩一份更早、更短的记录，
            // 而 localStorage 仍留着聊得最多的那份。两边都在时取消息更多的一份。
            try {
                const localCopy = localStorage.getItem('threadManager_v2');
                if (localCopy && localCopy !== stored) {
                    const localThreads = JSON.parse(localCopy);
                    // 瘦身镜像（__mirrorSlim）只用于同步读取，永远不当权威数据
                    if (!localThreads.__mirrorSlim && countStoredMessages(localThreads) > countStoredMessages(threadManager)) {
                        threadManager = localThreads;
                        console.warn('[聊天记录] IndexedDB 的记录比 localStorage 少，已改用本地较完整的一份');
                        saveThreadManager();
                    }
                }
            } catch (e) { /* 本地副本损坏时保持已加载的那份 */ }
            Object.keys(friendsData).forEach(fid => {
                if (!threadManager[fid]) {
                    threadManager[fid] = {
                        threads: [{ id: 1, name: '初始对话', messages: [] }],
                        currentThreadId: 1,
                        longTermMemory: []
                    };
                }
                if (!threadManager[fid].longTermMemory) {
                    threadManager[fid].longTermMemory = [];
                }
            });
            ensureMessageIds();
        }
        function saveThreadManager() {
            const payload = JSON.stringify(threadManager);
            /* 聊天记录动辄几 MB。以前是原样双写进 localStorage，把几 MB 的配额
               吃得一点不剩，于是 API Key、好感度开关这些几 KB 的配置在保存时
               一起抛 QuotaExceededError —— 用户看到的是「改了 Key 保存不了」。
               超限后只写瘦身镜像（每个线程最近 10 条），完整记录留在 IndexedDB：
               IndexedDB 是启动时的首选来源，同步读取点也还能读到结构。 */
            if (payload.length > THREAD_MIRROR_LIMIT) {
                if (typeof IndexedDBStorage !== 'undefined' && IndexedDBStorage.setItem) {
                    IndexedDBStorage.setItem('threadManager_v2', payload).catch(() => {});
                }
                setLocalStorageSafely('threadManager_v2', slimThreadPayload(payload, 10), '聊天记录',
                    { silent: true, skipIdb: true });
                return;
            }
            setLocalStorageSafely('threadManager_v2', payload, '聊天记录');
        }

        const saveThreadsToLocalStorage = saveThreadManager;
        /* 老数据的「消息 id 撞车」自愈。
           messageSeq 与聊天记录是两个独立存储键，恢复备份 / 清过缓存 / 多设备来回导时
           很容易脱节，于是历史上会出现两条 id 相同的消息。后果不只是「版本切换器
           看不到」——「编辑」「引用」「重新回答」都可能作用到别人的消息上。
           这里在进入某个角色时扫一遍当前对话：发现重复就把后来的重新编号（取当前最大值 +1），
           不影响其它对话，也不改动消息内容与顺序。 */
        function dedupeThreadMessageIds(thread) {
            if (!thread || !Array.isArray(thread.messages)) return 0;
            const seen = new Set();
            let maxId = 0;
            thread.messages.forEach(m => {
                const n = Number(m?.id);
                if (Number.isFinite(n) && n > maxId) maxId = n;
            });
            let next = maxId + 1, fixed = 0;
            thread.messages.forEach(m => {
                if (!m) return;
                const key = String(m.id != null ? m.id : m.timestamp);
                if (seen.has(key)) {
                    console.warn('[聊天] 发现重复消息 id，已重新编号:', key, '→', next);
                    m.id = next++;
                    fixed++;
                } else {
                    seen.add(key);
                }
            });
            return fixed;
        }

        function getCurrentThread() {
            const friendData = threadManager[currentFriendId];
            if (!friendData) return null;
            const thread = friendData.threads.find(t => t.id === friendData.currentThreadId);
            if (thread) return thread;
            // 【悬空自愈】currentThreadId 指向不存在的对话（多标签页互相覆盖、
            // 导入/恢复备份时 id 冲突、旧数据损坏都可能造成）时，
            // 旧实现直接返回 null —— getMessages() 拿到空数组，
            // 整个角色的聊天记录变成一条欢迎语，看起来像「记录全丢了」。
            // 这里回退到最近活跃的对话并把指针修正落盘，用户无感恢复。
            if (!friendData.threads.length) return null;
            const pickLatest = (t) => Number(t.lastActive || (t.messages && t.messages.length ? t.messages[t.messages.length - 1].timestamp : 0)) || 0;
            const healed = friendData.threads.slice().sort((a, b) => pickLatest(b) - pickLatest(a))[0] || friendData.threads[0];
            friendData.currentThreadId = healed.id;
            try { saveThreadManager(); } catch (e) { /* 落盘失败不影响本次渲染 */ }
            try { if (typeof window.renderBranchTree === 'function') window.renderBranchTree(); } catch (e) { /* 分支树不存在时忽略 */ }
            return healed;
        }
        function getMessages() {
            const thread = getCurrentThread();
            return thread ? thread.messages : [];
        }
        function getNextMessageId() {
            messageSeq += 1;
            setLocalStorageSafely('messageSeq', String(messageSeq));
            return messageSeq;
        }

        function ensureMessageIds() {
            let changed = false;
            Object.values(threadManager).forEach(friendData => {
                (friendData.threads || []).forEach(thread => {
                    (thread.messages || []).forEach(msg => {
                        if (!msg.id) {
                            msg.id = getNextMessageId();
                            changed = true;
                        }
                    });
                });
            });
            if (changed) saveThreadManager();
        }

        function addMessageToThread(role, content, type, isProactive = false, extra = {}) {
            return addMessageToFriendThread(currentFriendId, role, content, type, isProactive, extra);
        }

        function addMessageToFriendThread(friendId, role, content, type, isProactive = false, extra = {}) {
            const friendData = threadManager[friendId];
            return addMessageToSpecificThread(friendId, friendData?.currentThreadId, role, content, type, isProactive, extra);
        }

        function addMessageToSpecificThread(friendId, threadId, role, content, type, isProactive = false, extra = {}) {
            const friendData = threadManager[friendId];
            const thread = friendData?.threads?.find(t => t.id === threadId);
            if (thread) {
                /* id 去重：messageSeq 和聊天记录分开存，恢复备份 / 清过缓存时两者会脱节，
                   于是新消息可能拿到一个已经被旧消息占用的 id —— 之后「重新回答」「编辑」
                   「引用」都可能作用到别人的消息上。这里遇到占用就继续往后取。 */
                const usedIds = new Set((thread.messages || []).map(m => String(m.id || m.timestamp)));
                let nextId = getNextMessageId();
                let guard = 0;
                while (usedIds.has(String(nextId)) && guard++ < 500) nextId = getNextMessageId();
                const message = { id: nextId, role, content, type, timestamp: Date.now(), isProactive, ...extra };
                // 「重新回答」产生的回复不是新消息，而是上一条 AI 回复的新版本
                const swiped = role === 'other' ? consumeSwipeStash(friendId, threadId, message) : false;
                thread.messages.push(message);
                if (swiped) {
                    /* 流式模式下气泡是边收边写的，操作按钮区是结束时手工拼的，
                       里面没有版本切换控件。等这一轮渲染收尾后重绘一次，
                       让 ‹ 2/3 › 立刻出现，而不是要切走再切回来才看到。 */
                    setTimeout(() => {
                        try {
                            if (currentFriendId === friendId && threadManager[friendId]?.currentThreadId === threadId) {
                                renderMessages(friendId, { preserveScroll: true });
                            }
                        } catch (e) { }
                    }, 320);
                }
                thread.lastActive = message.timestamp;
                saveThreadManager();
                // 「最近聊过优先」需要列表跟着动：这里节流刷新一次侧边栏，
                // 不用在每次渲染消息时手动调用（群聊连发时也只会重绘一次）。
                scheduleFriendListRefreshForRecent();
                return message;
            }
            return null;
        }


        function saveMessageDraft() {
            clearTimeout(draftSaveTimer);
            draftSaveTimer = setTimeout(() => {
                if (currentFriendId) {
                    const draftKey = `messageDraft_${currentFriendId}`;
                    setLocalStorageSafely(draftKey, messageInput.value);
                }
            }, 300);
        }

        /**
         * 立刻把草稿写进存储（不经过 300ms 防抖）。
         * 切换角色前必须调用一次：否则最后一次按键可能还没落盘，
         * 恢复草稿时就会把刚打的字丢掉。
         */
        function saveMessageDraftNow() {
            clearTimeout(draftSaveTimer);
            draftSaveTimer = null;
            if (!currentFriendId) return;
            const draftKey = `messageDraft_${currentFriendId}`;
            const value = messageInput.value;
            if (value) setLocalStorageSafely(draftKey, value);
            else localStorage.removeItem(draftKey);
        }

        function restoreMessageDraft() {
            if (currentFriendId) {
                const draftKey = `messageDraft_${currentFriendId}`;
                const draft = localStorage.getItem(draftKey);
                // 没有草稿时必须显式清空输入框：旧实现只在「有草稿」时赋值，
                // 于是切换角色后上一个角色没发出去的文字会一直留在输入框里，
                // 还会把输入框撑成多行（用户看到的就是「聊天框莫名其妙变大、多出好几行」）。
                messageInput.value = draft || '';
            }
            // 无论有没有草稿都按最终内容重算高度，把上一个角色留下的虚高高度收回去
            autoResizeMessageInput();
        }

        function clearMessageDraft() {
            if (currentFriendId) {
                const draftKey = `messageDraft_${currentFriendId}`;
                localStorage.removeItem(draftKey);
            }
        }


        function clearCurrentThread() {
            // 【崩溃修复】必须判空。删光所有角色后 currentFriendId 会变成 null
            //（见删除好友的分支），而 threadManager[null] 是 undefined，
            // 直接 .threads.find 就抛 TypeError。触发路径很实在：
            // 删光角色 → 点聊天头的「清空当前聊天记录」或输 /reset → 控制台报错、
            // 界面毫无反应，用户完全不知道发生了什么。
            const friendData = threadManager[currentFriendId];
            const thread = friendData?.threads?.find(t => t.id === friendData.currentThreadId);
            if (!thread) {
                if (!currentFriendId || !friendData) showToast('当前没有打开任何角色，无需清空', 'ri-information-line');
                return;
            }
            thread.messages = [];
            saveThreadManager();
            renderMessages(currentFriendId);
            showToast("对话上下文已重置", "ri-refresh-line");
        }

        function deleteCurrentThread() {
            const friendData = threadManager[currentFriendId];
            if (!friendData || friendData.threads.length === 0) return;

            const currentThreadId = friendData.currentThreadId;
            const threadIndex = friendData.threads.findIndex(t => t.id === currentThreadId);

            if (threadIndex === -1) return;

            if (friendData.threads.length === 1) {
                clearCurrentThread();
                showToast("已清空对话内容", "ri-delete-bin-line");
                return;
            }

            friendData.threads.splice(threadIndex, 1);

            let newThreadId;
            if (threadIndex > 0) {
                newThreadId = friendData.threads[threadIndex - 1].id;
            } else {
                newThreadId = friendData.threads[0].id;
            }

            friendData.currentThreadId = newThreadId;
            saveThreadManager();

            renderMessages(currentFriendId);
            renderFriendList();
            showToast(`对话线程已删除`, "ri-delete-bin-line");
        }

        function createNewThread() {
            document.querySelectorAll('[id^="loading-"], [id^="group-loading-"]').forEach(node => node.remove());
            const friendData = threadManager[currentFriendId];
            const newId = Math.max(...friendData.threads.map(t => t.id)) + 1;
            friendData.threads.push({ id: newId, name: `对话 #${newId}`, messages: [] });
            friendData.currentThreadId = newId;
            saveThreadManager();
            renderMessages(currentFriendId);
            renderFriendList();
            if (typeof window.renderBranchTree === 'function') window.renderBranchTree();
            showToast(`新对话线程已创建`, "ri-add-circle-line");
        }
        function switchThread(threadId) {
            const friendData = threadManager[currentFriendId];
            // 同样要判空：/switch 是聊天框里的斜杠指令，任何时候都能敲，
            // 包括刚删光角色、currentFriendId 为 null 的时候。
            if (!friendData) {
                showToast('当前没有打开任何角色，无法切换对话', 'ri-error-warning-line');
                return;
            }
            document.querySelectorAll('[id^="loading-"], [id^="group-loading-"]').forEach(node => node.remove());
            const targetThread = friendData.threads.find(t => t.id === parseInt(threadId, 10));
            if (targetThread) {
                friendData.currentThreadId = parseInt(threadId, 10);
                saveThreadManager();
                renderMessages(currentFriendId);
                // 切换对话线程后也自动滚到底部，避免用户手动滑动
                const scrollToEnd = () => {
                    try {
                        if (typeof scrollToBottom === 'function') scrollToBottom();
                        else chatMessages.scrollTop = chatMessages.scrollHeight;
                    } catch (e) {}
                };
                requestAnimationFrame(() => { scrollToEnd(); setTimeout(scrollToEnd, 200); });
                if (typeof window.renderBranchTree === 'function') window.renderBranchTree();
                showToast(`已切换对话线程`, "ri-exchange-line");
            } else {
                showToast(`未找到对话线程`, "ri-error-warning-line");
            }
        }

        function renameCurrentThread(newName) {
            if (!newName || newName.trim() === '') {
                showToast("请输入有效的对话名称", "ri-error-warning-line");
                return;
            }
            const friendData = threadManager[currentFriendId];
            // 判空同上：/rename 也是随时能敲的斜杠指令
            const thread = friendData?.threads?.find(t => t.id === friendData.currentThreadId);
            if (thread) {
                thread.name = newName.trim();
                saveThreadManager();
                showToast(`对话已重命名`, "ri-edit-line");
                renderFriendList();
            } else {
                showToast('找不到要重命名的对话', 'ri-error-warning-line');
            }
        }


        // ========== 性能优化：角色列表渲染防抖 ==========
        let renderFriendListDebounceTimer = null;
        // 待「滚进可视区」的角色 id：切角色时置位，等下一次列表真正渲染完再滚动。
        // 不能直接在 switchFriend 里滚 —— renderFriendList 是 100ms 防抖的，
        // 那时列表还是旧节点，滚了也会被随后的重建覆盖回顶部。
        let pendingRevealFriendId = null;

        function renderFriendList() {
            // 防抖：100ms 内多次调用只执行最后一次
            // 拖动分组期间冻结列表重绘：中途重绘会把被拖的标题换成游离节点，
            // 松手时看到的顺序与内存里的不一致（表现为「拖完又弹回原位」）。
            if (groupDragInProgress) { groupDragDeferredRender = true; return; }
            if (renderFriendListDebounceTimer) {
                clearTimeout(renderFriendListDebounceTimer);
            }
            renderFriendListDebounceTimer = setTimeout(() => {
                renderFriendListDebounceTimer = null;
                _renderFriendListImpl();
            }, 100);
        }

        // 用户手动排列的角色顺序（置顶、分组仍优先于该顺序）。
        const FRIEND_ORDER_STORAGE_KEY = 'friendListManualOrder_v1';
        function getFriendManualOrder() {
            try { return JSON.parse(localStorage.getItem(FRIEND_ORDER_STORAGE_KEY) || '[]'); } catch (e) { return []; }
        }
        function saveFriendManualOrder(order) {
            setLocalStorageSafely(FRIEND_ORDER_STORAGE_KEY, JSON.stringify([...new Set(order)]), '角色列表排序');
        }
        function sortFriendsByManualOrder(list) {
            const order = getFriendManualOrder();
            const positions = new Map(order.map((id, index) => [id, index]));
            return [...list].sort((a, b) => (positions.get(a.id) ?? Number.MAX_SAFE_INTEGER) - (positions.get(b.id) ?? Number.MAX_SAFE_INTEGER));
        }

        // 用户拖动分组后的分组顺序（只记分组名；没记过的分组排在最后，仍按中文排序）。
        const FRIEND_GROUP_ORDER_STORAGE_KEY = 'friendGroupOrder_v1';
        function getFriendGroupOrder() {
            try {
                const list = JSON.parse(localStorage.getItem(FRIEND_GROUP_ORDER_STORAGE_KEY) || '[]');
                return Array.isArray(list) ? list.map(String) : [];
            } catch (e) { return []; }
        }
        function saveFriendGroupOrder(order) {
            setLocalStorageSafely(FRIEND_GROUP_ORDER_STORAGE_KEY, JSON.stringify([...new Set(order)]), '分组排序');
        }
        // ========== 最近聊过的角色排在前面 ==========
        // 规则只在「同一分组内的非置顶角色」之间生效：不会打乱置顶项，
        // 也仍然尊重用户手动拖出来的顺序（时间相同时保持手动顺序，见 _renderFriendListImpl）。
        function recentChatFirstEnabled() {
            return getChatSettings().recentChatFirst !== false;
        }

        /** 取某个角色的最近活跃时间：优先线程 lastActive，其次最后一条消息的时间戳 */
        function getFriendLastActive(friendId) {
            const data = threadManager?.[friendId];
            let latest = 0;
            if (data) {
                (data.threads || []).forEach(thread => {
                    latest = Math.max(latest, Number(thread?.lastActive) || 0);
                    const messages = thread?.messages;
                    if (Array.isArray(messages) && messages.length) {
                        latest = Math.max(latest, Number(messages[messages.length - 1]?.timestamp) || 0);
                    }
                });
            }
            return latest;
        }

        // 每来一条消息都要重排侧边栏，这里做一次节流，避免群聊连发时反复重绘整个列表。
        let recentChatRefreshTimer = null;
        function scheduleFriendListRefreshForRecent() {
            if (!recentChatFirstEnabled()) return;
            clearTimeout(recentChatRefreshTimer);
            recentChatRefreshTimer = setTimeout(() => {
                recentChatRefreshTimer = null;
                renderFriendList();
            }, 260);
        }

        // 所有平台统一使用“按住后拖动”的 Pointer Events 排序：部分 Chromium 内核（含夸克）
        // 的原生 HTML5 drag/drop 在列表嵌套元素中会出现只能拖起、不能落下的问题。
        // 修订：原判定过短（触摸 450ms / 鼠标 120ms）且没有任何位移检查，于是
        // 「稍微按久一点的普通点击」也被当成拖动，点一下就把角色换了位置。
        // 现在既把等待时间调长，也要求真正移动过一段距离才进入拖动状态。
        const REORDER_HOLD_MS = Object.freeze({ touch: 720, mouse: 340 });
        const REORDER_MOVE_THRESHOLD = 12; // 触发拖动前允许的位移（px）
        let reorderedFriendItem = null;
        let reorderPressTimer = null;
        let reorderArming = null; // { item, startX, startY, moved }
        let suppressFriendClickUntil = 0;
        function moveReorderedFriend(target, clientY) {
            const item = reorderedFriendItem;
            if (!item || !target || target === item || target.dataset.friendGroup !== item.dataset.friendGroup) return;
            const rect = target.getBoundingClientRect();
            target.parentElement.insertBefore(item, clientY > rect.top + rect.height / 2 ? target.nextSibling : target);
        }
        function finishFriendReorder(shouldSave = true) {
            clearTimeout(reorderPressTimer);
            reorderArming = null;
            if (!reorderedFriendItem) return;
            reorderedFriendItem.classList.remove('reordering');
            reorderedFriendItem = null;
            if (shouldSave) persistFriendDomOrder();
        }
        function enableFriendReorder(item, friendId, groupName) {
            // 禁用原生 HTML5 拖拽：夸克会优先劫持它，导致 Pointer Events 无法接收后续移动事件。
            item.draggable = false;
            item.dataset.friendId = friendId;
            item.dataset.friendGroup = groupName;
            item.addEventListener('pointerdown', e => {
                if (isBatchEditMode || e.button > 0) return;
                // 必须在按下当刻捕获指针；此前等长按计时结束才捕获，指针一旦离开卡片，
                // 后续 move 就丢失了，因此所有端看起来都“拖得动却换不了位置”。
                item.setPointerCapture?.(e.pointerId);
                const delay = e.pointerType === 'touch' ? REORDER_HOLD_MS.touch : REORDER_HOLD_MS.mouse;
                reorderArming = { item, startX: e.clientX, startY: e.clientY, moved: false };
                // 蓄力反馈：等待期间加一个极轻的缩放，让用户知道「长按正在生效」，
                // 而不是毫无提示地突然变成拖动。真实位移仍要等计时结束才开始。
                item.classList.add('reorder-arming');
                reorderPressTimer = setTimeout(() => {
                    // 计时结束再校验一次：手指/鼠标已经移开（滚动或滑屏）就不启动拖动
                    if (!reorderArming || reorderArming.item !== item || reorderArming.moved) {
                        item.classList.remove('reorder-arming');
                        return;
                    }
                    reorderedFriendItem = item;
                    item.classList.remove('reorder-arming');
                    item.classList.add('reordering');
                    if (e.pointerType === 'touch') navigator.vibrate?.(20);
                }, delay);
            });
            item.addEventListener('pointermove', e => {
                // 还没进入拖动状态时，只判断「有没有真的移动」：
                // 位移超过阈值即取消长按计时 —— 普通点击时的手指微抖不会误触排序。
                if (!reorderedFriendItem) {
                    if (reorderArming && reorderArming.item === item) {
                        const dx = e.clientX - reorderArming.startX;
                        const dy = e.clientY - reorderArming.startY;
                        if (Math.hypot(dx, dy) > REORDER_MOVE_THRESHOLD) {
                            reorderArming.moved = true;
                            clearTimeout(reorderPressTimer);
                            item.classList.remove('reorder-arming');
                        }
                    }
                    return;
                }
                e.preventDefault();
                // 被拖动的元素本身位于指针下方，暂时关闭命中以找到真正的目标项。
                reorderedFriendItem.style.pointerEvents = 'none';
                const target = document.elementFromPoint(e.clientX, e.clientY)?.closest('.friend-item[data-friend-id]');
                reorderedFriendItem.style.pointerEvents = '';
                moveReorderedFriend(target, e.clientY);
            }, { passive: false });
            item.addEventListener('pointerup', e => {
                clearTimeout(reorderPressTimer);
                const active = Boolean(reorderedFriendItem);
                // 只是按住了一下但没拖 → 视作普通点击，不写排序、不阻断点击
                item.classList.remove('reorder-arming');
                reorderArming = null;
                item.releasePointerCapture?.(e.pointerId);
                finishFriendReorder(active);
                if (active) { suppressFriendClickUntil = Date.now() + 350; renderFriendList(); }
            });
            item.addEventListener('pointercancel', () => {
                clearTimeout(reorderPressTimer);
                item.classList.remove('reorder-arming');
                reorderArming = null;
                finishFriendReorder(false);
            });
        }
        function persistFriendDomOrder() {
            const visibleIds = [...friendList.querySelectorAll('.friend-item[data-friend-id]')].map(el => el.dataset.friendId);
            const oldOrder = getFriendManualOrder().filter(id => !visibleIds.includes(id));
            saveFriendManualOrder([...oldOrder, ...visibleIds]);
        }

        // ========== 分组拖动排序 ==========
        // 与角色拖动同一套「按住再拖」手势，但整组一起走：拖动时把该分组内容折叠起来
        // （只留标题跟着手指），松手后展开 —— 若拖之前本来就是收起的，则保持收起。
        //
        // 【重要】这里刻意不用 setPointerCapture，也**不**把标题设成 pointer-events:none：
        //   角色拖动之所以正常，是因为它只在 elementFromPoint 那一瞬间临时关掉命中；
        //   而旧的分组拖动把「整段拖动期间」都设成穿透 + 捕获指针，部分 Chromium 内核
        //   会因此不再派发后续 pointerup —— 拖动状态永远结束不了（只能靠别处触发的重绘
        //   “掉下来”，于是一放下来就回到原位）。
        // 现在：手势监听挂在 window（捕获阶段），落点按「离指针最近的标题中心」几何计算，
        // 因此既不依赖指针捕获、也不依赖命中测试，绝对能停下来，且任何位置都能落位。
        let reorderedGroupHeader = null;
        let groupReorderPressTimer = null;
        let groupReorderArming = null;
        let groupReorderWasCollapsed = false;
        let groupDragPointerId = null;
        // 【用 var】renderFriendList 定义在文件更早的位置，读它时不能踩到 let 的暂时性死区。
        // 拖动期间冻结列表重绘：一旦中途重绘，被拖的标题会变成游离节点，
        // 松手时看到的顺序和内存里的对不上（就是「拖完又弹回原位」）。
        var groupDragInProgress = false;
        var groupDragDeferredRender = false;

        function groupPairOf(header) {
            const content = header?.nextElementSibling;
            return content && content.classList.contains('friend-group-content') ? content : null;
        }

        function groupHeaderList() {
            return [...friendList.querySelectorAll('.friend-group-header')];
        }

        /**
         * 指针落在哪个分组标题“附近”—— 用「离指针最近的标题中心」来算。
         * 不再用 document.elementFromPoint 找 .friend-group-header：
         * 指针落在分组内容区（角色卡片）或两行之间时，命中测试根本找不到标题，
         * 于是「拖到某个分组上面/下面」永远没有反应、松手也不落位。
         */
        function nearestGroupHeader(clientY) {
            const dragging = reorderedGroupHeader;
            let best = null;
            let bestDist = Infinity;
            groupHeaderList().forEach(candidate => {
                if (candidate === dragging) return;
                const rect = candidate.getBoundingClientRect();
                if (!rect.width && !rect.height) return;
                const dist = Math.abs(clientY - (rect.top + rect.height / 2));
                if (dist < bestDist) { bestDist = dist; best = { header: candidate, rect }; }
            });
            return best;
        }

        /** 把「被拖的标题 + 它的内容区」整块挪到离指针最近的分组前/后 */
        function moveReorderedGroup(clientY) {
            const header = reorderedGroupHeader;
            if (!header) return;
            if (!header.isConnected) { cancelGroupDrag(); return; }
            const hit = nearestGroupHeader(clientY);
            if (!hit) return;
            const parent = hit.header.parentElement;
            if (!parent || parent !== header.parentElement) return;
            const content = groupPairOf(header);
            const rect = hit.rect;
            const after = clientY > rect.top + rect.height / 2;
            const anchor = after ? (groupPairOf(hit.header)?.nextSibling || hit.header.nextSibling) : hit.header;
            if (anchor === header || anchor === content) return;   // 已经在目标位置
            parent.insertBefore(header, anchor);
            if (content) parent.insertBefore(content, header.nextSibling);
        }

        function beginGroupDrag(header, pointerType) {
            if (!header || reorderedGroupHeader) return;
            clearTimeout(groupReorderPressTimer);
            header.classList.remove('reorder-arming');
            header.classList.add('reordering-group');
            reorderedGroupHeader = header;
            groupDragInProgress = true;
            const content = groupPairOf(header);
            groupReorderWasCollapsed = !!(content && content.classList.contains('collapsed'));
            // 拖动过程中收起该分组：整组跟着标题一起走，但只显示标题这一行。
            if (content) content.classList.add('collapsed');
            if (pointerType === 'touch') navigator.vibrate?.(20);
        }

        function finishGroupReorder(shouldSave = true) {
            clearTimeout(groupReorderPressTimer);
            groupReorderArming = null;
            groupDragPointerId = null;
            groupDragInProgress = false;
            const header = reorderedGroupHeader;
            if (!header) { groupDragDeferredRender = false; return; }
            const name = header.getAttribute('data-group');
            header.classList.remove('reordering-group');
            header.classList.remove('reorder-arming');
            header.style.pointerEvents = '';
            const content = groupPairOf(header);
            if (content) {
                content.style.pointerEvents = '';
                // 松手后恢复展开：只有「拖之前本来就是收起的」才继续保持收起
                const collapse = groupReorderWasCollapsed === true;
                content.classList.toggle('collapsed', collapse);
                header.classList.toggle('collapsed', collapse);
                const stored = readJson('collapsedGroups', {}, '折叠分组');
                stored[name] = collapse;
                setLocalStorageSafely('collapsedGroups', JSON.stringify(stored));
            }
            reorderedGroupHeader = null;
            groupReorderWasCollapsed = false;
            // 先把新顺序落库，再由调用方（或这里的补渲染）重画：放下就固定住
            if (shouldSave) persistGroupDomOrder();
            if (groupDragDeferredRender) { groupDragDeferredRender = false; renderFriendList(); }
        }

        function persistGroupDomOrder() {
            const names = groupHeaderList().map(header => header.getAttribute('data-group')).filter(Boolean);
            // 搜索 / 分组筛选时列表里只有一部分分组：直接整体覆盖会把没渲染到的分组顺序丢掉。
            // 保留旧记录里没出现过的分组名（追加在后面），与角色排序同一套做法。
            const rest = getFriendGroupOrder().filter(name => !names.includes(name));
            saveFriendGroupOrder([...names, ...rest]);
        }

        /** 放弃这次拖动：界面回到拖动前的顺序（Esc / 失焦 / 指针取消 / 切标签页） */
        function cancelGroupDrag() {
            clearTimeout(groupReorderPressTimer);
            if (groupReorderArming) {
                groupReorderArming.header?.classList.remove('reorder-arming');
                groupReorderArming = null;
            }
            groupDragPointerId = null;
            if (!reorderedGroupHeader) return;
            finishGroupReorder(false);
            renderFriendList();
        }

        // 手势统一挂在 window（捕获阶段）：不再依赖「事件刚好落在被拖的标题身上」。
        let groupDragGlobalsBound = false;
        function bindGroupDragGlobals() {
            if (groupDragGlobalsBound) return;
            groupDragGlobalsBound = true;
            window.addEventListener('pointermove', onGroupDragPointerMove, { passive: false, capture: true });
            window.addEventListener('pointerup', onGroupDragPointerUp, true);
            window.addEventListener('pointercancel', onGroupDragPointerCancel, true);
            window.addEventListener('blur', cancelGroupDrag);
            document.addEventListener('keydown', e => { if (e.key === 'Escape') cancelGroupDrag(); });
            document.addEventListener('visibilitychange', () => { if (document.hidden) cancelGroupDrag(); });
        }

        function onGroupDragPointerMove(e) {
            if (groupDragPointerId !== null && e.pointerId !== groupDragPointerId) return;
            if (!reorderedGroupHeader) {
                if (!groupReorderArming) return;
                const dx = e.clientX - groupReorderArming.startX;
                const dy = e.clientY - groupReorderArming.startY;
                if (Math.hypot(dx, dy) <= REORDER_MOVE_THRESHOLD) return;
                if (groupReorderArming.pointerType === 'touch') {
                    // 触摸端：位移即视为在滑动列表，取消长按计时（避免滚动时误触排序）
                    clearTimeout(groupReorderPressTimer);
                    groupReorderArming.header?.classList.remove('reorder-arming');
                    groupReorderArming = null;
                    return;
                }
                // 鼠标端「按住直接拖」：不必先按住不动等长按计时结束
                const { header, pointerType } = groupReorderArming;
                beginGroupDrag(header, pointerType);
                if (!reorderedGroupHeader) return;
            }
            if (e.cancelable) e.preventDefault();
            moveReorderedGroup(e.clientY);
        }

        function onGroupDragPointerUp(e) {
            if (groupDragPointerId !== null && e.pointerId !== groupDragPointerId) return;
            if (!reorderedGroupHeader) {
                // 只是按了一下（没进入拖动状态）：交给原本的 click 处理，这里只收掉蓄力态
                clearTimeout(groupReorderPressTimer);
                if (groupReorderArming) {
                    groupReorderArming.header?.classList.remove('reorder-arming');
                    groupReorderArming = null;
                }
                return;
            }
            // 抬手即落位：写进分组顺序并重绘
            finishGroupReorder(true);
            suppressFriendClickUntil = Date.now() + 350;
            renderFriendList();
        }

        function onGroupDragPointerCancel() {
            if (!reorderedGroupHeader && !groupReorderArming) return;
            cancelGroupDrag();
        }

        function enableGroupReorder(header, groupName) {
            header.dataset.groupName = groupName;
            header.draggable = false;
            // 保险：万浏览器仍想发起原生 HTML5 拖拽（出现幽灵图、松手不落位），直接拦掉
            header.addEventListener('dragstart', e => e.preventDefault());
            header.addEventListener('pointerdown', e => {
                if (isBatchEditMode || e.button > 0) return;
                // 「⋯」管理按钮不参与拖动
                if (e.target?.closest?.('.group-menu-btn')) return;
                bindGroupDragGlobals();
                clearTimeout(groupReorderPressTimer);
                const delay = e.pointerType === 'touch' ? REORDER_HOLD_MS.touch : REORDER_HOLD_MS.mouse;
                groupDragPointerId = e.pointerId;
                groupReorderArming = {
                    header, pointerType: e.pointerType, pointerId: e.pointerId,
                    startX: e.clientX, startY: e.clientY, moved: false
                };
                header.classList.add('reorder-arming');
                groupReorderPressTimer = setTimeout(() => {
                    if (!groupReorderArming || groupReorderArming.header !== header) return;
                    beginGroupDrag(header, groupReorderArming.pointerType);
                }, delay);
            });
        }

        function _renderFriendListImpl() {
            friendList.innerHTML = '';

            // 使用 DocumentFragment 批量插入，减少重排
            const fragment = document.createDocumentFragment();


            const searchTerm = (friendSearchInput?.value || '').trim().toLowerCase();

            // 「最近聊过优先」需要一个 id → 最近活跃时间 的映射。整表只计算一次，
            // 避免在比较函数里反复遍历线程（每个角色每次比较都遍历会明显变慢）。
            const recentActiveMap = new Map();
            if (recentChatFirstEnabled()) {
                Object.keys(friendsData).forEach(id => recentActiveMap.set(id, getFriendLastActive(id)));
            }

            // 分组顺序：用户拖动过的分组按记录顺序排；没记录过的排在后面按中文排序。
            const groupRank = new Map(getFriendGroupOrder().map((name, index) => [name, index]));

            const allFriends = sortFriendsByManualOrder(Object.values(friendsData)).sort((a, b) => {
                // 必须先按分组、再在组内按置顶排序。此前先全局置顶会令同一分组被
                // “置顶项 / 其他分组 / 未置顶项”切开，因而渲染出重复的分组标题。
                const aGroup = getFriendGroup(a.id);
                const bGroup = getFriendGroup(b.id);
                if (aGroup !== bGroup) {
                    const aRank = groupRank.has(aGroup) ? groupRank.get(aGroup) : Number.MAX_SAFE_INTEGER;
                    const bRank = groupRank.has(bGroup) ? groupRank.get(bGroup) : Number.MAX_SAFE_INTEGER;
                    if (aRank !== bRank) return aRank - bRank;
                    return aGroup.localeCompare(bGroup, 'zh-CN');
                }

                const aPinned = isFriendPinned(a.id);
                const bPinned = isFriendPinned(b.id);
                if (aPinned && !bPinned) return -1;
                if (!aPinned && bPinned) return 1;

                // 同一分组、同为置顶或同为非置顶时：最近聊过的排前面。
                // 置顶项之间也按最近聊过排序，但绝不会越过「置顶优先」这条规则。
                // lastActive 相同时返回 0 —— Array.prototype.sort 在现代引擎里是稳定排序，
                // 于是会保持上面 sortFriendsByManualOrder 排好的手动拖拽顺序。
                if (recentChatFirstEnabled()) {
                    const diff = (recentActiveMap.get(b.id) || 0) - (recentActiveMap.get(a.id) || 0);
                    if (diff) return diff;
                }

                return 0;
            });


            let filteredFriends = allFriends;
            if (searchTerm) {
                filteredFriends = allFriends.filter(friend => {
                    const displayName = getFriendDisplayName(friend.id);
                    return `${friend.name} ${displayName}`.toLowerCase().includes(searchTerm);
                });
                const header = document.createElement('div');
                header.innerHTML = createSearchSectionHeader('角色结果', filteredFriends.length, 'characters', { icon: 'ri-user-search-line' }).trim();
                fragment.appendChild(header.firstElementChild);
                if (isSearchSectionCollapsed('characters')) {
                    friendList.appendChild(fragment);
                    return;
                }
            }


            let currentGroup = null;
            let groupContent = null;
            let groupCount = 0;

            filteredFriends.forEach(friend => {
                const friendGroup = getFriendGroup(friend.id);


                if (friendGroup !== currentGroup) {
                    currentGroup = friendGroup;
                    groupCount = 0;

                    const groupHeader = document.createElement('div');
                    groupHeader.classList.add('friend-group-header');
                    const headerGroup = currentGroup;
                    groupHeader.setAttribute('data-group', headerGroup);
                    groupHeader.innerHTML = `<span class="group-title"><i class="ri-folder-line"></i> ${escapeHtml(headerGroup)}</span><span class="group-count">0</span><button type="button" class="group-menu-btn" title="分组管理" aria-label="分组管理"><i class="ri-more-2-line"></i></button><span class="group-drag-hint" title="长按拖动分组"><i class="ri-draggable"></i></span>`;


                    groupHeader.addEventListener('contextmenu', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        // 右键分组 → 打开「分组管理」界面（原来是连问两次的原生 prompt，
                        // 又丑又难操作；增删分组现在都在同一个界面里完成）
                        openGroupManager(headerGroup);
                    });
                    groupHeader.addEventListener('click', (e) => {
                        if (e.shiftKey || e.altKey) {
                            e.preventDefault();
                            // 阻止同元素上的折叠监听执行，避免「打开管理界面的同时把分组折叠了」
                            e.stopImmediatePropagation();
                            openGroupManager(headerGroup);
                        }
                    });
                    // 移动端：长按标题 = 拖动整组排序；「⋯」按钮 = 分组管理。
                    // 旧版长按是进分组管理，现在这个手势让给拖动，管理入口收进按钮，
                    // 免得同一个手势既拖动又弹窗。
                    groupHeader.querySelector('.group-menu-btn')?.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        openGroupManager(headerGroup);
                    });
                    enableGroupReorder(groupHeader, headerGroup);


                    groupHeader.addEventListener('click', (e) => {
                        // 刚刚拖完分组：这次 click 是拖动抬手产生的，不能当作折叠
                        if (Date.now() < suppressFriendClickUntil) return;
                        if (e.target.closest('.friend-group-header')) {
                            const header = e.currentTarget;
                            const content = header.nextElementSibling;
                            if (content && content.classList.contains('friend-group-content')) {
                                const isCollapsed = content.classList.toggle('collapsed');
                                header.classList.toggle('collapsed', isCollapsed);


                                const collapsedGroups = readJson('collapsedGroups', {}, '折叠分组');
                                collapsedGroups[headerGroup] = isCollapsed;
                                setLocalStorageSafely('collapsedGroups', JSON.stringify(collapsedGroups));
                            }
                        }
                    });

                    fragment.appendChild(groupHeader);


                    groupContent = document.createElement('div');
                    groupContent.classList.add('friend-group-content');
                    // 放到分组空白处或最后一项后时，也可完成排序。
                    groupContent.addEventListener('dragover', (e) => {
                        if (!reorderedFriendItem || reorderedFriendItem.dataset.friendGroup !== currentGroup) return;
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                    });
                    groupContent.addEventListener('drop', (e) => {
                        if (!reorderedFriendItem || reorderedFriendItem.dataset.friendGroup !== currentGroup) return;
                        e.preventDefault();
                        groupContent.appendChild(reorderedFriendItem);
                        finishFriendReorder();
                        renderFriendList();
                    });
                    fragment.appendChild(groupContent);
                }

                groupCount++;

                const item = document.createElement('div');
                item.classList.add('friend-item');
                // 排序手势由 Pointer Events 接管，避免图片原生拖拽抢走事件。
                item.addEventListener('dragstart', e => e.preventDefault());
                if (friend.id === currentFriendId) item.classList.add('active');
                if (isFriendPinned(friend.id)) item.classList.add('pinned');

                const displayName = getFriendDisplayName(friend.id);
                enableFriendReorder(item, friend.id, friendGroup);

                // 安全加固：角色 id / 头像 / 名称都可能来自导入数据，属性与文本位置一律转义，
                // 避免名字里带引号或尖括号时逃逸出标签（存储型 XSS）。
                const safeFriendId = escapeHtml(friend.id);
                const safeFriendAvatar = escapeHtml(friend.avatar);
                const safeFriendName = escapeHtml(friend.name);
                const safeDisplayName = escapeHtml(displayName);
                item.innerHTML = `
                    ${isBatchEditMode && friend.isCustom ? `<input type="checkbox" class="friend-batch-checkbox" data-friend-id="${safeFriendId}" ${selectedCustomFriends.has(friend.id) ? 'checked' : ''}>` : ''}
                    <img data-src="${safeFriendAvatar}" alt="${safeFriendName}" class="friend-avatar lazy-avatar" data-friend-id="${safeFriendId}">
                    <span class="friend-pin"><i class="ri-pushpin-2-fill"></i></span>
                    <div style="flex:1;">
                        <div class="friend-name">${safeDisplayName}${displayName !== friend.name ? `<span style="font-size:0.8em;color:#888">(<span class="friend-orig-name">${safeFriendName}</span>)</span>` : ''}</div>
                    </div>
                    ${friend.isGroup ? '<span class="friend-status">群聊</span>' : (!hideMultiThreadStatusCheckbox?.checked && threadManager[friend.id]?.threads.length > 1 ? '<span class="friend-status">多线程</span>' : '')}
                `;

                const batchCheckbox = item.querySelector('.friend-batch-checkbox');
                if (batchCheckbox) {
                    batchCheckbox.addEventListener('click', (e) => e.stopPropagation());
                    batchCheckbox.addEventListener('change', (e) => {
                        e.stopPropagation();
                        e.target.checked ? selectedCustomFriends.add(friend.id) : selectedCustomFriends.delete(friend.id);
                        updateBatchActionButtons();
                    });
                }

                const avatar = item.querySelector('.friend-avatar');
                const nameElement = item.querySelector('.friend-name');
                // 头像保留右键入口；角色名字支持双击（桌面）与长按（移动端）。
                avatar.addEventListener('contextmenu', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    showFriendContextMenu(e, friend.id);
                });
                const openNameMenu = (e) => showFriendContextMenu(e, friend.id);
                nameElement.addEventListener('dblclick', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    openNameMenu(e);
                });
                let pressTimer;
                nameElement.addEventListener('touchstart', (e) => {
                    pressTimer = setTimeout(() => openNameMenu(e), 550);
                });
                ['touchend', 'touchmove', 'touchcancel'].forEach(eventName => nameElement.addEventListener(eventName, () => clearTimeout(pressTimer)));
                avatar.addEventListener('touchstart', (e) => {
                    pressTimer = setTimeout(() => showFriendContextMenu(e, friend.id), 500);
                });
                ['touchend', 'touchmove', 'touchcancel'].forEach(eventName => avatar.addEventListener(eventName, () => clearTimeout(pressTimer)));

                item.addEventListener('click', (e) => {
                    // 长按排序后的抬手会生成 click，不能因此误打开角色。
                    if (Date.now() < suppressFriendClickUntil) return;
                    if (isBatchEditMode) {
                        const checkbox = item.querySelector('.friend-batch-checkbox');
                        if (checkbox) {
                            if (e.target !== checkbox) checkbox.checked = !checkbox.checked;
                            checkbox.checked ? selectedCustomFriends.add(friend.id) : selectedCustomFriends.delete(friend.id);
                        }
                        updateBatchActionButtons();
                        return;
                    }
                    switchFriend(friend.id);
                    if (isMobileView) {
                        closeSidebar();
                    }
                });

                if (groupContent) {
                    groupContent.appendChild(item);
                }
            });


            // 一次性插入所有 DOM，减少重排
            friendList.appendChild(fragment);

            const headers = friendList.querySelectorAll('.friend-group-header');
            headers.forEach(header => {
                const groupName = header.getAttribute('data-group');
                const count = filteredFriends.filter(f => getFriendGroup(f.id) === groupName).length;
                const countSpan = header.querySelector('.group-count');
                if (countSpan) {
                    countSpan.textContent = count;
                }
            });


            const collapsedGroups = readJson('collapsedGroups', {}, '折叠分组');
            headers.forEach(header => {
                const groupName = header.getAttribute('data-group');
                if (collapsedGroups[groupName]) {
                    header.classList.add('collapsed');
                    const content = header.nextElementSibling;
                    if (content && content.classList.contains('friend-group-content')) {
                        content.classList.add('collapsed');
                    }
                }
            });

            // 把「刚切过去的角色」滚进可视区。
            // renderFriendList 是 100ms 防抖的，switchFriend 里直接滚会滚到旧节点上，
            // 重建列表后 scrollTop 回到 0，所以统一放到渲染结束这一步。
            if (pendingRevealFriendId) {
                const targetId = pendingRevealFriendId;
                pendingRevealFriendId = null;
                try {
                    const activeItem = friendList.querySelector('.friend-item.active');
                    // 只在列表里确实渲染出该角色时才滚，避免切到被搜索过滤掉的角色时乱跳。
                    if (activeItem && activeItem.dataset.friendId === targetId) {
                        activeItem.scrollIntoView({ block: 'nearest' });
                    }
                } catch (e) { /* 滚动失败不影响列表渲染 */ }
            }

            // ========== 性能优化：头像懒加载 ==========
            initLazyAvatars();
        }

        // 头像懒加载观察者
        let lazyAvatarObserver = null;

        // 同时只允许这么多张占位头像在跑「流光」动画。
        // .lazy-avatar 的 lazyShimmer 是 **infinite** 动画，而这里的占位元素
        // 在头像加载完成前一直挂着；角色多、或头像加载失败时，
        // 几十张 36px 圆形一起做 background-position 动画，是典型的「莫名有点卡」来源
        // （修 ??? 模式时排查到的残留常驻动画之一）。超出的部分改用静态底色：
        // 它们大多在屏幕外，用户根本看不到流光，却要一直付渲染代价。
        const LAZY_AVATAR_ANIM_MAX = 8;

        function initLazyAvatars() {
            // 如果浏览器不支持 IntersectionObserver，直接加载所有头像
            if (!('IntersectionObserver' in window)) {
                document.querySelectorAll('.lazy-avatar').forEach(img => {
                    img.src = img.dataset.src;
                    img.classList.remove('lazy-avatar');
                });
                return;
            }

            // 销毁旧的观察者
            if (lazyAvatarObserver) {
                lazyAvatarObserver.disconnect();
            }

            // 给占位动画设上限：只让前 N 张（即最靠上、最可能可见的）保持流光，
            // 其余换成同色静态底，视觉上几乎无差别，但不再长期占用合成/绘制预算。
            const placeholders = Array.from(document.querySelectorAll('.lazy-avatar'));
            placeholders.forEach((img, i) => {
                if (i < LAZY_AVATAR_ANIM_MAX) return;
                img.classList.add('lazy-avatar--static');
                // 已经等了几秒还没被观察到（大概率在屏幕外）：直接补上 src，
                // 让浏览器按需解码，同时把 infinite 动画彻底摘掉。
                setTimeout(() => {
                    if (!img.classList.contains('lazy-avatar')) return;
                    try { if (img.dataset.src) img.src = img.dataset.src; } catch (e) {}
                    img.classList.remove('lazy-avatar');
                }, 6000);
            });

            // 创建新的观察者
            lazyAvatarObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const img = entry.target;
                        img.src = img.dataset.src;
                        img.classList.remove('lazy-avatar');
                        lazyAvatarObserver.unobserve(img);
                    }
                });
            }, { rootMargin: '100px' }); // 提前 100px 开始加载

            // 观察所有懒加载头像
            document.querySelectorAll('.lazy-avatar').forEach(img => {
                lazyAvatarObserver.observe(img);
            });
        }

        function showFriendContextMenu(e, friendId) {
            e.preventDefault();
            e.stopPropagation();
            currentFriendMenuTarget = friendId;

            const pinned = isFriendPinned(friendId);
            pinText.textContent = pinned ? '取消置顶' : '置顶';


            const friend = friendsData[friendId];
            const isBuiltIn = isBuiltInFriend(friendId);
            menuChangeAvatar.style.display = friend && !friend.isGroup ? "flex" : "none";
            menuResetAvatar.style.display = friend && !friend.isGroup && isFriendAvatarCustomized(friendId) ? "flex" : "none";
            menuChangeGroup.style.display = friend && !friend.isGroup ? "flex" : "none";
            menuCreateGroupFromChat.style.display = friend && !friend.isGroup ? "flex" : "none";
            // 自定义角色仅支持彻底删除；内置角色同时提供保留记录的移除方式。
            menuDeleteFriend.style.display = friend && !friend.isGroup ? "flex" : "none";
            menuRemoveBuiltIn.style.display = isBuiltIn ? "flex" : "none";
            // 群聊：给「群容器自己」两个入口（群聊不是角色，上面的角色菜单项对它全部隐藏）。
            // 侧边栏右键群聊 / 聊天区右键群头像都走这里。
            if (menuGroupAvatar) menuGroupAvatar.style.display = friend?.isGroup ? "flex" : "none";
            if (menuGroupDisband) menuGroupDisband.style.display = friend?.isGroup ? "flex" : "none";
            const rect = e.currentTarget?.getBoundingClientRect?.() || e.target.getBoundingClientRect();
            const gap = 6;
            const viewportPadding = 8;

            // 先显示以获得真实菜单尺寸；若下方空间不足则翻转到触发项上方。
            toggleFriendContextMenu(true);
            const menuRect = friendContextMenu.getBoundingClientRect();
            const availableBelow = window.innerHeight - rect.bottom - gap - viewportPadding;
            const placeAbove = menuRect.height > availableBelow && rect.top - gap >= menuRect.height + viewportPadding;
            const top = placeAbove
                ? rect.top - menuRect.height - gap
                : Math.min(rect.bottom + gap, window.innerHeight - menuRect.height - viewportPadding);
            const left = Math.min(
                Math.max(viewportPadding, rect.left),
                Math.max(viewportPadding, window.innerWidth - menuRect.width - viewportPadding)
            );
            friendContextMenu.style.left = `${left}px`;
            friendContextMenu.style.top = `${Math.max(viewportPadding, top)}px`;
        }

        menuTogglePin?.addEventListener('click', () => {
            if (currentFriendMenuTarget) {
                const pinned = !isFriendPinned(currentFriendMenuTarget);
                setFriendPinned(currentFriendMenuTarget, pinned);
                renderFriendList();
                showToast(`${getFriendDisplayName(currentFriendMenuTarget)} ${pinned ? '已置顶' : '已取消置顶'}`, pinned ? 'ri-pushpin-line' : 'ri-pushpin-2-line');
            }
            toggleFriendContextMenu(false);
        });

        menuSetRemark?.addEventListener('click', async () => {
            // 先把目标 id 固定下来：await 期间用户可能又点了别的角色
            const targetId = currentFriendMenuTarget;
            if (targetId && friendsData[targetId]) {
                toggleFriendContextMenu(false);
                const newRemark = await Dlg.prompt({
                    title: '设置备注',
                    message: `为「${friendsData[targetId].name}」设置备注（留空则清除）：`,
                    value: getFriendRemark(targetId),
                    placeholder: '例如：老搭档',
                    maxLength: 20,
                    okText: '保存'
                });
                if (newRemark !== null) {
                    setFriendRemark(targetId, newRemark.trim());
                    renderFriendList();
                    if (currentFriendId === targetId) {
                        currentFriendNameElement.textContent = getFriendDisplayName(currentFriendId);
                    }
                    showToast(`备注已${newRemark.trim() ? '更新' : '清除'}`, 'ri-edit-line');
                }
            } else {
                toggleFriendContextMenu(false);
            }
        });


        menuChangeAvatar?.addEventListener('click', (e) => {
            // 先阻止冒泡：这次点击会继续冒泡到 document 上的「点击空白处关闭菜单」监听，
            // 而 e.target 并不在 aiAvatarContextMenu 内部，于是刚打开的头像菜单
            // 会被立刻关掉 —— 用户看到的现象就是「点『更换头像』没反应」。
            e.stopPropagation();
            e.preventDefault();
            const targetId = currentFriendMenuTarget;
            toggleFriendContextMenu(false);
            if (!targetId) return;
            currentAiAvatarTarget = targetId;
            syncAiMenuResetVisibility(targetId);
            chooseFriendAvatarSource(targetId);
        });

        menuGroupAvatar?.addEventListener('click', (e) => {
            e.stopPropagation();
            const targetId = currentFriendMenuTarget;
            toggleFriendContextMenu(false);
            if (!targetId || !groupManager[targetId]) return;
            chooseFriendAvatarSource(targetId);
        });

        menuGroupDisband?.addEventListener('click', (e) => {
            e.stopPropagation();
            const targetId = currentFriendMenuTarget;
            toggleFriendContextMenu(false);
            if (!targetId || !groupManager[targetId]) return;
            disbandGroupChat(targetId);
        });

        // 角色头像菜单里的「解散群聊」：右键群聊头像时出现
        aiMenuDisbandGroup?.addEventListener('click', (e) => {
            e.stopPropagation();
            const targetId = currentAiAvatarTarget;
            toggleAiAvatarMenu(false);
            if (!targetId || !groupManager[targetId]) return;
            disbandGroupChat(targetId);
        });

        menuResetAvatar?.addEventListener('click', () => {
            if (currentFriendMenuTarget) restoreFriendAvatar(currentFriendMenuTarget);
            toggleFriendContextMenu(false);
        });

        menuChangeGroup?.addEventListener('click', () => {
            if (!currentFriendMenuTarget) return;


            // 统一走 collectAllGroups()：这样在「分组管理」里新建的分组
            // （哪怕还没放任何角色）也会出现在这份「移动到」列表里
            const groups = collectAllGroups();
            const currentGroup = getFriendGroup(currentFriendMenuTarget);


            let groupHtml = '';
            groups.forEach(g => {
                const activeClass = g === currentGroup ? 'active' : '';
                const count = Object.values(friendsData).filter(f => getFriendGroup(f.id) === g).length;
                // 分组名是用户自己输入的，写入 innerHTML 前必须转义
                groupHtml += `
                    <div class="friend-group-option ${activeClass}" data-group="${escapeHtml(g)}">
                        <span>${escapeHtml(g)} (${count})</span>
                        ${g === currentGroup ? '<i class="ri-check-line"></i>' : ''}
                    </div>
                `;
            });


            friendGroupModalTitle.textContent = '选择分组';
            friendGroupModalBody.innerHTML = `
                <div class="friend-group-list">
                    ${groupHtml}
                </div>
            `;


            const options = friendGroupModalBody.querySelectorAll('.friend-group-option');
            let selectedGroup = currentGroup;

            options.forEach(opt => {
                opt.addEventListener('click', () => {
                    options.forEach(o => {
                        o.classList.remove('active');
                        o.querySelector('i')?.remove();
                    });
                    opt.classList.add('active');
                    const checkIcon = document.createElement('i');
                    checkIcon.className = 'ri-check-line';
                    opt.appendChild(checkIcon);
                    selectedGroup = opt.getAttribute('data-group');
                });
            });


            toggleFriendGroupModal(true);


            friendGroupConfirmBtn.onclick = () => {
                if (currentFriendMenuTarget && selectedGroup) {
                    setFriendGroup(currentFriendMenuTarget, selectedGroup);
                    renderFriendList();
                    showToast(`已移动分组至「${selectedGroup}」`, 'ri-folder-move-line');
                }
                toggleFriendGroupModal(false);
            };

            toggleFriendContextMenu(false);
        });


        menuDeleteFriend?.addEventListener('click', async () => {
            const targetId = currentFriendMenuTarget;
            if (!targetId) return;

            const friend = friendsData[targetId];
            if (!friend || friend.isGroup) {
                toggleFriendContextMenu(false);
                return;
            }

            toggleFriendContextMenu(false);
            const confirmDelete = await Dlg.confirm({
                title: '删除角色',
                message: `确定要删除角色「${getFriendDisplayName(targetId)}」和全部聊天记录吗？\n\n此操作不可恢复！`,
                okText: '确认删除',
                danger: true
            });
            if (!confirmDelete) return;
            // 等待确认期间数据可能已被改动，重新校验再删
            if (!friendsData[targetId]) { renderFriendList(); return; }


            // 内置角色彻底删除后不再随刷新自动出现，可在“添加好友”中恢复。
            if (isBuiltInFriend(targetId)) {
                saveRemovedBuiltInFriendIds([...getRemovedBuiltInFriendIds(), targetId]);
            }
            // 「角色卡市场」添加的角色：删除后要从添加记录里摘掉，
            // 否则下次打开网站又会被 applyInstalledPresetCards 重建回来。
            try {
                const cards = JSON.parse(localStorage.getItem('installedPresetCards') || '{}');
                if (cards && cards[targetId]) {
                    delete cards[targetId];
                    setLocalStorageSafely('installedPresetCards', JSON.stringify(cards), '角色卡添加记录');
                }
            } catch (e) { /* 记录损坏时按未添加处理 */ }
            delete friendsData[targetId];


            if (threadManager[targetId]) {
                delete threadManager[targetId];
            }


            saveCustomFriendsData();
            saveThreadManager();


            if (currentFriendId === targetId) {
                const remainingFriends = Object.keys(friendsData);
                if (remainingFriends.length > 0) {
                    switchFriend(remainingFriends[0]);
                } else {
                    currentFriendId = null;
                    chatMessages.innerHTML = '<div style="text-align:center;color:#888;margin-top:50px;">暂无好友，请添加新角色</div>';
                    currentFriendNameElement.textContent = '无';
                }
            } else {
                renderFriendList();
            }

            showToast(`已删除好友「${friend.name}」`, "ri-delete-bin-line");
        });

        menuRemoveBuiltIn?.addEventListener('click', async () => {
            const friendId = currentFriendMenuTarget;
            const friend = friendsData[friendId];
            if (!friend || !isBuiltInFriend(friendId)) return;
            toggleFriendContextMenu(false);
            if (!await Dlg.confirm({
                title: '移除角色',
                message: `删除角色「${getFriendDisplayName(friendId)}」但保留聊天记录？\n\n以后可在“添加好友”中重新添加该内置角色并恢复记录。`,
                okText: '移除角色',
                danger: true
            })) return;
            if (!friendsData[friendId]) { renderFriendList(); return; }
            saveRemovedBuiltInFriendIds([...getRemovedBuiltInFriendIds(), friendId]);
            // 市场添加的角色：保留角色卡正文（重新添加时不用再下载），只标记移出。
            try {
                const cards = JSON.parse(localStorage.getItem('installedPresetCards') || '{}');
                if (cards && cards[friendId]) {
                    cards[friendId].removed = true;
                    setLocalStorageSafely('installedPresetCards', JSON.stringify(cards), '角色卡添加记录');
                }
            } catch (e) { /* 忽略 */ }
            delete friendsData[friendId];
            saveThreadManager();
            if (currentFriendId === friendId) {
                const nextFriendId = Object.keys(friendsData)[0];
                if (nextFriendId) switchFriend(nextFriendId);
            } else renderFriendList();
            showToast(`已移除角色「${friend.name}」，聊天记录已保留`, 'ri-user-unfollow-line');
            toggleFriendContextMenu(false);
        });

        menuCreateGroupFromChat?.addEventListener('click', async () => {
            const friendId = currentFriendMenuTarget;
            if (!friendsData[friendId] || friendsData[friendId].isGroup) return;
            toggleFriendContextMenu(false);
            await createGroupChatFromFriend(friendId);
        });

        function switchFriend(friendId) {
            clearTimeout(proactiveCareTimer);
            proactiveCareTimer = null;
            proactiveCareSequence += 1;
            // 剧场回放期间渲染被锁，必须先退出，否则新角色的消息一条也画不出来
            try { window.TheaterMode?.isActive?.() && window.TheaterMode.stop(); } catch (e) { /* 功能未开启 */ }
            // 上一条回复还在生成时，思考中的气泡属于旧对话。先摘掉，避免它被 renderMessages 清空前闪到新角色上，
            // 也避免流式结束时误删新对话里恰好同 id 的节点。
            document.querySelectorAll('[id^="loading-"], [id^="group-loading-"]').forEach(node => node.remove());
            if (isBatchEditMode) {
                isBatchEditMode = false;
                selectedCustomFriends.clear();
                updateBatchActionButtons();
            }
            document.querySelector('.quick-replies')?.remove();
            const previousFriendId = currentFriendId;
            // 关键顺序：先把当前输入框内容落盘到「上一个角色」的草稿键，
            // 再改 currentFriendId。反过来的话 saveMessageDraftNow 会按新角色写，
            // 等于把 A 的草稿存成 B 的草稿。
            if (previousFriendId && previousFriendId !== friendId) saveMessageDraftNow();
            currentFriendId = friendId;
            if (!threadManager[friendId]) {
                threadManager[friendId] = { threads: [{ id: 1, name: '初始对话', messages: [] }], currentThreadId: 1, longTermMemory: [] };
                saveThreadManager();
            }

            const friend = friendsData[friendId];
            // 用户点进某个角色的聊天，才开始加载它的角色提示词。
            // 其余角色的提示词不进内存 —— 这就是「不用的角色不加载」这条规则的落点。
            loadFriendPrompt(friendId);
            if (friend) {
                currentFriendNameElement.textContent = getFriendDisplayName(friendId);
                currentFriendNameElement.title = isGroupChat(friendId) ? '双击管理群聊成员、发言顺序和活跃度' : '';
            }


            setLocalStorageSafely('lastChatId', friendId);

            // 进角色时顺手修一次重复 id（只扫当前对话，很快；有改动才落盘）
            try {
                const th = getCurrentThread();
                if (th && dedupeThreadMessageIds(th) > 0) saveThreadManager();
            } catch (e) { /* 自愈失败不影响进入聊天 */ }

            // 先画聊天区:侧栏刷新若抛错,不能让聊天记录一起消失(启动时正是这样)
            renderMessages(friendId);
            try { renderFriendList(); } catch (e) { console.warn('[切换角色] 侧栏刷新失败(不影响聊天显示):', e); }

            // 侧栏滚到当前角色：置位交给 _renderFriendListImpl 执行。
            // 「角色卡市场 → 去聊天」这类深链进入时，目标角色可能排在列表很下面
            // (74+ 个角色、列表区高 660px)，不滚过去的话侧栏停在顶部，
            // 看起来像「一个都没选中」，用户得自己往下找。
            pendingRevealFriendId = friendId;

            // 高级动效：切角色时让聊天区做一次「聚焦」入场（仅？？？模式，且非轻量档）
            try { window.MotionFX?.viewIn?.(); } catch (e) { /* 动效失败不影响功能 */ }
            // 好感度徽标要跟着当前角色切换
            try { window.Affinity?.onFriendChanged?.(); } catch (e) { /* 忽略 */ }

            // ========== 进入角色聊天自动滚到底部 ==========
            // 使用 requestAnimationFrame 等待 DOM 完成 + 虚拟滚动撑高后再滚到底，
            // 避免出现"用户进聊天还要手动滑到上次聊到的地方"的体验问题。
            const scrollToEndSafely = () => {
                try {
                    if (typeof scrollToBottom === 'function') {
                        scrollToBottom();
                    } else {
                        chatMessages.scrollTop = chatMessages.scrollHeight;
                    }
                } catch (e) { /* 静默忽略 */ }
            };
            requestAnimationFrame(() => {
                scrollToEndSafely();
                // 二次保险：200ms 后再滚一次（应对消息渲染和懒加载头像完成）
                setTimeout(scrollToEndSafely, 200);
            });
            // 切角色时清掉未读徽标
            unreadWhileAway = 0;
            updateScrollToBottomBadge();
            scheduleScrollToBottomButtonUpdate();

            // 切角色必须同时切换「输入框里的草稿」：
            // 旧实现只在 init() 里 restoreMessageDraft 一次，切到别的角色后上一个角色的
            // 未发送文字仍留在输入框里（还会把输入框撑成多行），既容易误发，
            // 看起来也正是用户说的「聊天框莫名其妙变大、多出好几行」。
            // 上一个角色的草稿已在上面（改 currentFriendId 之前）同步落盘。
            if (previousFriendId !== friendId) restoreMessageDraft();
            autoResizeMessageInput();
            if (typeof hideMentionMenu === 'function') hideMentionMenu();

            // 清空快捷回复区域，避免上一个角色的回复残留
            document.querySelector('.quick-replies')?.remove();
            try { window.VNMode?.clearChoices?.(); } catch (e) {}

            // 如果设置弹窗打开且处于长期记忆标签页，刷新记忆档案列表
            const activeTab = document.querySelector('.tab-button.active');
            if (activeTab && activeTab.dataset.tab === 'longterm-memory') {
                renderMemoryProfileList();
            }
        }

        // ========== 虚拟滚动（「界面外观」里可开关，默认关） ==========
        // 旧实现按固定 120px 估算每条消息，长短混排时会篡改滚动位置（向下滑被拉回）。
        // 现在的实现：渲染后实测每条真实高度并缓存，padding 与滚动锚点都按实测值计算。
        const VIRTUAL_SCROLL_CONFIG = {
            estimatedHeight: 96,   // 未实测消息的初始估算高度（有实测样本后改用样本均值）
            overscan: 6,           // 视口外上下各多渲染几条，避免快速滚动露白
            minMessagesForVirtual: 80,
            rerenderStep: 300,     // 向下滚过这个像素数才重建窗口（配合 overscan 不露白）
            estFloor: 48,          // 估算均值下限
            estCeil: 600,          // 估算均值上限（防止一条超长消息把整体估算抬爆）
            maxCachedHeights: 4000 // 高度缓存上限，超过即整体清空（换角色/长会话累积）
        };

        function isVirtualScrollEnabled() {
            try { return getChatSettings().enableVirtualScroll === true; } catch (e) { return false; }
        }

        // 虚拟滚动状态。
        // heights 以前按「消息序号 → 实测高度」缓存，序号会随「显示限制截取 / 换对话 /
        // 插入新消息」整体位移，缓存跟着错位，越滚越偏（一路偏到聊天区全白）。
        // 现在改按**消息 id** 缓存：id 由 dedupeThreadMessageIds 保证唯一，位移不会串号。
        let virtualScrollState = {
            forFriend: null,
            heights: new Map(),      // key: 'id:xxx' → 实测像素高
            estAvg: 0,               // 实测高度均值（用于未测消息的估算，长消息场景比固定 96 准得多）
            scrollTop: 0,
            containerHeight: 0,
            startIndex: 0,
            endIndex: 0,
            startOffset: 0,          // 窗口首条在内容坐标里的顶部位置（滚动时增量维护，不重算）
            lastStartOffset: 0,
            wasAtBottom: false,
            suppressUntil: 0,
            expectedScrollTop: -1,   // 上一次「程序化」设置的 scrollTop，用于区分用户滚动
            estRelayouted: false,    // 估算基准定下来后是否已重新排过版（只排一次）
            lastStableSh: 0
        };

        function vsResetHeights(friendId) {
            if (virtualScrollState.forFriend !== friendId) {
                virtualScrollState.heights.clear();
                virtualScrollState.estAvg = 0;
                virtualScrollState.estRelayouted = false;
                virtualScrollState.forFriend = friendId;
                virtualScrollState.lastStartOffset = 0;
                virtualScrollState.lastStableSh = 0;
                virtualScrollState.suppressUntil = 0;
            }
        }

        /** 彻底清掉虚拟滚动的一切运行态（关开关 / 恢复默认 / 换角色时调用） */
        function vsClearCache() {
            virtualScrollState.heights.clear();
            virtualScrollState.estAvg = 0;
            virtualScrollState.startIndex = 0;
            virtualScrollState.endIndex = 0;
            virtualScrollState.startOffset = 0;
            virtualScrollState.lastStartOffset = 0;
            virtualScrollState.lastStableSh = 0;
            virtualScrollState.suppressUntil = 0;
            virtualScrollState.expectedScrollTop = -1;
            virtualScrollState.estRelayouted = false;
            try { chatMessages.classList.remove('vs-active'); } catch (e) { }
        }

        /** 消息的缓存 key：优先用 id（唯一且稳定），没有 id 才退回序号 */
        function vsKeyOf(msg, i) {
            const id = msg && msg.id;
            if (id !== undefined && id !== null && id !== '') return 'id:' + id;
            return 'ix:' + i;
        }
        /** 未实测消息的估算高度：有样本时用实测均值，比固定值贴近真实布局 */
        function vsEstimate() {
            const a = virtualScrollState.estAvg;
            if (!a || a <= 0) return VIRTUAL_SCROLL_CONFIG.estimatedHeight;
            return Math.min(VIRTUAL_SCROLL_CONFIG.estCeil, Math.max(VIRTUAL_SCROLL_CONFIG.estFloor, Math.round(a)));
        }
        function vsHeightOfMsg(msg, i) {
            const h = virtualScrollState.heights.get(vsKeyOf(msg, i));
            return h > 0 ? h : vsEstimate();
        }
        function vsOffsetOf(messages, index) {
            let s = 0;
            for (let i = 0; i < index; i++) s += vsHeightOfMsg(messages[i], i);
            return s;
        }
        /** 记录一条实测高度，同时用指数平滑维护均值（估算用） */
        function vsRememberHeight(msg, i, h) {
            if (!(h > 0)) return false;
            if (virtualScrollState.heights.size > VIRTUAL_SCROLL_CONFIG.maxCachedHeights) {
                virtualScrollState.heights.clear();
            }
            const key = vsKeyOf(msg, i);
            const old = virtualScrollState.heights.get(key);
            virtualScrollState.heights.set(key, h);
            /* 估算基准（未测消息按多高算）只在「首屏还没定稿」时用滑动平均学：
               第一屏量到的可能恰好是最短的一条（一句"嗯"），拿它当基准会让
               整个坐标系缩水好几倍 —— 滚一格就翻过十几条，这也是要避免的。
               首屏重排之后立刻冻结：再让它随测量漂移，前面几千条未测消息的
               高度和会整体变形，占位符与滚动位置瞬间脱节。
               估算偏一点无所谓 —— 屏幕里显示的内容永远以实测高度为准。 */
            if (!virtualScrollState.estRelayouted) {
                const avg = virtualScrollState.estAvg > 0 ? virtualScrollState.estAvg * 0.7 + h * 0.3 : h;
                virtualScrollState.estAvg = Math.min(VIRTUAL_SCROLL_CONFIG.estCeil, Math.max(VIRTUAL_SCROLL_CONFIG.estFloor, avg));
            }
            return !(old && Math.abs(old - h) <= 1);
        }

        /* 消息节点被「性能补丁」的 content-visibility:auto 跳过渲染时，offsetHeight 会读成 0，
           虚拟滚动据此测量的缓存全错、窗口算出来是空的 —— 就是「滚一下就白屏」的元凶。
           这里给窗口内的节点内联关掉该属性（只影响当前这十几条，代价可以忽略），
           保证测量拿到的是真实高度。 */
        function vsForceMeasureable(node) {
            if (!node || !node.style) return;
            const cs = window.getComputedStyle ? getComputedStyle(node) : null;
            if (cs && cs.contentVisibility && cs.contentVisibility !== 'visible') {
                node.style.contentVisibility = 'visible';
                node.style.containIntrinsicSize = 'none';
            }
        }

        // renderMessages 防抖 - 防止短时间内多次触发全量重绘
        let renderMessagesDebounceTimer = null;

        function isChatNearBottom(threshold = 80) {
            return chatMessages.scrollHeight - chatMessages.scrollTop - chatMessages.clientHeight <= threshold;
        }

        // ---------- 回到最新消息（悬浮下箭头按钮）----------
        const scrollToBottomBtn = document.getElementById('scroll-to-bottom-btn');
        let scrollBtnRaf = 0;

        // 用户离开底部期间收到的 AI 新消息数量（用于按钮上的小红点数字）
        let unreadWhileAway = 0;

        function updateScrollToBottomBadge() {
            const badge = document.getElementById('scroll-to-bottom-badge');
            if (!badge) return;
            if (unreadWhileAway > 0) {
                badge.hidden = false;
                badge.textContent = unreadWhileAway > 99 ? '99+' : String(unreadWhileAway);
            } else {
                badge.hidden = true;
                badge.textContent = '';
            }
        }

        function updateScrollToBottomButton() {
            if (!scrollToBottomBtn) return;
            const distance = chatMessages.scrollHeight - chatMessages.scrollTop - chatMessages.clientHeight;
            // 离底部还差一屏的 1/6 或 120px 以上时才出现，轻微滚动不会闪出按钮
            const threshold = Math.max(120, Math.min(320, Math.round(chatMessages.clientHeight / 6)));
            const show = distance > threshold;
            if (!show) unreadWhileAway = 0;      // 已经到底：未读清零
            scrollToBottomBtn.classList.toggle('show', show);
            scrollToBottomBtn.hidden = !show;
            if (show) positionScrollToBottomButton();
            updateScrollToBottomBadge();
        }

        /**
         * 把悬浮按钮摆在「聊天区底部 + 输入区高度」之上。
         * 输入区高度是动态的（多行输入、待发送附件、手机软键盘都会改变它），
         * 因此每次显示时都实测一次并写进 --stb-bottom，避免按钮压住输入框。
         */
        function positionScrollToBottomButton() {
            if (!scrollToBottomBtn) return;
            const area = document.querySelector('.chat-area');
            const inputArea = document.querySelector('.chat-input-area');
            if (!area || !inputArea) return;
            const areaRect = area.getBoundingClientRect();
            const inputRect = inputArea.getBoundingClientRect();
            if (!inputRect.height || !areaRect.height) return;
            const offset = Math.max(12, Math.round(areaRect.bottom - inputRect.top) + 12);
            const width = scrollToBottomBtn.offsetWidth || 40;
            // 极矮视口下别把按钮顶到聊天区外
            const safe = Math.min(offset, Math.max(12, Math.round(areaRect.height - width - 12)));
            scrollToBottomBtn.style.setProperty('--stb-bottom', safe + 'px');
        }

        /** AI 回复渲染时调用：如果用户不在底部，累计未读数 */
        function noteNewMessageWhileAway() {
            if (isChatNearBottom(120)) return;
            unreadWhileAway = Math.min(999, unreadWhileAway + 1);
            scheduleScrollToBottomButtonUpdate();
        }
        window.noteNewMessageWhileAway = noteNewMessageWhileAway;

        function scheduleScrollToBottomButtonUpdate() {
            if (scrollBtnRaf) return;
            scrollBtnRaf = requestAnimationFrame(() => {
                scrollBtnRaf = 0;
                updateScrollToBottomButton();
            });
        }

        if (scrollToBottomBtn) {
            scrollToBottomBtn.addEventListener('click', () => {
                unreadWhileAway = 0;
                chatMessages.scrollTo({ top: chatMessages.scrollHeight, behavior: 'smooth' });
                // 部分浏览器对容器的平滑滚动支持不佳（或开启了「减少动效」），兜底直接落底
                setTimeout(() => {
                    if (!isChatNearBottom(4)) chatMessages.scrollTop = chatMessages.scrollHeight;
                    updateScrollToBottomButton();
                }, 420);
                updateScrollToBottomButton();
            });
            chatMessages.addEventListener('scroll', scheduleScrollToBottomButtonUpdate, { passive: true });
            window.addEventListener('resize', scheduleScrollToBottomButtonUpdate);
            // 消息区内容变化（新消息、图片加载完成后高度变化）也要同步按钮状态
            if (typeof MutationObserver !== 'undefined') {
                const stbObserver = new MutationObserver(() => scheduleScrollToBottomButtonUpdate());
                stbObserver.observe(chatMessages, { childList: true, subtree: true });
            }
            // 图片/视频加载完成后高度会变化，需要重算
            chatMessages.addEventListener('load', scheduleScrollToBottomButtonUpdate, true);
            requestAnimationFrame(updateScrollToBottomButton);
        }

        function restoreChatScroll(position, forceBottom = false) {
            const apply = () => {
                if (forceBottom) {
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                } else {
                    const maxScrollTop = Math.max(0, chatMessages.scrollHeight - chatMessages.clientHeight);
                    chatMessages.scrollTop = Math.min(position, maxScrollTop);
                }
            };
            // 图片、字体和分段内容可能在本帧后继续改变高度；仅在本次重绘完成后校正，
            // 防止设置保存、投票刷新等操作把用户从正在阅读的位置拉走。
            requestAnimationFrame(() => { apply(); scheduleScrollToBottomButtonUpdate(); });
            setTimeout(() => { apply(); scheduleScrollToBottomButtonUpdate(); }, 120);
            /* 第三跳是给「性能补丁」的 content-visibility 留的：全量渲染时离屏消息
               先按估算高度折叠，滚到底之后浏览器才逐条真渲染，scrollHeight 会继续
               变大。只补到 120ms 的话，最后往往停在离底部差一屏的位置 ——
               用户一进对话就发现「没在最新消息上」。 */
            if (forceBottom) setTimeout(() => { apply(); scheduleScrollToBottomButtonUpdate(); }, 600);
        }
        
        /**
         * 「显示限制」截取后的消息列表。
         * 单独抽出来是因为剧场回放必须用**和渲染完全相同的口径**建播放列表：
         * 若回放按 getMessages() 全量计数、而画面只画了被截取的尾部，
         * 进度条就会一路跑到画面前面 —— 正是「显示播到第 8 条、画面还在第 6 条」的成因之一。
         */
        function getDisplayLimitedMessages() {
            let messages = getMessages();
            const chatSettings = getChatSettings();
            if (chatSettings.enableDisplayLimit && chatSettings.displayLimitRounds > 0) {
                const limitRounds = Math.max(1, chatSettings.displayLimitRounds);
                const maxMessages = limitRounds * 2;
                if (messages.length > maxMessages) messages = messages.slice(-maxMessages);
            }
            return messages;
        }

        function renderMessages(friendId, options = {}) {
            const preserveScroll = options.preserveScroll !== false;
            const scrollPosition = preserveScroll ? chatMessages.scrollTop : 0;
            const shouldStayAtBottom = options.forceBottom === true || (preserveScroll && isChatNearBottom());
            // 防抖：100ms 内多次调用只执行最后一次；保留最后一次请求的滚动策略。
            if (renderMessagesDebounceTimer) {
                clearTimeout(renderMessagesDebounceTimer);
            }
            renderMessagesDebounceTimer = setTimeout(() => {
                renderMessagesDebounceTimer = null;
                _renderMessagesImpl(friendId, { scrollPosition, shouldStayAtBottom });
            }, 100);
        }
        
        function _renderMessagesImpl(friendId, scrollState = {}) {
            // ------------------------------------------------------------
            // 剧场模式（对话回放）协作：
            //   · __theaterLocked 为真时**直接吞掉本次渲染** —— 回放期间任何
            //     后台重绘（消息发送、好感度刷新、窗口 resize、虚拟滚动）都会
            //     重建 DOM，把已经标成「已播放」的气泡洗掉，于是出现
            //     「进度显示第 8 条、画面还在第 6 条」。
            //   · __theaterMode 为真时强制走完整渲染，不走虚拟滚动：
            //     虚拟滚动只保留可视窗口内的节点，滚动即销毁重建，回放根本无法进行。
            // ------------------------------------------------------------
            if (window.__theaterLocked === true) return;
            const friend = friendsData[friendId];
            // 应用显示限制设置 - 按对话轮数截取（抽成函数，供剧场回放共用同一口径）
            let messages = getDisplayLimitedMessages();

            // 消息较少时不启用虚拟滚动；剧场模式必须完整渲染（见上方说明）
            dbgLog('[VS] decide', 'theater', window.__theaterMode, 'enabled', isVirtualScrollEnabled(), 'len', messages.length);
            if (window.__theaterMode === true || !isVirtualScrollEnabled() || messages.length < VIRTUAL_SCROLL_CONFIG.minMessagesForVirtual) {
                renderMessagesSimple(messages, friend, friendId);
                restoreChatScroll(scrollState.scrollPosition || 0, Boolean(scrollState.shouldStayAtBottom));
                if (chatSearchInput?.value) updateChatSearch();
                return;
            }

            // 启用虚拟滚动。
            // 注意：不要在这里调 restoreChatScroll —— 它内部用 rAF/120ms 延迟 apply，
            // 拿到的是上一轮全量 DOM 状态下捕获的 scrollPosition，会把刚由
            // calculateVisibleRange/spacer 安排好的位置拖回去，进而触发 scroll →
            // rerender 的 ping-pong 死循环。位置维护完全交给虚拟滚动自身：
            // 贴底由 renderMessagesVirtual 收尾贴底，非贴底由 vsMeasureAndReconcile 锚点补偿。
            renderMessagesVirtual(messages, friend, friendId);
            if (chatSearchInput?.value) updateChatSearch();
        }

        /**
         * 单条消息的安全渲染：appendMessageToDOM 内部依赖多（marked/DOMPurify/群成员表/头像），
         * 任何一条消息抛异常都不该让 forEach 中断 —— 中断的后果是坏消息之后的
         * 所有记录（往往正是最新的对话）全部消失。失败时降级为纯文本气泡。
         */
        /* 论坛分享卡片:消息带 forumShare 字段时渲染为可点击卡片,点击跳转到论坛对应帖子 */
        function appendForumShareNode(msg, friend, friendId) {
            const mine = msg.role === 'mine';
            const share = msg.forumShare || {};
            const wrap = document.createElement('div');
            wrap.className = 'message ' + (mine ? 'mine' : 'other');
            wrap.dataset.role = msg.role;
            wrap.dataset.messageId = msg.id || msg.timestamp;
            const avatar = document.createElement('img');
            avatar.className = 'avatar';
            avatar.src = mine ? (inputAvatar ? inputAvatar.src : '') : ((friend && friend.avatar) || '');
            const content = document.createElement('div');
            content.className = 'message-content';
            const nick = document.createElement('span');
            nick.className = 'nickname';
            nick.textContent = mine ? myUserName : getFriendDisplayName(friendId);
            const card = document.createElement('div');
            card.className = 'forum-share-card';
            card.tabIndex = 0;
            card.setAttribute('role', 'link');
            card.title = '打开论坛帖子';
            const tag = document.createElement('div');
            tag.className = 'fsc-tag';
            tag.innerHTML = '<i class="ri-discuss-line"></i> 论坛分享';
            const title = document.createElement('div');
            title.className = 'fsc-title';
            title.textContent = share.title || '未命名帖子';
            const meta = document.createElement('div');
            meta.className = 'fsc-meta';
            /* 分类放在自己的 span 里：它和作者名原本拼成一个字符串，
               整段替换会把用户名也一起翻掉，拆开才能只译分类。 */
            if (share.board) {
                const bd = document.createElement('span');
                bd.className = 'fsc-board';
                bd.textContent = share.board;
                meta.appendChild(bd);
            }
            if (share.board && share.author) meta.appendChild(document.createTextNode(' · '));
            if (share.author) {
                const au = document.createElement('span');
                au.className = 'fsc-author';
                au.textContent = share.author;
                meta.appendChild(au);
            }
            const excerpt = document.createElement('div');
            excerpt.className = 'fsc-excerpt';
            excerpt.textContent = share.excerpt || '';
            const hint = document.createElement('div');
            hint.className = 'fsc-hint';
            hint.innerHTML = '点击查看帖子 <i class="ri-arrow-right-s-line"></i>';
            card.append(tag, title, meta, excerpt, hint);
            const open = () => {
                if (!share.postId) return;
                window.location.href = 'forum.html?post=' + encodeURIComponent(share.postId);
            };
            card.addEventListener('click', open);
            card.addEventListener('keydown', e => { if (e.key === 'Enter') open(); });
            content.append(nick, card);
            wrap.append(avatar, content);
            chatMessages.appendChild(wrap);
        }

        /* 批量重绘（切对话/改设置/恢复备份）时不播入场动画：
           否则每条历史都会重播一次 translateY，看起来像整屏在抖。 */
        let bulkRendering = 0;

        function appendMessageNodeSafely(msg, friend, friendId) {
            if (msg && msg.forumShare) { appendForumShareNode(msg, friend, friendId); return; }
            try {
                const speakerId = msg.friendId || friendId;
                const speaker = friendsData[speakerId] || friend;
                const avatarSrc = msg.role === 'mine' ? inputAvatar.src : (msg.role === 'system' ? (friendsData[friendId]?.avatar || speaker.avatar) : speaker.avatar);
                const nickName = msg.role === 'mine' ? myUserName : (msg.role === 'system' ? (msg.isCompressed ? '上下文摘要' : '群内通报') : (isGroupChat(friendId) ? getGroupMemberLabel(groupManager[friendId], speakerId) : getFriendDisplayName(speakerId)));
                /* 第 9 个参数把消息对象本身传下去：渲染「版本切换器」时要读 variants，
                   靠 id 反查在「历史里存在重复 id」时会拿到前面那条同 id 的旧消息
                   （老数据里 messageSeq 与聊天记录是分开存的，恢复备份/清过缓存就很容易撞），
                   结果就是「明明有多个版本，切回来却看不到 ‹ 2/3 ›」。 */
                bulkRendering += 1;
                try {
                    appendMessageToDOM(msg.role, msg.content, msg.type, avatarSrc, nickName, msg.isProactive, msg.id || msg.timestamp, msg, msg);
                } finally {
                    bulkRendering -= 1;
                }
            } catch (err) {
                console.warn('[渲染] 单条消息渲染失败，已降级显示:', err);
                try {
                    const fallbackFriend = friendsData[friendId] || friend || {};
                    const fallbackText = '[该消息无法按原样显示]\n' + String(msg && msg.content != null ? msg.content : '').slice(0, 500);
                    appendMessageToDOM(msg && msg.role === 'mine' ? 'mine' : 'other', fallbackText, 'text', fallbackFriend.avatar || '', '—', false, (msg && (msg.id || msg.timestamp)) || Date.now(), { __noUnread: true });
                } catch (e2) { /* 连降级都失败：放弃这一条，也不让列表中断 */ }
            }
        }

        /* 跨标签页同步：论坛是独立页面，「分享到主站聊天」写的是同一份
           localStorage，但本页内存里的 threadManager 不会自己更新 ——
           用户切回来看到的还是旧记录，分享卡片一张都不在，就像根本没发出去。
           这里接住 storage 事件（只有别的标签页写入才会触发），把新增消息补进内存；
           正在看的会话顺手画出来，分享卡片再让角色回一句。 */
        window.addEventListener('storage', event => {
            if (event.key !== 'threadManager_v2' || !event.newValue) return;
            let incoming = null;
            try { incoming = JSON.parse(event.newValue); } catch (e) { return; }
            if (!incoming || typeof incoming !== 'object') return;
            let pendingShare = null;
            let touched = false;
            Object.keys(incoming).forEach(fid => {
                const mem = threadManager[fid];
                const disk = incoming[fid];
                if (!mem || !disk || !Array.isArray(disk.threads)) return;
                const memThread = (mem.threads || []).find(t => t.id === mem.currentThreadId);
                const diskThread = disk.threads.find(t => t.id === mem.currentThreadId);
                if (!memThread || !diskThread || !Array.isArray(diskThread.messages)) return;
                const known = new Set((memThread.messages || []).map(m => String(m.id || m.timestamp)));
                const added = diskThread.messages.filter(m => m && !known.has(String(m.id || m.timestamp)));
                if (!added.length) return;
                added.forEach(m => memThread.messages.push(m));
                touched = true;
                if (fid !== currentFriendId) return;
                added.forEach(m => {
                    try { appendMessageNodeSafely(m, friendsData[fid], fid); } catch (e) { /* 单条失败不影响其余 */ }
                });
                try { scrollToBottom(); } catch (e) { /* 不在聊天页时不用滚 */ }
                const shareMsg = added.filter(m => m.forumShare).pop();
                if (shareMsg) pendingShare = { fid, threadId: memThread.id, share: shareMsg.forumShare };
            });
            /* 补进内存还不够：论坛页写的是 localStorage 镜像，启动时却以 IndexedDB 为准。
               这里把合并后的完整记录立刻落盘，重开页面卡片才不会消失。 */
            if (touched) { try { saveThreadManager(); } catch (e) { /* 存不下就先保证界面正确 */ } }
            // 分享过来总要有人接话。没配 API 就老老实实只放卡片，别往对话里塞报错。
            if (pendingShare) {
                // 同一个人开了两个主站标签页时，两边会同时收到 storage 事件；
                // 按帖子 id 记一个短命标记，避免同一篇帖子被回两遍（不挡下一篇）。
                try {
                    const claimKey = 'myswForumShareClaim';
                    let claims = {};
                    try { claims = JSON.parse(localStorage.getItem(claimKey) || '{}') || {}; } catch (e) { claims = {}; }
                    const sid = String(pendingShare.share.postId || '');
                    const now = Date.now();
                    Object.keys(claims).forEach(k => { if (now - Number(claims[k] || 0) > 30000) delete claims[k]; });
                    if (sid && claims[sid]) return;
                    if (sid) claims[sid] = now;
                    localStorage.setItem(claimKey, JSON.stringify(claims));
                } catch (e) { /* 存储不可用时不做去重，最多多回一条 */ }
                let api = {};
                try { api = JSON.parse(localStorage.getItem('aiChatSettings') || '{}') || {}; } catch (e) { api = {}; }
                if (api.apiUrl && api.apiKey) {
                    try {
                        enqueueAIResponse(
                            `（我刚在论坛看到一篇帖子，分享给你了：《${pendingShare.share.title}》。说说你的看法。）`,
                            { friendId: pendingShare.fid, threadId: pendingShare.threadId }
                        );
                    } catch (e) { /* 队列不可用时静默，卡片已经在聊天里了 */ }
                }
            }
        });

        /* 开场白池：welcomeMessage + 角色卡里的 alternate_greetings。
           导入的酒馆卡常带好几条开场白，以前只能永远显示第一条，很浪费。 */
        function greetingPool(friend) {
            const pool = [];
            if (String(friend?.welcomeMessage || '').trim()) pool.push(String(friend.welcomeMessage));
            // 关掉「多开场白随机」就只用主开场白（备用开场白仍存在角色数据里）
            const alts = (featureOn('altGreetings') && Array.isArray(friend?.tavernAlternateGreetings))
                ? friend.tavernAlternateGreetings : [];
            alts.forEach(g => { if (String(g || '').trim()) pool.push(String(g)); });
            return pool.length ? pool : [`你好，我是${friend?.name || '角色'}。很高兴认识你！`];
        }
        function pickGreeting(friend, friendId, reroll) {
            const pool = greetingPool(friend);
            const fd = threadManager[friendId];
            const thread = fd && Array.isArray(fd.threads) ? fd.threads.find(t => t.id === fd.currentThreadId) : null;
            if (!reroll && thread && Number.isInteger(thread.welcomeIndex) && pool[thread.welcomeIndex] != null) {
                return { text: pool[thread.welcomeIndex], count: pool.length, index: thread.welcomeIndex };
            }
            let idx = Math.floor(Math.random() * pool.length);
            if (reroll && thread && Number.isInteger(thread.welcomeIndex) && pool.length > 1 && idx === thread.welcomeIndex) {
                idx = (idx + 1) % pool.length;   // 重掷时避免又抽到同一条，看起来像没反应
            }
            if (thread) { thread.welcomeIndex = idx; try { saveThreadManager(); } catch (e) { } }
            return { text: pool[idx], count: pool.length, index: idx };
        }

        function renderMessagesSimple(messages, friend, friendId) {
            chatMessages.innerHTML = '';
            chatMessages.style.paddingTop = '';
            chatMessages.style.paddingBottom = '';
            // 退出虚拟滚动：去掉标记，让「性能补丁」的 content-visibility
            // 重新接管（全量渲染时它确实能省掉大量离屏布局）。
            chatMessages.classList.remove('vs-active');
            try { chatMessages.style.overflowAnchor = ''; } catch (e) { }
            virtualScrollState.startIndex = 0;
            virtualScrollState.endIndex = 0;
            virtualScrollState.lastStartOffset = 0;

            if (messages.length === 0) {
                const picked = pickGreeting(friend, friendId, false);
                appendMessageToDOM('other', picked.text, 'text', friend.avatar, getFriendDisplayName(friendId));
                if (picked.count > 1) {
                    // 有多条开场白时给个重掷按钮：每条新对话随机抽一条，看着不顺眼可以换
                    const bar = document.createElement('div');
                    bar.className = 'greeting-reroll-bar';
                    bar.style.cssText = 'display:flex;align-items:center;gap:8px;padding:2px 0 8px 52px;font-size:.78rem;color:#8b90a0;';
                    bar.innerHTML = `<button type="button" style="border:1px solid rgba(255,255,255,.14);background:transparent;color:#a9afbd;border-radius:20px;padding:3px 10px;font-size:.75rem;cursor:pointer">↻ 换个开场白</button>
                        <span>共 ${picked.count} 条开场白 · 第 ${picked.index + 1} 条</span>`;
                    bar.querySelector('button').onclick = (ev) => {
                        ev.stopPropagation();
                        pickGreeting(friend, friendId, true);
                        renderMessages(friendId, { preserveScroll: true });
                    };
                    chatMessages.appendChild(bar);
                }
                return;
            }

            messages.forEach(msg => {
                appendMessageNodeSafely(msg, friend, friendId);
            });
        }

        // 虚拟滚动渲染（消息多的时候用；开启「聊天设置 → 虚拟滚动」后生效）
                /**
         * 虚拟滚动：只把视口附近的十几条消息放进 DOM，其余用两段占位符撑高。
         * 1. **定位只认锚点，不认全局坐标。**
         * 视口里第一条可见消息就是锚点。渲染前记下它相对容器顶部的像素位置，
         * 渲染后读它的真实位置把偏差补回去 —— 估算再离谱，画面也不跳。
         * 2. **占位符高度只增不减地维护，绝不按全局估算重算。**
         * 上方占位符是「已经滚过去的部分」。它一旦被重算（比如估算基准
         * 从 96px 学到 600px），前面几千条的高度和整个变形，视口瞬间错位。
         * 3. **重建 DOM 期间把容器高度锁住。**
         * 否则 innerHTML='' 的瞬间内容高度归零，浏览器把 scrollTop 一把
         * clamp 成 0，还顺带派发一个 scroll 事件，窗口被迫重建 —— 越滚越乱。
         * 4. **窗口内必须关掉 content-visibility。**
         * 「性能补丁」给 .message 加了 content-visibility:auto，和虚拟滚动
         * 是同一件事的两种做法：叠加使用时，窗口内那十几条会被判成「离屏」
         */

        /**
         * 采集「滚动锚点」：视口里第一条可见消息，以及它顶部相对容器顶部的偏移。
         */
        function vsCaptureAnchor(messages) {
            const nodes = chatMessages.querySelectorAll(':scope > .message');
            if (!nodes.length) return null;
            const cr = chatMessages.getBoundingClientRect();
            const idToIndex = new Map();
            for (let i = 0; i < messages.length; i++) {
                const id = messages[i] && messages[i].id;
                if (id !== undefined && id !== null && id !== '') idToIndex.set(String(id), i);
            }
            for (let j = 0; j < nodes.length; j++) {
                const r = nodes[j].getBoundingClientRect();
                if (r.bottom <= cr.top + 1 || r.top >= cr.bottom - 1) continue;
                const mid = nodes[j].dataset ? nodes[j].dataset.messageId : null;
                if (mid == null) continue;
                const idx = idToIndex.get(String(mid));
                if (idx === undefined) continue;
                return { index: idx, id: String(mid), viewportTop: Math.round(r.top - cr.top) };
            }
            return null;
        }

        function vsNodeById(id) {
            const nodes = chatMessages.querySelectorAll(':scope > .message');
            for (let i = 0; i < nodes.length; i++) {
                if (nodes[i].dataset && String(nodes[i].dataset.messageId) === String(id)) return nodes[i];
            }
            return null;
        }

        /** 程序化设置 scrollTop：同步状态，并开一个很短的抑制窗，避免被当成用户滚动 */
        function vsSetScrollTop(value) {
            const v = Math.max(0, Math.round(value));
            chatMessages.scrollTop = v;
            virtualScrollState.scrollTop = chatMessages.scrollTop;
            virtualScrollState.expectedScrollTop = chatMessages.scrollTop;
            virtualScrollState.suppressUntil = ((window.performance && performance.now) ? performance.now() : Date.now()) + 200;
        }

        /**
         * 以某条消息为准开窗口：上方留 600px、下方留一屏 + 600px 的缓冲。
         * 缓冲按**像素**而不是条数算 —— 一条长回复可能就占满整屏，按条数留
         * 缓冲会在长消息会话里频繁露白。
         */
        function vsWindowAround(messages, index) {
            const n = messages.length;
            if (!n) return { startIndex: 0, endIndex: 0 };
            const ch = virtualScrollState.containerHeight || 600;
            const upNeed = 600, downNeed = ch + 600;
            let si = Math.max(0, Math.min(index, n - 1));
            let up = 0, upCnt = 0;
            while (si > 0 && (up < upNeed || upCnt < 3)) { si--; up += vsHeightOfMsg(messages[si], si); upCnt++; }
            let ei = Math.max(0, Math.min(index, n - 1)), used = up, downCnt = 0;
            // 条数保底：一条长回复可能顶两屏，只按像素算缓冲会让窗口只剩两三条，
            // 轻微滚动就露白、还得反复重建 DOM。
            while (ei < n && (used < downNeed || downCnt < 10)) { used += vsHeightOfMsg(messages[ei], ei); ei++; downCnt++; }
            if (ei <= si) ei = Math.min(n, si + 1);
            return { startIndex: si, endIndex: ei };
        }

        /** 没有锚点时（首次进入/恢复位置）：按 scrollTop 估算大致落在第几条 */
        function calculateVisibleRange(messages) {
            const n = messages.length;
            const ch = virtualScrollState.containerHeight || 600;
            const scrollTop = Math.max(0, virtualScrollState.scrollTop || 0);
            let acc = 0, i = 0;
            while (i < n - 1 && acc + vsHeightOfMsg(messages[i], i) < scrollTop) {
                acc += vsHeightOfMsg(messages[i], i);
                i++;
            }
            const w = vsWindowAround(messages, i);
            return w;
        }

        // 虚拟滚动渲染（消息多的时候用；开启「聊天设置 → 虚拟滚动」后生效）
        function renderMessagesVirtual(messages, friend, friendId) {
            // 禁用浏览器滚动锚定：重建窗口内容时 Chrome 会自作主张调整 scrollTop
            // 去「锚定」某个节点，把位置拉走又触发 scroll → 重绘 → 再锚定的死循环。
            try { chatMessages.style.overflowAnchor = 'none'; } catch (e) { }
            chatMessages.classList.add('vs-active');
            vsResetHeights(friendId);

            const n = messages.length;
            virtualScrollState.containerHeight = Math.min(chatMessages.clientHeight || 0, 4000) || 600;
            const wasAtBottom = isChatNearBottom(140);
            virtualScrollState.wasAtBottom = wasAtBottom;
            const prevScrollHeight = chatMessages.scrollHeight;
            dbgLog('[VS] enter', 'st', Math.round(chatMessages.scrollTop), 'sh', prevScrollHeight, 'bottom', wasAtBottom);

            // 锚点必须在清空 DOM 之前采集 —— 旧窗口里的节点马上就要被删掉
            const anchor = wasAtBottom ? null : vsCaptureAnchor(messages);
            const estBefore = virtualScrollState.estAvg;

            let startIndex, endIndex;
            if (wasAtBottom) {
                // 贴底：从末尾往前反推，最后一条一定在窗口里。
                // 除了一屏 + 900px 缓冲，再保底 8 条 —— 长回复会话里一条就顶两屏，
                // 只按像素算会让窗口只剩两三条，往上一滚就得重建。
                const need = virtualScrollState.containerHeight + 900;
                let used = 0, i = n, cnt = 0;
                while (i > 0 && (used < need || cnt < 8)) { i--; used += vsHeightOfMsg(messages[i], i); cnt++; }
                startIndex = i; endIndex = n;
            } else if (anchor) {
                const w = vsWindowAround(messages, anchor.index);
                startIndex = w.startIndex; endIndex = w.endIndex;
            } else {
                const w = calculateVisibleRange(messages);
                startIndex = w.startIndex; endIndex = w.endIndex;
            }
            if (endIndex <= startIndex) endIndex = Math.min(n, startIndex + 1);

            const startOffset = vsOffsetOf(messages, startIndex);
            const totalHeight = vsOffsetOf(messages, n);
            let sliceHeight = 0;
            for (let i = startIndex; i < endIndex; i++) sliceHeight += vsHeightOfMsg(messages[i], i);
            dbgLog('[VS] win', startIndex, endIndex, 'off', Math.round(startOffset), 'total', Math.round(totalHeight), 'slice', Math.round(sliceHeight));

            /* 重建期间锁住容器高度（见本段开头的设计要点 3），用 try/finally 保证还原：
               一旦忘了还原，容器永远停在旧高度，下方会出现一大片能滚过去、
               但什么都没有的空白。 */
            const lockHeight = prevScrollHeight > 0 ? prevScrollHeight + 'px' : '';
            try {
                if (lockHeight) chatMessages.style.height = lockHeight;
                chatMessages.innerHTML = '';
                const spacerTop = document.createElement('div');
                spacerTop.className = 'vs-spacer';
                spacerTop.style.height = `${Math.max(0, startOffset)}px`;
                spacerTop.style.flexShrink = '0';
                chatMessages.appendChild(spacerTop);

                messages.slice(startIndex, endIndex).forEach(msg => {
                    appendMessageNodeSafely(msg, friend, friendId);
                });

                const spacerBottom = document.createElement('div');
                spacerBottom.className = 'vs-spacer';
                // 贴底窗口一直渲到最后一条，下方不应再留占位（留了就能滚进空白里）
                const bottomH = (endIndex >= n) ? 0 : Math.max(0, totalHeight - startOffset - sliceHeight);
                spacerBottom.style.height = `${bottomH}px`;
                spacerBottom.style.flexShrink = '0';
                chatMessages.appendChild(spacerBottom);
            } finally {
                if (lockHeight) { try { chatMessages.style.height = ''; } catch (e) { } }
            }

            virtualScrollState.startIndex = startIndex;
            virtualScrollState.endIndex = endIndex;
            virtualScrollState.startOffset = startOffset;
            virtualScrollState.lastStartOffset = startOffset;

            // ---- 落位：把画面放回用户原来看到的位置 ----
            if (wasAtBottom) {
                // 窗口已经渲到最后一条、下方占位也归零了，这时 scrollHeight 就是真底部
                vsSetScrollTop(chatMessages.scrollHeight);
            } else if (anchor) {
                const node = vsNodeById(anchor.id);
                if (node) {
                    const cr = chatMessages.getBoundingClientRect();
                    const delta = (node.getBoundingClientRect().top - cr.top) - anchor.viewportTop;
                    if (Math.abs(delta) > 0.5) vsSetScrollTop(chatMessages.scrollTop + delta);
                } else {
                    vsSetScrollTop(startOffset);
                }
            } else {
                vsSetScrollTop(startOffset);
            }

            // 渲染完成后实测真实高度：估算换成实测会让窗口内内容轻微挤压，再校一次
            requestAnimationFrame(() => {
                vsMeasureAndReconcile(messages, startIndex, endIndex, anchor, estBefore);
            });
        }

        /** 实测窗口内消息高度并修正占位符（虚拟滚动「不糊弄」的关键） */
        function vsMeasureAndReconcile(messages, startIndex, endIndex, anchor, estBefore) {
            // 窗口在这帧里又被换掉了：本次测量已过期，下一轮会重新量
            if (virtualScrollState.startIndex !== startIndex || virtualScrollState.endIndex !== endIndex) return;
            const nodes = chatMessages.querySelectorAll(':scope > .message');
            if (!nodes.length) return;

            /* 兜底自愈：窗口内节点总高为 0 = 它们被 content-visibility 跳过了渲染
               （样式没命中 .vs-active 时会发生）。内联关掉再量一次，绝不留白屏。 */
            let totalNodeHeight = 0;
            for (let i = 0; i < nodes.length; i++) totalNodeHeight += nodes[i].offsetHeight;
            if (totalNodeHeight <= 0) {
                dbgLog('[VS] 窗口高度全为 0，强制关闭 content-visibility');
                for (let i = 0; i < nodes.length; i++) vsForceMeasureable(nodes[i]);
            }

            // 节点与 messages 的下标不一定严格对应（日期分隔、系统提示也会插进来），
            // 优先按 messageId 反查真实下标，查不到才退回顺序。
            const indexById = new Map();
            for (let i = startIndex; i < endIndex; i++) {
                const id = messages[i] && messages[i].id;
                if (id !== undefined && id !== null && id !== '') indexById.set(String(id), i);
            }
            const cnt = Math.min(nodes.length, endIndex - startIndex);
            for (let j = 0; j < cnt; j++) {
                const node = nodes[j];
                const mid = node.dataset ? node.dataset.messageId : null;
                const idx = (mid != null && indexById.has(String(mid))) ? indexById.get(String(mid)) : (startIndex + j);
                vsRememberHeight(messages[idx], idx, node.offsetHeight);
            }

            // 只改下方占位符。上方占位符在这个渲染周期里是固定的，改了就会错位。
            const totalHeight = vsOffsetOf(messages, messages.length);
            let sliceHeight = 0;
            for (let i = startIndex; i < endIndex; i++) sliceHeight += vsHeightOfMsg(messages[i], i);
            const spacers = chatMessages.querySelectorAll(':scope > .vs-spacer');
            if (spacers.length >= 2) {
                spacers[1].style.height = `${Math.max(0, totalHeight - virtualScrollState.startOffset - sliceHeight)}px`;
            }

            if (virtualScrollState.wasAtBottom) {
                // 渲染时设的 scrollTop 是在新节点还没布局时按偏小的高度算的，
                // 会被浏览器 clamp；实测完成后必须再贴一次，否则会「悬」在半空 →
                // 判定离开底部 → 换窗口重绘 → 无限 ping-pong。
                const bottomSpacer = spacers.length >= 2 ? spacers[1] : null;
                if (bottomSpacer) bottomSpacer.style.height = '0px';
                vsSetScrollTop(chatMessages.scrollHeight);
                virtualScrollState.suppressUntil = ((window.performance && performance.now) ? performance.now() : Date.now()) + 350;
                /* 首屏第一次量到消息时，估算基准会从 96px 变成真实均值。
                   此刻视口还贴在底部（位置由底部决定，与估算无关），正是重新排版的
                   最佳时机：把占位符按新基准重算一遍，滚动条长度立刻变准。
                   只做一次，之后基准冻结，不会再有任何跳动。 */
                if (!virtualScrollState.estRelayouted && estBefore !== virtualScrollState.estAvg) {
                    virtualScrollState.estRelayouted = true;
                    const fid = typeof currentFriendId !== 'undefined' ? currentFriendId : null;
                    if (fid != null) {
                        renderMessagesVirtual(messages, friendsData[fid], fid);
                        return;
                    }
                }
                return;
            }

            // 实测换掉估算后，锚点可能又偏了几个像素 —— 钉回去，画面就完全静止了
            const node = anchor ? vsNodeById(anchor.id) : null;
            const cr = chatMessages.getBoundingClientRect();
            if (node) {
                const delta = (node.getBoundingClientRect().top - cr.top) - anchor.viewportTop;
                if (Math.abs(delta) > 0.5) vsSetScrollTop(chatMessages.scrollTop + delta);
                return;
            }
            // 没有锚点时的最后一道保险：视口里必须真有消息，不能只剩占位符
            const first = nodes[0].getBoundingClientRect();
            if (first.bottom < cr.top || first.top > cr.bottom) {
                dbgLog('[VS] 视口无内容，拉回首条');
                vsSetScrollTop(chatMessages.scrollTop + (first.top - cr.top));
            }
        }

        // 滚动事件处理 - 更新虚拟滚动窗口
        function handleScrollForVirtual() {
            if (!isVirtualScrollEnabled()) return;
            if (window.__theaterMode === true || window.__theaterLocked === true) return;
            const now = (window.performance && performance.now) ? performance.now() : Date.now();
            if (now < virtualScrollState.suppressUntil) {
                /* 抑制窗内要分清两种 scroll 事件：
                   · 我们自己改 scrollTop 触发的（值与 expected 一致）→ 只同步状态；
                   · 用户在这 200ms 里真滚了（值已经偏离）→ 立刻解除抑制照常处理，
                     否则连续滚轮会被一段一段吞掉，手感发黏。 */
                if (virtualScrollState.expectedScrollTop >= 0 &&
                    Math.abs(chatMessages.scrollTop - virtualScrollState.expectedScrollTop) > 4) {
                    virtualScrollState.suppressUntil = 0;
                } else {
                    virtualScrollState.scrollTop = chatMessages.scrollTop;
                    return;
                }
            }
            /* 口径必须和渲染一致：渲染走的是 getDisplayLimitedMessages()
               （「显示限制」截取过的尾部），这里若用 getMessages() 全量，
               同一份 scrollTop 会在两套长度不同的数组里定位到不同消息。 */
            const messages = getDisplayLimitedMessages();
            if (!messages.length || messages.length < VIRTUAL_SCROLL_CONFIG.minMessagesForVirtual) return;

            virtualScrollState.scrollTop = chatMessages.scrollTop;

            /* 判断要不要重建窗口，直接看「DOM 里现有的消息还够不够盖住视口」——
               比拿 scrollTop 和估算坐标比大小可靠得多：不管估算准不准，
               只要视口还在已渲染内容的缓冲区内，就什么都不用做。 */
            const nodes = chatMessages.querySelectorAll(':scope > .message');
            if (!nodes.length) {
                renderMessagesVirtual(messages, friendsData[currentFriendId], currentFriendId);
                return;
            }
            const cr = chatMessages.getBoundingClientRect();
            const first = nodes[0].getBoundingClientRect();
            const last = nodes[nodes.length - 1].getBoundingClientRect();
            const margin = 240;
            const needMoreUp = first.top - cr.top > -margin;
            const needMoreDown = last.bottom < cr.bottom + margin;
            // 贴底（用户主动滚到最新）也交给渲染函数按「末尾窗口」重建
            const nearBottom = isChatNearBottom(140);
            if (nearBottom && !virtualScrollState.wasAtBottom) {
                renderMessagesVirtual(messages, friendsData[currentFriendId], currentFriendId);
                return;
            }
            if (!needMoreUp && !needMoreDown) return;
            renderMessagesVirtual(messages, friendsData[currentFriendId], currentFriendId);
        }

        window.getMessages = getMessages;
        window.getDisplayLimitedMessages = getDisplayLimitedMessages;
        window.renderMessages = renderMessages;
        window.getCurrentThread = getCurrentThread;
        // 上下文压缩器（默认插件）需要读写线程与重绘，这里显式导出这几个入口，
        // 而不是让它去猜全局变量的名字（脚本作用域里的 const 挂不到 window 上）。
        window.saveThreadManager = saveThreadManager;
        window.getNextMessageId = getNextMessageId;
        // 【严重 BUG 修复】这里以前写的是：
        //   window.renderContextEditList = function () { try { renderContextEditList(); } catch (e) {} };
        // main.js 是顶层经典脚本，`function renderContextEditList()` 声明本身就已经是
        // window 上的全局属性。上面这句赋值把该全局绑定**覆盖**掉，于是新函数体里的
        // renderContextEditList() 又解析回它自己 → 无限自递归 → RangeError（栈溢出），
        // 再被 catch (e) {} 一声不响地吞掉。
        // 后果就是用户报的那条：「编辑当前对话上下文」里即使已经和 AI 聊过，
        // 也永远停在「暂无消息」，点「刷新上下文列表」同样没反应 —— 因为刷新按钮
        // 绑的正是这个被覆盖后的函数。
        // 顶层函数声明已自动挂到 window，不需要再包一层；真需要兜底也绝不能吞掉错误。
        if (typeof window.renderContextEditList !== 'function') {
            window.renderContextEditList = renderContextEditList;
        }
        window.getThreadList = function(friendId = currentFriendId) {
            return threadManager[friendId]?.threads || [];
        };
        Object.defineProperty(window, 'currentFriendId', { get: () => currentFriendId, configurable: true });

        // ==========================================================
        // 语音通话实验室（voice-lab.js）用的桥接口
        // ----------------------------------------------------------
        // main.js 是脚本作用域：friendsData / threadManager / addMessageToThread
        // 这些词法绑定外部脚本拿不到（const / let 不挂到 window 上）。
        // 语音通话需要「当前角色是谁、人设是什么、把通话内容写回聊天」，
        // 与其让 voice-lab.js 去猜全局名字，不如在这里开一个小而稳的窗口。
        // 只做转发，不改变任何既有行为。
        // ==========================================================
        window.VoiceLabBridge = {
            /** 当前角色：id / 显示名 / 头像 / 人设提示词 */
            getFriend() {
                const friend = friendsData[currentFriendId];
                if (!friend) return null;
                return {
                    id: currentFriendId,
                    name: getFriendDisplayName(currentFriendId),
                    avatar: friend.avatar || '',
                    systemPrompt: friend.systemPrompt || ''
                };
            },
            getPersonaName() { return myUserName; },
            /** 只取最近若干条纯文本消息，供通话起步时带入上下文 */
            recentMessages(count) {
                const thread = getCurrentThread();
                const list = (thread && Array.isArray(thread.messages)) ? thread.messages : [];
                return list.slice(-Math.max(1, parseInt(count, 10) || 8))
                    .filter(m => m && m.type === 'text' && typeof m.content === 'string' && m.content.trim())
                    .map(m => ({ role: m.role, content: m.content }));
            },
            /** 把通话里的一轮写回当前对话（用户在翻别的对话时不重绘，避免抢屏） */
            appendMessage(role, content, type = 'text') {
                try {
                    const saved = addMessageToThread(role, content, type, false, {});
                    const stillHere = () => threadManager[currentFriendId]?.currentThreadId === getCurrentThread()?.id;
                    if (saved && stillHere()) {
                        const isMine = role === 'mine';
                        const avatarSrc = isMine
                            ? (typeof inputAvatar !== 'undefined' && inputAvatar ? inputAvatar.src : '')
                            : (friendsData[currentFriendId]?.avatar || '');
                        appendMessageToDOM(role, content, type, avatarSrc,
                            isMine ? myUserName : getFriendDisplayName(currentFriendId),
                            false, saved.id, {});
                        scrollToBottom();
                    }
                    return saved || null;
                } catch (e) {
                    console.warn('[语音通话] 写入聊天记录失败：', e);
                    return null;
                }
            },
            toast(message, icon) {
                try { showToast(message, icon || 'ri-phone-line'); }
                catch (e) { dbgLog('[语音通话]', message); }
            },
            /** 群聊里「当前角色」不唯一，语音通话只支持单聊，这里把判定暴露出去 */
            inGroupChat() { return Boolean(isGroupChat()); }
        };


        /* 插件受控通道（ctx.chat.append）要用到它：顶层 function 声明虽然挂在
           window 上，但打包/降级情况下名字可能变，这里显式固定一个入口。 */
        window.addMessageToThread = addMessageToThread;

        // ========== 性能优化：增量更新头像和用户名，避免全量重绘 ==========
        function updateRenderedMessagesAppearance(changedFriendId) {
            // 只更新已渲染消息中的头像和用户名，不重新渲染整个聊天记录。
            // 【修复】旧实现查的是 `.msg` 与 `.name span`，而消息节点实际用的是
            // `.message` / `.nickname` —— 选择器永远匹配不到，等于这个方法什么都没干。
            // 结果就是：改了头像/昵称后，聊天区里已经渲染出来的消息仍显示旧图，
            // 只有刷新页面才恢复（这正是「改了头像要刷新才生效」的一半原因，
            // 另一半是 friendsData 浅拷贝污染了出厂默认头像）。
            const nodes = chatMessages.querySelectorAll('.message');
            const friend = friendsData[currentFriendId];
            nodes.forEach(node => {
                const img = node.querySelector('img.avatar');
                const nameSpan = node.querySelector('.nickname');
                if (node.classList.contains('mine')) {
                    if (img) img.src = inputAvatar.src;
                    if (nameSpan) nameSpan.textContent = myUserName;
                    return;
                }
                const speakerId = img?.dataset?.speakerId || '';
                // 只动「被改动的那个人」的头像；群聊里其他说话人的头像保持不变
                if (changedFriendId && speakerId && speakerId !== changedFriendId) return;
                if (!changedFriendId && speakerId && speakerId !== currentFriendId) return;
                const speaker = friendsData[changedFriendId || speakerId || currentFriendId];
                if (img && speaker?.avatar) img.src = speaker.avatar;
                if (nameSpan && (changedFriendId || speakerId || currentFriendId)) {
                    nameSpan.textContent = getFriendDisplayName(changedFriendId || speakerId || currentFriendId);
                } else if (nameSpan && friend) {
                    nameSpan.textContent = getFriendDisplayName(currentFriendId);
                }
            });
        }

        function applyBubbleTextStyle(bubble) {

            bubble.style.color = currentBubbleTextStyle.color;

            bubble.style.fontSize = currentBubbleTextStyle.fontSize + 'px';


            if (currentBubbleTextStyle.enableStroke && currentBubbleTextStyle.strokeWidth > 0) {
                const sw = currentBubbleTextStyle.strokeWidth;
                const sc = currentBubbleTextStyle.strokeColor;
                bubble.style.textShadow = `
                    -${sw}px -${sw}px 0 ${sc},
                    ${sw}px -${sw}px 0 ${sc},
                    -${sw}px ${sw}px 0 ${sc},
                    ${sw}px ${sw}px 0 ${sc},
                    0 -${sw}px 0 ${sc},
                    0 ${sw}px 0 ${sc},
                    -${sw}px 0 0 ${sc},
                    ${sw}px 0 0 ${sc}
                `;
            } else {
                bubble.style.textShadow = 'none';
            }
        }


        function splitMessageByPunctuation(text) {
            if (!text || text.trim().length === 0) return [];

            // Markdown 结构（代码块、列表、表格、引用等）不能按标点拆散，否则会破坏渲染语义。
            const hasMarkdownStructure = /```|^\s{0,3}([-*+]\s+|\d+\.\s+|>\s+)|^\s*\|.+\|\s*$/m.test(text);
            if (hasMarkdownStructure) return [text];

            const MAX_SEGMENT_LENGTH = 220;
            const MIN_SEGMENT_LENGTH = 48;
            const HARD_SPLIT_LENGTH = 320;
            const paragraphs = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
            const result = [];

            for (const paragraph of paragraphs) {
                const sentenceParts = paragraph
                    .split(/(?<=[。！？!?；;])\s*/)
                    .map(part => part.trim())
                    .filter(Boolean);

                const pieces = sentenceParts.length ? sentenceParts : [paragraph];
                let current = '';

                for (const piece of pieces) {
                    if (piece.length > HARD_SPLIT_LENGTH) {
                        if (current) {
                            result.push(current);
                            current = '';
                        }
                        splitLongSegment(piece, MAX_SEGMENT_LENGTH, result);
                        continue;
                    }

                    const next = current ? joinMessageSegments(current, piece) : piece;
                    if (next.length <= MAX_SEGMENT_LENGTH || current.length < MIN_SEGMENT_LENGTH) {
                        current = next;
                    } else {
                        result.push(current);
                        current = piece;
                    }
                }

                if (current) result.push(current);
            }

            return mergeShortSegments(result, MAX_SEGMENT_LENGTH, MIN_SEGMENT_LENGTH);
        }

        function joinMessageSegments(left, right) {
            if (!left) return right;
            if (!right) return left;
            const needsSpace = /[A-Za-z0-9)]$/.test(left) && /^[A-Za-z0-9(]/.test(right);
            return needsSpace ? `${left} ${right}` : left + right;
        }

        function splitLongSegment(text, maxLen, result) {
            let rest = text.trim();
            while (rest.length > maxLen) {
                const windowText = rest.slice(0, maxLen);
                const breakIndex = Math.max(
                    windowText.lastIndexOf('，'),
                    windowText.lastIndexOf(','),
                    windowText.lastIndexOf('、'),
                    windowText.lastIndexOf(' ')
                );
                const cutAt = breakIndex >= Math.floor(maxLen * 0.55) ? breakIndex + 1 : maxLen;
                result.push(rest.slice(0, cutAt).trim());
                rest = rest.slice(cutAt).trim();
            }
            if (rest) result.push(rest);
        }

        function mergeShortSegments(segments, maxLen, minLen) {
            const merged = [];
            for (const segment of segments) {
                const trimmed = segment.trim();
                if (!trimmed) continue;
                const previous = merged[merged.length - 1];
                if (previous && (previous.length < minLen || trimmed.length < minLen) && previous.length + trimmed.length <= maxLen) {
                    merged[merged.length - 1] = joinMessageSegments(previous, trimmed);
                } else {
                    merged.push(trimmed);
                }
            }
            return merged.length ? merged : [segments.join('').trim()].filter(Boolean);
        }


        // 聊天图片在当前页面内预览，避免点击后跳转到浏览器的图片页面。
        let previewScale = 1;
        let previewRotation = 0;
        function openImagePreview(src, alt = '图片') {
            if (!imagePreviewModal || !imagePreviewTarget || !src) return;
            previewScale = 1;
            previewRotation = 0;
            imagePreviewTarget.src = src;
            imagePreviewTarget.alt = alt;
            imagePreviewTarget.style.transform = 'scale(1) rotate(0deg)';
            const download = document.getElementById('image-preview-download');
            if (download) { download.href = src; download.download = `聊天图片-${Date.now()}`; }
            imagePreviewModal.hidden = false;
            document.body.style.overflow = 'hidden';
        }
        function closeImagePreview() {
            if (!imagePreviewModal?.hidden) {
                imagePreviewModal.hidden = true;
                document.body.style.overflow = '';
                imagePreviewTarget.src = '';
            }
        }
        function updateImagePreviewTransform() {
            if (imagePreviewTarget) imagePreviewTarget.style.transform = `scale(${previewScale}) rotate(${previewRotation}deg)`;
        }
        function initImagePreview() {
            if (!imagePreviewModal || !imagePreviewTarget) return;
            // 兜底拦截：旧消息或 Markdown 渲染出的图片可能被 <a target="_blank"> 包住。
            // 以捕获阶段处理，先于链接默认跳转执行，统一在预览器中打开。
            chatMessages?.addEventListener('click', e => {
                const image = e.target instanceof Element ? e.target.closest('img.message-image, .message-content img') : null;
                if (!image) return;
                const src = image.currentSrc || image.getAttribute('src');
                if (!src) return;
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                openImagePreview(src, image.alt || '聊天图片');
            }, true);
            chatMessages?.addEventListener('auxclick', e => {
                const image = e.target instanceof Element ? e.target.closest('img.message-image, .message-content img') : null;
                if (image) e.preventDefault();
            }, true);
            document.getElementById('image-preview-close')?.addEventListener('click', closeImagePreview);
            document.getElementById('image-preview-zoom-in')?.addEventListener('click', () => { previewScale = Math.min(5, +(previewScale + 0.25).toFixed(2)); updateImagePreviewTransform(); });
            document.getElementById('image-preview-zoom-out')?.addEventListener('click', () => { previewScale = Math.max(0.25, +(previewScale - 0.25).toFixed(2)); updateImagePreviewTransform(); });
            document.getElementById('image-preview-rotate')?.addEventListener('click', () => { previewRotation = (previewRotation + 90) % 360; updateImagePreviewTransform(); });
            document.getElementById('image-preview-reset')?.addEventListener('click', () => { previewScale = 1; previewRotation = 0; updateImagePreviewTransform(); });
            imagePreviewModal.addEventListener('click', e => { if (e.target === imagePreviewModal || e.target === imagePreviewStage) closeImagePreview(); });
            document.addEventListener('keydown', e => { if (!imagePreviewModal.hidden && e.key === 'Escape') closeImagePreview(); });
            imagePreviewStage?.addEventListener('wheel', e => {
                if (imagePreviewModal.hidden) return;
                e.preventDefault();
                previewScale = Math.min(5, Math.max(0.25, +(previewScale + (e.deltaY < 0 ? 0.15 : -0.15)).toFixed(2)));
                updateImagePreviewTransform();
            }, { passive: false });
        }

        // 【身份互换插件】开关为 body.identity-swap。群聊说话人是多人,不做对调,原样显示。
        function identitySwapActive() {
            return document.body.classList.contains('identity-swap') && !isGroupChat();
        }
        // 供 plugins.js 的「身份互换」插件读取真实名字,用于拼接系统提示词
        window.IdentitySwapNames = function () {
            if (!identitySwapActive()) return null;
            return { me: myUserName, ai: getFriendDisplayName(currentFriendId) };
        };
        // 插件开关切换后重绘当前聊天,让历史气泡立即颠倒 / 恢复
        window.IdentitySwapRerender = function () {
            try { if (currentFriendId) renderMessages(currentFriendId, { preserveScroll: true }); } catch (e) { /* 重绘失败不影响聊天 */ }
        };

                /**
         * 消息滑动（Swipe）：同一条 AI 回复保留多个版本
         * 数据结构：message.variants = [{ text, at }]，message.variantIndex 指向当前版本；
         * message.content 始终等于 variants[variantIndex].text —— 这样所有老的读取点
         */
        const SWIPE_MAX_VARIANTS = 12;
        let SWIPE_STASH = null;   // 生成中的「这次要合并进哪条消息」
        // 滑动重生成期间强制「一次回复 = 一条消息」：
        // 如果开着消息分段，一条回复会被拆成多条入库，新版本就没法跟旧版本一一对应了。
        let SWIPE_SINGLE_MODE = false;

        function ensureVariants(msg) {
            if (!msg || typeof msg !== 'object') return null;
            if (!Array.isArray(msg.variants) || !msg.variants.length) {
                msg.variants = [{ text: String(msg.content || ''), at: Number(msg.timestamp) || Date.now() }];
                msg.variantIndex = 0;
            }
            if (!Number.isInteger(msg.variantIndex) || msg.variantIndex < 0 || msg.variantIndex >= msg.variants.length) {
                msg.variantIndex = msg.variants.length - 1;
            }
            return msg.variants;
        }
        function variantCount(msg) {
            return Array.isArray(msg?.variants) ? msg.variants.length : 1;
        }
        function currentVariantText(msg) {
            if (!msg) return '';
            if (Array.isArray(msg.variants) && msg.variants[Number(msg.variantIndex)||0]) {
                return String(msg.variants[Number(msg.variantIndex)||0].text || '');
            }
            return String(msg.content || '');
        }
        /* 「重新回答」前的存根：把当前版本列表留好，等新回复写进线程时合并成新版本 */
        /* textOverride：目标消息如果是「分段生成」的一批，第一条里只存了半个句子，
           调用方会把这批文本拼好传进来，覆盖掉那个不完整的首版。 */
        function beginSwipeStash(friendId, threadId, msg, textOverride) {
            ensureVariants(msg);
            const variants = msg.variants.map(v => ({ text: String(v.text || ''), at: Number(v.at) || Date.now() }));
            if (textOverride != null && variants.length === 1) {
                variants[0] = { text: String(textOverride), at: variants[0].at };
            }
            SWIPE_STASH = {
                friendId: String(friendId || ''),
                threadId: String(threadId == null ? '' : threadId),
                variants,
                at: Date.now()
            };
            SWIPE_SINGLE_MODE = true;   // 新版本按「一条消息」生成
        }
        function clearSwipeStash() { SWIPE_STASH = null; SWIPE_SINGLE_MODE = false; }
        /* 新回复写入线程时调用：把这条 AI 消息变成「老版本的下一版」。
           返回 true 表示这次写入被当成新版本消费掉了。 */
        function consumeSwipeStash(friendId, threadId, message) {
            if (!SWIPE_STASH) return false;
            if (Date.now() - SWIPE_STASH.at > 120000) { SWIPE_STASH = null; return false; }   // 存根过期，防止一次失败的生成污染很久以后的回复
            if (SWIPE_STASH.friendId !== String(friendId || '')) return false;
            if (SWIPE_STASH.threadId !== String(threadId == null ? '' : threadId)) return false;
            const stash = SWIPE_STASH;
            SWIPE_STASH = null;
            const variants = stash.variants.slice(-(SWIPE_MAX_VARIANTS - 1));
            // 新版本与上一版完全一样就没必要多存一份（模型偶尔会吐一模一样的句子）
            const lastText = variants.length ? String(variants[variants.length - 1].text || '') : '';
            if (lastText && lastText.trim() === String(message.content || '').trim()) {
                message.variants = variants;
                message.variantIndex = variants.length - 1;
                return true;
            }
            variants.push({ text: String(message.content || ''), at: Number(message.timestamp) || Date.now() });
            message.variants = variants;
            message.variantIndex = variants.length - 1;
            return true;
        }
        function swipeMessage(messageId, dir) {
            const found = findMessageById(messageId);
            if (!found) return;
            const { thread, message } = found;
            const list = ensureVariants(message);
            if (!list || list.length < 2) return;
            const next = (Number(message.variantIndex) || 0) + (dir > 0 ? 1 : -1);
            if (next < 0 || next >= list.length) return;
            message.variantIndex = next;
            message.content = String(list[next].text || '');
            saveThreadManager();
            renderMessages(currentFriendId, { preserveScroll: true });
            try { renderContextBar(); } catch (e) { }
        }
        /* 直接操作消息对象切版本。
           不走「按 id 再查一遍」：历史数据里可能有重复 id，反查会切到别的消息上。 */
        function swipeVariantOf(msg, dir) {
            if (!msg) return;
            const list = ensureVariants(msg);
            if (!list || list.length < 2) return;
            const next = (Number(msg.variantIndex) || 0) + (dir > 0 ? 1 : -1);
            if (next < 0 || next >= list.length) return;
            msg.variantIndex = next;
            msg.content = String(list[next].text || '');
            saveThreadManager();
            try { if (currentFriendId) renderMessages(currentFriendId, { preserveScroll: true }); } catch (e) { }
            try { renderContextBar(); } catch (e) { }
        }

        /* 消息下方那一行「‹ 2/3 ›」：只在有多种版本时出现 */
        function buildSwipeBar(messageId, msg) {
            const total = variantCount(msg);
            if (total < 2) return null;
            const idx = Math.min(total - 1, Math.max(0, Number(msg?.variantIndex) || 0));
            const bar = document.createElement('div');
            bar.className = 'swipe-bar';
            const arrow = (glyph, dir, disabled, title) => {
                const b = document.createElement('button');
                b.type = 'button';
                b.className = 'swipe-arrow';
                b.textContent = glyph;
                b.disabled = !!disabled;
                b.title = title;
                if (!disabled) b.addEventListener('click', (ev) => { ev.stopPropagation(); swipeVariantOf(msg, dir); });
                return b;
            };
            bar.appendChild(arrow('‹', -1, idx <= 0, '上一版'));
            const label = document.createElement('span');
            label.className = 'swipe-count';
            label.textContent = `${idx + 1} / ${total}`;
            label.title = '同一条回复的多个版本，用左右箭头切换（内容会随版本变化，上下文按当前版本计算）';
            bar.appendChild(label);
            bar.appendChild(arrow('›', 1, idx >= total - 1, '下一版'));
            return bar;
        }

        /* ============================================================
           文件消息：气泡里放一张卡片，点开才看内容
           以前发个 txt，是把「[文件：xxx]」加全文一起塞进消息正文 ——
           几百行的文件发出去，气泡能顶穿聊天区，往上翻三屏还在同一个气泡里。
           现在正文照旧存在消息里（发给 AI、导出、搜索都用得到），
           但气泡只渲染一张卡片：图标 + 文件名 + 体积/行数，点开是预览弹窗
           （可复制、可下载）。整条消息的高度从此跟文件大小无关。
 */
        function formatFileSize(bytes) {
            const n = Number(bytes) || 0;
            if (n < 1024) return `${n} B`;
            if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
            return `${(n / 1024 / 1024).toFixed(2)} MB`;
        }

        function fileIconFor(name) {
            const ext = String(name || '').split('.').pop().toLowerCase();
            if (ext === 'md' || ext === 'markdown') return 'ri-markdown-line';
            if (['json', 'yaml', 'yml', 'xml', 'csv', 'tsv'].includes(ext)) return 'ri-file-code-line';
            if (['js', 'ts', 'jsx', 'tsx', 'py', 'html', 'css', 'sh', 'java', 'c', 'cpp', 'go', 'rs', 'sql'].includes(ext)) return 'ri-code-line';
            if (ext === 'log') return 'ri-file-list-3-line';
            return 'ri-file-text-line';
        }

        /** 旧版把「[文件：名] + 全文」塞进一条 text 消息，这里识别出来改按卡片渲染 */
        function parseLegacyFileMessage(text) {
            const m = String(text || '').match(/^\s*\[文件[:：]\s*([^\]\n]{1,200})\]\s*\n+/);
            if (!m) return null;
            return { name: m[1].trim(), body: String(text).slice(m[0].length) };
        }

        function buildFileBubble(text, meta) {
            const body = String(text == null ? '' : text);
            const fileName = String(meta?.fileName || '').trim() || '文本文件';
            const size = Number(meta?.fileSize) || body.length;
            const lines = body ? body.split('\n').length : 0;

            const card = document.createElement('div');
            card.className = 'bubble file-bubble';
            card.tabIndex = 0;
            card.setAttribute('role', 'button');
            card.title = `${fileName} · 点击预览`;

            const icon = document.createElement('div');
            icon.className = 'file-bubble-icon';
            icon.innerHTML = `<i class="${fileIconFor(fileName)}"></i>`;

            const main = document.createElement('div');
            main.className = 'file-bubble-main';
            const nameEl = document.createElement('div');
            nameEl.className = 'file-bubble-name';
            nameEl.textContent = fileName;
            const metaEl = document.createElement('div');
            metaEl.className = 'file-bubble-meta';
            metaEl.textContent = `${formatFileSize(size)}${lines ? ` · ${lines} 行` : ''}`;
            main.append(nameEl, metaEl);

            const action = document.createElement('span');
            action.className = 'file-bubble-action';
            action.innerHTML = '<i class="ri-eye-line"></i>';

            card.append(icon, main, action);
            const open = (e) => {
                e?.preventDefault?.();
                e?.stopPropagation?.();
                openFilePreview(fileName, body, size);
            };
            card.addEventListener('click', open);
            card.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') open(e); });
            return card;
        }

        /* 文件预览弹窗：单例，第一次用到时才插进 body */
        let filePreviewEls = null;
        const FILE_PREVIEW_LIMIT = 400000;   // 超过这个字符数只渲染前一段，其余提示下载看

        function ensureFilePreviewModal() {
            if (filePreviewEls) return filePreviewEls;
            const modal = document.createElement('div');
            modal.className = 'file-preview-modal';
            modal.hidden = true;
            modal.innerHTML = `
                <div class="fp-backdrop" data-fp-close></div>
                <div class="fp-card" role="dialog" aria-modal="true" aria-label="文件预览">
                    <div class="fp-head">
                        <i class="ri-file-text-line fp-head-icon"></i>
                        <div class="fp-title-wrap">
                            <div class="fp-title"></div>
                            <div class="fp-sub"></div>
                        </div>
                        <button type="button" class="fp-btn" data-fp-copy title="复制全文"><i class="ri-file-copy-line"></i><span>复制</span></button>
                        <button type="button" class="fp-btn" data-fp-download title="下载文件"><i class="ri-download-2-line"></i><span>下载</span></button>
                        <button type="button" class="fp-btn fp-close" data-fp-close title="关闭（Esc）"><i class="ri-close-line"></i></button>
                    </div>
                    <pre class="fp-body"></pre>
                    <div class="fp-foot"><i class="ri-lock-line"></i> 文件内容保存在本机聊天记录里，预览不会上传任何东西。</div>
                </div>`;
            document.body.appendChild(modal);

            const titleEl = modal.querySelector('.fp-title');
            const subEl = modal.querySelector('.fp-sub');
            const bodyEl = modal.querySelector('.fp-body');
            const headIcon = modal.querySelector('.fp-head-icon');
            const state = { name: '', text: '' };

            const close = () => {
                modal.hidden = true;
                document.body.style.overflow = '';
                bodyEl.textContent = '';
            };
            const copy = async () => {
                try {
                    if (navigator.clipboard?.writeText) {
                        await navigator.clipboard.writeText(state.text);
                    } else {
                        const ta = document.createElement('textarea');
                        ta.value = state.text;
                        ta.style.cssText = 'position:fixed;left:-9999px;';
                        document.body.appendChild(ta);
                        ta.select();
                        document.execCommand('copy');
                        ta.remove();
                    }
                    showToast('文件内容已复制', 'ri-file-copy-line');
                } catch (e) {
                    showToast('复制失败，请手动选中内容复制', 'ri-error-warning-line');
                }
            };
            const download = () => {
                try {
                    downloadBlob(state.name || '文本文件.txt', state.text, 'text/plain;charset=utf-8');
                    showToast('已下载文件', 'ri-download-2-line');
                } catch (e) {
                    showToast('下载失败：' + e.message, 'ri-error-warning-line');
                }
            };

            modal.addEventListener('click', e => {
                if (e.target.closest('[data-fp-close]')) { close(); return; }
                if (e.target.closest('[data-fp-copy]')) { copy(); return; }
                if (e.target.closest('[data-fp-download]')) { download(); return; }
            });
            document.addEventListener('keydown', e => {
                if (e.key === 'Escape' && !modal.hidden) close();
            });

            filePreviewEls = {
                open(name, text, size) {
                    state.name = name || '文本文件';
                    state.text = String(text == null ? '' : text);
                    titleEl.textContent = state.name;
                    headIcon.className = `${fileIconFor(state.name)} fp-head-icon`;
                    const lines = state.text ? state.text.split('\n').length : 0;
                    subEl.textContent = `${formatFileSize(size || state.text.length)}${lines ? ` · ${lines} 行` : ''}${state.text.length > FILE_PREVIEW_LIMIT ? ' · 内容较长，预览只显示开头' : ''}`;
                    bodyEl.textContent = state.text.length > FILE_PREVIEW_LIMIT
                        ? state.text.slice(0, FILE_PREVIEW_LIMIT) + '\n\n…（预览已截断，点「下载」看完整内容）'
                        : state.text;
                    bodyEl.scrollTop = 0;
                    modal.hidden = false;
                    document.body.style.overflow = 'hidden';
                },
                close
            };
            return filePreviewEls;
        }

        function openFilePreview(name, text, size) {
            ensureFilePreviewModal().open(name, text, size);
        }

        function appendMessageToDOM(role, text, type, avatarSrc, nickName, isProactive = false, messageId = null, meta = {}, messageRef = null) {
            // 身份互换:只改「显示」。role 本身与内容处理(AI 文本解析、重新回答、消息操作)保持原样,
            // displayRole 只决定气泡落在哪一侧、头像与昵称换成谁的。
            const swapOn = identitySwapActive();
            const displayRole = swapOn ? (role === 'mine' ? 'other' : (role === 'other' ? 'mine' : role)) : role;
            if (swapOn && (role === 'mine' || role === 'other')) {
                avatarSrc = role === 'mine' ? (friendsData[currentFriendId]?.avatar || '') : (inputAvatar?.src || '');
                nickName = role === 'mine' ? getFriendDisplayName(currentFriendId) : myUserName;
            }
            const chatSettings = getChatSettings();
            // 角色（AI）新消息到达时，如果用户正停在上面看历史，就点亮「回到最新消息」的小红点。
            // 只在 DOM 追加路径里计数：重绘历史记录不会误加。
            if (role === 'other' && !meta?.isCompressed && !meta?.__noUnread) {
                try { noteNewMessageWhileAway(); } catch (e) {}
            }
            // Code 模式：强制关闭消息分段，否则代码块会被按标点拆成多条气泡，
            // 用户无法整体复制。（配置读取可能在 chat.js 之外，这里再兜一道。）
            let enableSegmentation = chatSettings.enableMessageSegmentation;
            try {
                if (window.CodeMode && window.CodeMode.isEnabled()) enableSegmentation = false;
            } catch (e) { /* Code 模式异常不影响渲染 */ }
            // 仅影响 AI 文本的界面渲染，不改变已保存的原始消息内容。
            if (role === 'other' && type === 'text') {
                text = getDisplayableAiText(text, chatSettings);
            }

            // 如果没有传入 messageId，使用当前时间戳作为默认值
            if (messageId === null) {
                messageId = Date.now();
            }

            // 仅对 AI 消息 + 文本类型做表情包占位符解析；
            // 占位符解析后会把每段以 {type:'text'|'sticker', content|sticker} 形式展开，再走原有的分段逻辑。
            let segments;
            if (type === 'text' && role === 'other' && typeof splitAiOutputWithStickers === 'function') {
                const stickerList = typeof loadMyStickers === 'function' ? loadMyStickers() : [];
                const parsed = splitAiOutputWithStickers(text, stickerList, enableSegmentation);
                // 纯文本且无占位符 → 走旧路径（保留原有 splitMessageByPunctuation 分段）
                if (parsed.length === 1 && parsed[0].type === 'text' && enableSegmentation) {
                    segments = splitMessageByPunctuation(parsed[0].content).map(t => ({ kind: 'text', value: t }));
                } else if (parsed.length === 1 && parsed[0].type === 'text') {
                    segments = [{ kind: 'text', value: parsed[0].content }];
                } else {
                    segments = parsed.map(s => s.type === 'text'
                        ? { kind: 'text', value: s.content }
                        : { kind: 'sticker', sticker: s.sticker });
                }
            } else if (type === 'text' && role === 'other' && enableSegmentation) {
                segments = splitMessageByPunctuation(text).map(t => ({ kind: 'text', value: t }));
            } else {
                // 图片、视频、音频不能伪装成 text 段；否则图片 URL 会被 marked 渲染成外链，
                // 点击自然就跳到了浏览器页面，也不会执行预览器逻辑。
                segments = [{ kind: type === 'image' ? 'image' : 'text', value: text }];
            }

            // 把数据保存到数据层（已经包含占位符的原文本 → 需要把占位符剥离为纯文本）
            // 注意：这里只针对「AI 消息 + 含 sticker 占位符」的场景做去占位符处理。
            // 该步骤由调用方在 addMessageToThread 之前完成；此处不重复操作。

            segments.forEach((segment, index) => {
                const msgDiv = document.createElement('div');
                msgDiv.classList.add('message', displayRole);
                /* 入场动画只给「实时追加」的那几条；批量重绘不播（见 bulkRendering）。
                   动画结束就摘掉 class，避免 content-visibility 反复进出时重播。 */
                if (!bulkRendering) {
                    msgDiv.classList.add('msg-enter');
                    msgDiv.addEventListener('animationend', () => msgDiv.classList.remove('msg-enter'), { once: true });
                    setTimeout(() => msgDiv.classList.remove('msg-enter'), 600);
                }
                // 真实角色(mine / other),与显示侧解耦;身份互换时逻辑判断请用它
                msgDiv.dataset.role = role;
                // 上下文压缩摘要（插件「上下文压缩器」产出）：加标记类，
                // 让它显示成「虚线摘要块」而不是普通系统通知，一眼可辨。
                if (meta && meta.isCompressed) msgDiv.classList.add('is-ctx-summary');
                if (messageId) {
                    // 每个分段都保留同一个原始消息 ID，供回放等按「一条消息」处理的功能可靠分组。
                    msgDiv.dataset.messageId = messageId + (index > 0 ? `-${index}` : '');
                    msgDiv.dataset.messageSourceId = String(messageId);
                }

                const avatarImg = document.createElement('img');
                avatarImg.src = avatarSrc;
                avatarImg.classList.add('avatar');
                // 记录这条消息的头像属于谁：群聊里同一条记录可能有多个说话人，
                // 增量更新头像时必须按说话人匹配，不能一律当成当前角色。
                avatarImg.dataset.speakerId = displayRole === 'mine' ? '__me' : (meta?.friendId || currentFriendId || '');

                if (displayRole === 'other') {
                    // 多段消息（开启分段显示）时每段都会渲染一个头像；
                    // 旧实现只在 index === 0 绑定，导致第二段之后的头像点了没反应。
                    const openAiAvatarMenu = (e) => {
                        e?.stopPropagation?.();
                        currentAiAvatarTarget = meta?.friendId || currentFriendId;
                        syncAiMenuResetVisibility(currentAiAvatarTarget);
                        const rect = avatarImg.getBoundingClientRect();
                        aiAvatarContextMenu.style.left = Math.max(8, rect.left) + 'px';
                        aiAvatarContextMenu.style.top = Math.min(window.innerHeight - 140, rect.bottom + 5) + 'px';
                        toggleFriendContextMenu(false);
                        toggleAiAvatarMenu(true);
                    };
                    avatarImg.addEventListener('click', openAiAvatarMenu);
                    const setGroupTitle = (e) => {
                        if (!isGroupChat() || !meta?.friendId) return;
                        e.preventDefault();
                        e.stopPropagation();
                        // 群头衔统一在「管理群聊」界面设置，避免使用原生 prompt 弹窗。
                        showToast('请在群聊管理界面的「群成员头衔」中设置', 'ri-vip-crown-line');
                        manageCurrentGroupChat();
                    };
                    // 群聊里右键 = 设置头衔（沿用原行为）；普通聊天里右键直接开出头像菜单，
                    // 这样「右键 AI 头像 → 更改头像」在单聊下也能用。
                    avatarImg.addEventListener('contextmenu', (e) => {
                        // 群聊里右键「成员头像」= 设置头衔（沿用原行为）；
                        // 但群容器自己的头像（系统消息 / 群内通报，没有具体发言人）
                        // 右键应当能换群头像 / 解散群聊 —— 与侧边栏右键共用同一个群菜单。
                        if (isGroupChat() && meta?.friendId) { setGroupTitle(e); return; }
                        if (isGroupChat() && !meta?.friendId) {
                            showFriendContextMenu(e, currentFriendId);
                            return;
                        }
                        e.preventDefault();
                        openAiAvatarMenu(e);
                    });
                    let titlePressTimer;
                    const onTitlePress = (e) => {
                        if (isGroupChat() && meta?.friendId) setGroupTitle(e);
                        else openAiAvatarMenu(e);
                    };
                    avatarImg.addEventListener('touchstart', (e) => { titlePressTimer = setTimeout(() => onTitlePress(e), 600); }, { passive: false });
                    avatarImg.addEventListener('touchend', () => clearTimeout(titlePressTimer));
                    avatarImg.addEventListener('touchmove', () => clearTimeout(titlePressTimer));
                }

                if(displayRole === 'mine' && index === 0) avatarImg.addEventListener('click', () => avatarUpload.click());

                const contentDiv = document.createElement('div');
                contentDiv.classList.add('message-content');

                const nickSpan = document.createElement('span');
                nickSpan.classList.add('nickname');
                nickSpan.textContent = nickName;

                let bubble;
                if (segment.kind === 'sticker') {
                    // AI 通过 [sticker:N] 占位符发送的表情包：直接渲染为图片气泡
                    const sticker = segment.sticker || {};
                    bubble = document.createElement('img');
                    bubble.classList.add('bubble', 'message-image', 'sticker-bubble');
                    bubble.src = sticker.url || '';
                    if (sticker.remark) bubble.title = sticker.remark;
                    bubble.addEventListener('click', () => openImagePreview(sticker.url || '', sticker.remark || '表情图片'));
                } else if (type === 'file') {
                    // 文件消息：气泡里只放卡片，完整内容在预览弹窗里
                    bubble = buildFileBubble(segment.value, meta);
                } else if (type === 'text') {
                    const segmentText = segment.value;
                    /* 旧版本发文件时，正文是「[文件：xxx] + 全文」直接拼出来的。
                       这里识别出来也按卡片渲染 —— 不然老聊天记录里那几个超大
                       气泡还是会把聊天区顶穿，用户以为没修好。 */
                    const legacyFile = role === 'mine' ? parseLegacyFileMessage(segmentText) : null;
                    if (legacyFile) {
                        bubble = buildFileBubble(legacyFile.body, { fileName: legacyFile.name });
                    } else {
                    bubble = document.createElement('div');
                    bubble.classList.add('bubble');


                    // 圆角不再写内联样式：交给 CSS 变量 --bubble-radius，
                    // 这样在设置里切换气泡样式时，已渲染的气泡也能立刻跟着变。

                    if (currentBubbleImage) {
                        bubble.classList.add('has-custom-bg');
                        bubble.style.backgroundImage = `url('${currentBubbleImage}')`;
                    }


                    applyBubbleTextStyle(bubble);

                    if (isProactive && index === 0) {
                        bubble.classList.add('proactive');
                        const tag = document.createElement('span');
                        tag.classList.add('proactive-tag');
                        tag.textContent = '💬 主动关怀';
                        bubble.appendChild(tag);
                    }
                    // 使用 DOMPurify 清理 marked 解析后的 HTML，防止 XSS
                    const parsedHtml = marked.parse(segmentText);
                    appendSanitizedHtml(bubble, parsedHtml);
                    }
                } else if (segment.kind === 'image' || type === 'image') {
                    bubble = document.createElement('img');
                    bubble.classList.add('bubble', 'message-image');
                    bubble.src = segment.value;
                    bubble.alt = '图片';
                    bubble.addEventListener('click', e => {
                        e.preventDefault();
                        e.stopPropagation();
                        openImagePreview(segment.value, '聊天图片');
                    });
                } else if (type === 'video') {
                    bubble = document.createElement('video');
                    bubble.classList.add('bubble', 'message-video');
                    bubble.src = segment.value;
                    bubble.controls = true;
                    bubble.style.maxWidth = '100%';
                    bubble.style.borderRadius = '12px';
                } else if (type === 'audio') {
                    bubble = document.createElement('div');
                    bubble.classList.add('bubble', 'audio-bubble');
                    const audio = document.createElement('audio');
                    audio.controls = true;
                    audio.src = segment.value;
                    bubble.appendChild(audio);
                } else {
                    // 【渲染中断兜底】未知/遗留消息类型（旧版本写入的 voice、插件扩展类型、
                    // 导入数据丢失 type 字段等）以前会落到这里导致 bubble 保持 undefined，
                    // 紧接着的 contentDiv.appendChild(bubble) 抛 TypeError ——
                    // renderMessagesSimple 的 forEach 从中断点整段崩掉，
                    // 用户看到的就是「打开网站聊天记录只剩一小截，最新的一堆全没了」。
                    // 现在统一降级为文本气泡显示原始内容，坏数据最多影响它自己那一条。
                    bubble = document.createElement('div');
                    bubble.classList.add('bubble');
                    if (currentBubbleImage) {
                        bubble.classList.add('has-custom-bg');
                        bubble.style.backgroundImage = `url('${currentBubbleImage}')`;
                    }
                    applyBubbleTextStyle(bubble);
                    const fallbackHtml = marked.parse(String(segment.value == null ? '' : segment.value));
                    appendSanitizedHtml(bubble, fallbackHtml);
                }

                // 压缩摘要：气泡换成「虚线摘要块」样式（标签在 nickSpan 之后插入）
                const isCompressedSummary = !!meta?.isCompressed && index === 0;
                if (isCompressedSummary) bubble.classList.add('ctx-summary-bubble');
                contentDiv.appendChild(nickSpan);
                // 推理模型的思考过程：昵称下方、正文气泡上方。
                // 只挂首段（index === 0）：开启「消息分段」后若每段都挂，用户会看到
                // 同一份思考重复好几遍。历史消息同样走这里，所以重开开关也能看到。
                if (role === 'other' && index === 0 && meta?.reasoning && reasoningPanelEnabled(chatSettings)) {
                    const reasoningPanel = buildReasoningBlock(meta.reasoning, meta.reasoningMs);
                    if (reasoningPanel) contentDiv.appendChild(reasoningPanel);
                }
                if (isCompressedSummary) {
                    const tag = document.createElement('div');
                    tag.className = 'ctx-summary-tag';
                    const cnt = Number(meta.compressedCount) || 0;
                    const tk = Number(meta.originalTokens) || 0;
                    tag.innerHTML = `<i class="ri-compress-db-line"></i> 历史摘要${cnt ? ` · 由 ${cnt} 条消息压缩而成` : ''}${tk ? ` · 压缩前约 ${tk} token` : ''}`;
                    contentDiv.appendChild(tag);
                }
                if (meta?.replyTo) {
                    const quote = document.createElement('div');
                    quote.className = 'reply-preview';
                    quote.textContent = `↪ ${meta.replyTo.name || '引用'}：${String(meta.replyTo.content || '').slice(0, 80)}`;
                    contentDiv.appendChild(quote);
                }
                contentDiv.appendChild(bubble);
                const showElapsedMeta = meta?.elapsedMs && getChatSettings().showAiReplyElapsed !== false && role === 'other' && index === 0;
                const showTokenMeta = meta?.tokenUsage && getChatSettings().showMessageTokens === true && role === 'other' && index === 0;
                if (showElapsedMeta || showTokenMeta) {
                    const metaDiv = document.createElement('div');
                    metaDiv.className = 'message-meta';
                    const metaParts = [];
                    if (showTokenMeta) {
                        let cachePart = '';
                        if (meta.tokenUsage.cacheHit) {
                            cachePart = `（缓存命中 ${meta.tokenUsage.cacheHit}`;
                            if (Number.isFinite(meta.tokenUsage.cacheMiss) && (meta.tokenUsage.cacheHit + meta.tokenUsage.cacheMiss) > 0) {
                                cachePart += ` · 命中率 ${((meta.tokenUsage.cacheHit / (meta.tokenUsage.cacheHit + meta.tokenUsage.cacheMiss)) * 100).toFixed(0)}%`;
                            }
                            cachePart += '）';
                        }
                        metaParts.push(`Token ${meta.tokenUsage.input}+${meta.tokenUsage.output}${cachePart}`);
                    }
                    if (showElapsedMeta) metaParts.push(`回复耗时 ${(meta.elapsedMs / 1000).toFixed(1)}s`);
                    metaDiv.textContent = metaParts.join(' · ');
                    contentDiv.appendChild(metaDiv);
                }
                // 分段消息在最后一个气泡上承载操作入口，避免操作按钮挂在首段。
                if (role === 'mine' && index === segments.length - 1) {
                    attachOwnMessageActions(msgDiv, msgDiv.dataset.messageId);
                }
                msgDiv.appendChild(avatarImg);
                msgDiv.appendChild(contentDiv);

                chatMessages.appendChild(msgDiv);


                if (index === segments.length - 1) {
                    const actionsDiv = document.createElement('div');
                    actionsDiv.className = 'message-actions';
                    if (role === 'other' && type === 'text' && showRegenerateBtnCheckbox.checked) {
                        const regenerateBtn = document.createElement('div');
                        regenerateBtn.className = 'regenerate-btn';
                        regenerateBtn.innerHTML = '<i class="ri-refresh-line"></i>';
                        regenerateBtn.title = '重新回答（生成新版本，可用下方的 ‹ › 切回上一版）';
                        regenerateBtn.addEventListener('click', () => {
                            dbgLog('重新回答按钮点击，messageId:', msgDiv.dataset.messageId);
                            regenerateAIResponse(msgDiv.dataset.messageId);
                        });
                        actionsDiv.appendChild(regenerateBtn);
                    }
                    if (getFeatureToggles().showMessageTts && type === 'text') {
                        const ttsBtn = document.createElement('div');
                        ttsBtn.className = 'regenerate-btn';
                        ttsBtn.innerHTML = '<i class="ri-volume-up-line"></i>';
                        ttsBtn.title = '朗读消息';
                        ttsBtn.addEventListener('click', () => speakMessageText(segment.kind === 'text' ? segment.value : ''));
                        actionsDiv.appendChild(ttsBtn);
                    }
                    if (getFeatureToggles().showMessageQuote && type === 'text') {
                        const quoteBtn = document.createElement('div');
                        quoteBtn.className = 'regenerate-btn';
                        quoteBtn.innerHTML = '<i class="ri-double-quotes-l"></i>';
                        quoteBtn.title = '引用回复';
                        quoteBtn.addEventListener('click', () => quoteMessageForReply({ id: msgDiv.dataset.messageId, role, content: segment.kind === 'text' ? segment.value : '[表情包]', name: nickName }));
                        actionsDiv.appendChild(quoteBtn);
                    }
                    if (getFeatureToggles().showBranchButtons) {
                        const branchBtn = document.createElement('div');
                        branchBtn.className = 'regenerate-btn';
                        branchBtn.innerHTML = '<i class="ri-git-branch-line"></i>';
                        branchBtn.title = '从此处开新对话';
                        branchBtn.addEventListener('click', () => createBranchFromMessage(msgDiv.dataset.messageId));
                        actionsDiv.appendChild(branchBtn);
                    }
                    // 同一条回复的多个版本：‹ 2/3 › 切换，挂在按钮行末尾。群聊不做（一条回复可能拆成多条消息）
                    if (role === 'other' && type === 'text' && !isGroupChat(currentFriendId) && featureOn('swipeVariants')) {
                        // messageRef 是 renderMessages 直接传下来的消息对象（首选）；
                        // 流式/临时气泡没有引用时再按 id 回退查找。
                        const foundMsg = messageRef ? { message: messageRef } : findMessageById(messageId);
                        let targetMsg = foundMsg ? foundMsg.message : null;
                        // id 冲突时（历史数据里 messageSeq 被重置过，可能出现两条同 id 的消息）
                        // findMessageById 会拿到前面那条「我」的消息，这里按角色再确认一次。
                        if (targetMsg && targetMsg.role !== role) {
                            const th = getCurrentThread();
                            targetMsg = th ? [...th.messages].reverse()
                                .find(m => String(m.id || m.timestamp) === getMessageIdBase(messageId) && m.role === role) : null;
                        }
                        const bar = targetMsg ? buildSwipeBar(messageId, targetMsg) : null;
                        if (bar) actionsDiv.appendChild(bar);
                    }
                    if (actionsDiv.children.length > 0) contentDiv.appendChild(actionsDiv);
                }
            });
        }


        function getMessageIdBase(messageId) {
            return String(messageId || '').split('-')[0];
        }

        function findMessageById(messageId) {
            const id = getMessageIdBase(messageId);
            const thread = getCurrentThread();
            if (!thread) return null;
            const index = thread.messages.findIndex(msg => String(msg.id || msg.timestamp) === id);
            return index >= 0 ? { thread, index, message: thread.messages[index] } : null;
        }

        function attachOwnMessageActions(msgDiv, messageId) {
            let longPressTimer = null;
            const openActions = (event) => {
                event.preventDefault();
                const found = findMessageById(messageId);
                if (!found || found.message.role !== 'mine') return;
                if (event.shiftKey) {
                    revokeOwnMessage(messageId);
                } else {
                    editOwnMessage(messageId);
                }
            };
            msgDiv.addEventListener('contextmenu', openActions);
            msgDiv.addEventListener('touchstart', () => {
                longPressTimer = setTimeout(() => openActions(new Event('contextmenu')), 650);
            }, { passive: true });
            ['touchend', 'touchmove', 'touchcancel'].forEach(type => {
                msgDiv.addEventListener(type, () => clearTimeout(longPressTimer), { passive: true });
            });
        }

        async function editOwnMessage(messageId) {
            const found = findMessageById(messageId);
            if (!found || found.message.role !== 'mine' || found.message.type !== 'text' || found.message.revoked) {
                showToast('这条消息不能编辑', 'ri-error-warning-line');
                return;
            }
            const nextContent = await Dlg.prompt({
                title: '编辑消息',
                message: '修改后要重新发给 AI 吗？直接确认即视为编辑本条内容：',
                value: found.message.content,
                multiline: true,
                rows: 5,
                okText: '保存'
            });
            if (nextContent === null) return;
            if (!nextContent.trim()) {
                showToast('消息内容不能为空', 'ri-error-warning-line');
                return;
            }
            // await 期间线程可能被切换/重建：重新定位一次再写入
            const again = findMessageById(messageId);
            if (!again) return;
            again.message.content = nextContent.trim();
            again.message.edited = true;
            again.message.editedAt = Date.now();
            saveThreadManager();
            renderMessages(currentFriendId);
            showToast('消息已编辑', 'ri-edit-line');
        }

        async function revokeOwnMessage(messageId) {
            const found = findMessageById(messageId);
            if (!found || found.message.role !== 'mine') return;
            if (!await Dlg.confirm({ title: '撤回消息', message: '确定撤回这条消息吗？', okText: '撤回', danger: true })) return;
            const again = findMessageById(messageId);
            if (!again) return;
            found.message.content = '你撤回了一条消息';
            found.message.type = 'text';
            found.message.revoked = true;
            found.message.revokedAt = Date.now();
            saveThreadManager();
            renderMessages(currentFriendId);
            showToast('消息已撤回', 'ri-arrow-go-back-line');
        }

        function scrollToBottom() {
            chatMessages.scrollTop = chatMessages.scrollHeight;
            scheduleScrollToBottomButtonUpdate();
        }

        function appendSystemMessage(htmlContent) {
            const msgDiv = document.createElement('div');
            msgDiv.classList.add('message');
            msgDiv.style.justifyContent = 'center';
            // 系统通知不参与「未读到底部」判断之外的任何逻辑，保持原样即可

            const bubble = document.createElement('div');
            bubble.classList.add('bubble', 'system-bubble');
            appendSanitizedHtml(bubble, htmlContent);

            msgDiv.appendChild(bubble);
            chatMessages.appendChild(msgDiv);
            scrollToBottom();
        }



        function showToast(message, iconClass = 'ri-information-line') {
            const toastContainer = document.getElementById('toast-container');
            const toastMessage = document.getElementById('toast-message');
            // 容器尚未挂载（如启动早期存储迁移触发提示）时静默跳过，避免报错
            if (!toastContainer || !toastMessage) return;
            const toastIcon = toastContainer.querySelector('i');


            toastIcon.className = iconClass;
            toastMessage.textContent = message;


            toastContainer.classList.add('show');


            setTimeout(() => {
                toastContainer.classList.remove('show');
            }, 2000);
        }


        function createBranchFromMessage(messageId) {
            const thread = getCurrentThread();
            if (!thread) return;
            const baseId = String(messageId).split('-')[0];
            const msgIndex = thread.messages.findIndex(m => String(m.id || m.timestamp) === baseId);
            if (msgIndex < 0) {
                showToast('找不到分支起点', 'ri-error-warning-line');
                return;
            }
            const friendData = threadManager[currentFriendId];
            const newId = Math.max(0, ...friendData.threads.map(t => t.id)) + 1;
            friendData.threads.push({
                id: newId,
                name: `分支 ${newId}`,
                // 显式记录来源，供分支管理面板正确展示分叉关系。
                parentThreadId: thread.id,
                parentMessageId: thread.messages[msgIndex].id || thread.messages[msgIndex].timestamp,
                createdAt: Date.now(),
                lastActive: Date.now(),
                messages: thread.messages.slice(0, msgIndex + 1).map(msg => ({ ...msg }))
            });
            friendData.currentThreadId = newId;
            saveThreadManager();
            renderFriendList();
            renderMessages(currentFriendId);
            // 面板若已打开，创建后立即刷新，不能依赖页面重载。
            if (typeof window.renderBranchTree === 'function') window.renderBranchTree();
            showToast('已从此处创建新对话分支', 'ri-git-branch-line');
        }

        function removeRenderedMessagesFrom(messageId) {
            const baseId = getMessageIdBase(messageId);
            const target = chatMessages.querySelector(`[data-message-id="${messageId}"]`) || chatMessages.querySelector(`[data-message-id="${baseId}"]`);
            if (!target) return false;
            let node = target;
            while (node) {
                const next = node.nextSibling;
                // 只删除消息元素和相关的操作按钮，避免误删其他 DOM 元素
                if (node.classList?.contains('message') || node.classList?.contains('message-actions')) {
                    node.remove();
                }
                node = next;
            }
            return true;
        }

        async function regenerateAIResponse(messageId) {
            const messages = getMessages();

            const baseId = getMessageIdBase(messageId);
            const msgIndex = messages.findIndex(m => String(m.id || m.timestamp) === baseId);

            dbgLog('重新回答调试:', { messageId, baseId, msgIndex, messagesCount: messages.length });

            if (msgIndex === -1 || msgIndex === 0) {
                showToast("无法重新生成回复", "ri-error-warning-line");
                return;
            }
            /* 最后一条 AI 文本消息 → 「再加一版」而不是「覆盖」：
               生成的回复会作为新版本合并到同一条消息上，用户可以左右滑动挑一版留下。
               其余情况（中间那条、群聊、图片消息）沿用原来的「删掉重生成」。 */
            const swipeTarget = messages[msgIndex];
            const swipeEligible = featureOn('swipeVariants')
                && swipeTarget
                && swipeTarget.role === 'other'
                && (swipeTarget.type === 'text' || !swipeTarget.type)
                && msgIndex === messages.length - 1
                && !isGroupChat(currentFriendId);

            let lastUserMsg = null;
            for (let i = msgIndex - 1; i >= 0; i--) {
                if (messages[i].role === 'mine') {
                    lastUserMsg = messages[i].content;
                    break;
                }
            }

            if (!lastUserMsg) {
                showToast("找不到对应的用户消息", "ri-error-warning-line");
                return;
            }

            /* 对「不在末尾」的 AI 消息点重新回答，旧实现是把这条连同它之后的消息全部删掉再生成。
               这很容易被误当成「我的几版回复被吃掉了」，所以先问一句。 */
            const trailingCount = messages.length - 1 - msgIndex;
            if (!swipeEligible && trailingCount > 0) {
                let confirmed = true;   // 弹窗组件缺失时不阻断（保持旧行为）
                if (window.Dlg && typeof window.Dlg.confirm === 'function') {
                    confirmed = await window.Dlg.confirm({
                        title: '重新生成这条回复？',
                        message: `这条消息后面还有 ${trailingCount} 条消息，重新生成会把它们一并删掉（不可撤销）。\n\n`
                            + '如果你只是想换一种说法、又舍不得后面的对话，建议先备份这段，或者只对最后一条用「重新回答」。',
                        okText: '删掉并重新生成'
                    }) === true;
                }
                if (!confirmed) return;
            }

            const friendData = threadManager[currentFriendId];
            // 判空：「重新生成」按钮可能在角色被删除后仍留在旧 DOM 上
            const thread = friendData?.threads?.find(t => t.id === friendData.currentThreadId);
            /* 删除起点：普通的就删这一条；如果是分段生成的一批，从这批的第一段开始删，
               并把整批文本拼成「第 1 版」，否则新版本只替换掉最后一段、前几段会留在上面。 */
            let cutIndex = msgIndex;
            let swipeOldText = null;
            if (thread && swipeEligible) {
                const group = swipeTarget.segmentGroup;
                let first = msgIndex;
                if (group) {
                    while (first > 0 && messages[first - 1] && messages[first - 1].segmentGroup === group) first--;
                    if (first < msgIndex) {
                        swipeOldText = messages.slice(first, msgIndex + 1)
                            .filter(m => m.role === 'other' && (m.type === 'text' || !m.type))
                            .map(m => String(m.content || '')).join('\n\n');
                    }
                    cutIndex = first;
                }
                beginSwipeStash(currentFriendId, thread.id, messages[cutIndex] || swipeTarget, swipeOldText);
            }
            if (thread) {
                dbgLog('删除消息前的线程消息数:', thread.messages.length);
                /* 下面要 splice 的是 thread.messages，而 messages 就是同一个数组
                   （getMessages 返回引用、不是副本）。所以「要删哪条」的 id、以及
                   群聊分支要用的失败消息，都必须在删之前先取出来，删完再读就是 undefined。 */
                const failedMessageSnapshot = messages[msgIndex];
                const cutBaseId = getMessageIdBase(String((messages[cutIndex] || messages[msgIndex] || {}).id || baseId));
                // 删除从 cutIndex 开始的所有消息（包括 AI 回复）
                thread.messages.splice(cutIndex);
                dbgLog('删除消息后的线程消息数:', thread.messages.length);
                saveThreadManager();
                removeRenderedMessagesFrom(cutBaseId);
                dbgLog('开始调用 AI，用户消息:', lastUserMsg);

                // 群聊消息必须根据消息记录中的 friendId 定位实际发言成员。
                // 旧逻辑不区分单聊/群聊，统一调用 enqueueAIResponse()，后者会把当前会话
                // （即群聊容器）的名称和头像当作 AI 身份，因此点击群成员的错误消息重试时
                // 会错误显示为群名称和群头像。
                if (isGroupChat(currentFriendId)) {
                    const failedMessage = failedMessageSnapshot;
                    const group = groupManager[currentFriendId];
                    const memberId = failedMessage?.friendId || failedMessage?.metadata?.friendId;

                    if (!group || !memberId || !group.memberIds?.includes(memberId) || !friendsData[memberId]) {
                        console.error('找不到需要重新回复的群成员:', { groupId: currentFriendId, memberId, failedMessage });
                        showToast('找不到需要重新回复的群成员', 'ri-error-warning-line');
                        // 前面已移除的消息不能保留半截状态，按当前数据重新绘制。
                        renderMessages(currentFriendId);
                        return;
                    }

                    // 上一次失败请求已将用户消息写入该成员的私有上下文，但失败时不会写入
                    // assistant 消息。移除这条尾部 user 记录，再由重试请求正常写回，避免
                    // 同一句用户消息在该成员上下文中重复两次。
                    const memberHistory = group.memberThreads?.[memberId]?.messages;
                    if (Array.isArray(memberHistory)) {
                        const lastHistoryMessage = memberHistory[memberHistory.length - 1];
                        if (lastHistoryMessage?.role === 'user' && lastHistoryMessage.content === lastUserMsg) {
                            memberHistory.pop();
                        }
                    }

                    // callGroupMemberAI 会使用 memberId 对应角色的头像、昵称和人设，
                    // 从而保证重试后的显示身份与原错误消息的发送者一致。
                    callGroupMemberAI(lastUserMsg, currentFriendId, memberId, thread.id);
                } else {
                    enqueueAIResponse(lastUserMsg, { friendId: currentFriendId, threadId: thread.id });
                }
            } else {
                console.error('找不到当前线程');
                showToast("找不到当前对话线程", "ri-error-warning-line");
            }
        }

        async function generateQuickReplies(userMessage, aiResponse, friendId = currentFriendId) {
            if (!enableLazyModeCheckbox.checked) return;

            // Jev 快速通道：配置了 Jev 且为懒人模式开启后，快捷回复由 Jev 从预设池里
            // 挑选（不调用聊天模型，毫秒级返回）。Jev 只能「选」不能「写」；
            // 未配置 / 未开启 / 置信度低 / 请求失败时走下方原有 LLM 生成流程。
            if (window.JevModule?.isEnabled?.('lazy')) {
                try {
                    const jevPicks = await JevModule.pickLazyReplies([
                        { role: 'user', content: userMessage },
                        { role: 'assistant', content: aiResponse }
                    ]);
                    if (jevPicks && jevPicks.length) {
                        displayQuickReplies(jevPicks.slice(0, 2));
                        return;
                    }
                } catch (e) { console.warn('[懒人模式] Jev 选择失败，回退到模型生成:', e); }
            }

            const baseSettings = getMainApiSettings();
            // 本地部署模型无需 Key
            if (!baseSettings || !baseSettings.apiUrl || !ApiModule.hasUsableApiCredential(baseSettings.apiUrl, baseSettings.apiKey)) {
                showToast('懒人模式未生效：请先在「设置 → AI 配置」填写 API 地址与 Key（本地服务可免 Key）', 'ri-key-2-line');
                return;
            }
            const apiSettings = window.FeatureModels
                ? FeatureModels.resolve('lazy', baseSettings)
                : baseSettings;
            if (!apiSettings.modelName) {
                showToast('懒人模式未生效：未填写模型名称（或在「专用模型」里留了空）', 'ri-question-line');
                return;
            }

            const friend = friendsData[friendId];
            // 群聊角色没有 systemPrompt 字段，之前直接 .substring 会抛 TypeError，
            // 表现为「懒人模式总是失败」却没有任何可读提示。
            const personaHint = String(friend?.systemPrompt || '').slice(0, 500) || '（无额外人设，按对话语气自然生成）';

            const prompt = `
基于以下对话上下文，请站在**用户**的角度，生成 2 个简短的回复选项（每个不超过 20 字）。
回复内容应该是用户想对 AI 说的话，符合用户的说话风格。
只输出 JSON 数组本身，不要 markdown 代码块、不要注释、不要解释。
格式：["回复选项1", "回复选项2"]

对话：
用户：${userMessage}
AI：${aiResponse}
角色人设（仅供语气参考）：${personaHint}
`.trim();

            let lazySystem = prompt;
            try { if (window.EnglishMode) lazySystem = window.EnglishMode.applyToSystem(lazySystem, 'chat'); } catch (e) { /* 英文模式未加载按原文 */ }
            try {
                const content = await ApiModule.requestSmallTask(apiSettings, lazySystem, '请按要求输出 JSON 数组。', {
                    maxTokens: 220,
                    temperature: 0.8,
                    label: '懒人模式'
                });
                const replies = parseQuickReplyList(content);
                if (!replies.length) {
                    showToast('懒人模式没有拿到可用选项（模型未按 JSON 返回）。可在「设置 → AI 配置 → 专用模型」为懒人模式换一个指令跟随更好的模型', 'ri-error-warning-line');
                    console.warn('[懒人模式] 模型原始输出：', String(content || '').slice(0, 400));
                    return;
                }
                displayQuickReplies(replies.slice(0, 2));
            } catch (error) {
                const friendlyError = ApiModule.handleApiError(error, '生成快捷回复');
                showToast(`${friendlyError}（懒人模式）—— 可在「设置 → AI 配置 → 专用模型」为该功能单独指定一个更小的模型`, 'ri-error-warning-line');
            }
        }

        /** 兼容多种模型输出风格地解析快捷回复数组 */
        function parseQuickReplyList(content) {
            const raw = String(content || '')
                .replace(/```json/gi, '')
                .replace(/```/g, '')
                .trim();
            const candidates = [];
            try { candidates.push(JSON.parse(raw)); } catch (e) {}
            if (!Array.isArray(candidates[0])) {
                // 从文本里抠出第一个 JSON 数组（模型常带前后说明文字）
                const match = raw.match(/\[[\s\S]*\]/);
                if (match) {
                    try { candidates.length = 0; candidates.push(JSON.parse(match[0])); } catch (e) {}
                }
            }
            let list = Array.isArray(candidates[0]) ? candidates[0] : null;
            if (!list) {
                // 最后兜底：按行拆分（"1. xxx" / "- xxx" / 纯文本一行一个）
                const lines = raw.split('\n').map(l => l.replace(/^[\s\-•*\d.、)）]+/, '').replace(/^["“”]|["“”]$/g, '').trim()).filter(Boolean);
                list = lines.length >= 2 ? lines : [];
            }
            return list
                .map(item => String(typeof item === 'object' && item !== null ? (item.reply || item.text || item.content || '') : item).trim())
                .filter(Boolean)
                .slice(0, 2);
        }

        function displayQuickReplies(replies) {
            const list = (Array.isArray(replies) ? replies : [])
                .map(t => String(t || '').trim())
                .filter(Boolean);

            // ========== 视觉小说模式：选项搬到舞台上，做成 Galgame 选择肢 ==========
            // 舞台盖住了消息区，普通快捷回复用户根本看不见，因此这里优先交给 VNMode；
            // 皮肤样式由 .vn-stage.skin-* 决定，与用户设置的对话框皮肤自动一致。
            if (window.VNMode?.isEnabled?.() && typeof VNMode.showChoices === 'function') {
                document.querySelector('.quick-replies')?.remove();
                VNMode.showChoices(list);
                return;
            }
            try { window.VNMode?.clearChoices?.(); } catch (e) {}

            const oldReplies = document.querySelector('.quick-replies');
            if (oldReplies) oldReplies.remove();
            if (!list.length) return;

            const repliesDiv = document.createElement('div');
            repliesDiv.className = 'quick-replies';

            list.forEach(reply => {
                const btn = document.createElement('button');
                btn.className = 'quick-reply-btn';
                btn.textContent = reply;
                btn.addEventListener('click', () => {
                    messageInput.value = reply;
                    // 填入的是可能多行的快捷回复：不重算高度的话输入框会停在最小高度，
                    // 文字被压在框里滚动（视觉上就是「有内容却只显示一行」）。
                    autoResizeMessageInput();
                    messageInput.focus();
                    repliesDiv.remove();
                });
                repliesDiv.appendChild(btn);
            });

            chatMessages.appendChild(repliesDiv);
            scrollToBottom();
        }

        // 被 vn-mode.js 的选项点击回调：填入输入框并直接发送
        window.vnChooseQuickReply = function (text) {
            const value = String(text || '').trim();
            if (!value) return;
            if (messageInput) {
                messageInput.value = value;
                autoResizeMessageInput();
                messageInput.focus();
            }
            // VN 舞台下消息区不可见，sendMessage 内部会自行滚动，不影响舞台
            sendMessage(value, 'text');
        };


