        // 弹窗版本的 AI 生成开场白按钮
        generateWelcomeBtnModal?.addEventListener('click', async () => {
            const prompt = newCharPromptInputModal.value.trim();
            const name = newCharNameInputModal.value.trim() || '角色';

            if (!prompt) {
               Dlg.alert('请先填写角色提示词！');
                return;
            }

            // 与内联版一致：支持「功能专用模型 → AI 生成开场白」
            const apiSettings = window.FeatureModels
                ? FeatureModels.resolve('welcome', getMainApiSettings())
                : getMainApiSettings();
            if (!apiSettings || !apiSettings.apiKey) {
               Dlg.alert('请先在设置中配置 API Key！');
                return;
            }

            generateWelcomeBtnModal.disabled = true;
            generateWelcomeBtnModal.innerHTML = '<i class="ri-loader-4-line ri-spin"></i> 生成中...';

            try {
                const welcome = (await ApiModule.runChatPlan(apiSettings, settings => ApiModule.requestJson(
                    ApiModule.buildChatUrl(settings.apiUrl),
                    ApiModule.createChatFetchOptions(settings, [
                        { role: "system", content: "你是一个创意文案助手，擅长为虚拟角色撰写生动、有深度的开场白。" },
                        { role: "user", content: `请为角色"${name}"生成一段精彩的开场白（100-200 字左右），基于以下人设：\n${prompt.substring(0, 800)}\n\n要求：\n1. 符合角色性格和背景设定\n2. 有场景感和代入感，可以适当描写动作、神态或环境\n3. 语气自然生动，能吸引用户继续对话\n4. 不要过于简短，要有一定的内容深度\n\n直接返回开场白内容，不要其他解释文字。` }
                    ], { temperature: 0.8, max_tokens: 300, stream: false })
                )))?.choices?.[0]?.message?.content?.trim();
                if (welcome) newCharWelcomeInputModal.value = welcome;
            } catch (error) {
                const friendlyError = ApiModule.handleApiError(error, '生成开场白');
                showToast(friendlyError, 'ri-error-warning-line');
            } finally {
                generateWelcomeBtnModal.disabled = false;
                generateWelcomeBtnModal.innerHTML = '<i class="ri-magic-line"></i> AI 生成开场白';
            }
        });

        function saveCustomFriendsData() {
            const customData = {};
            Object.keys(friendsData).forEach(key => {
                const friend = friendsData[key];
                if (!friend || !friend.isCustom) return;
                // 只写「真的有内容」的字段：内置角色被复制成自定义角色后会残留空的
                // systemPrompt / welcomeMessage，空串没有意义，却会把整份出厂数据
                // 一起塞进 localStorage 和备份文件。
                const slim = { ...friend };
                Object.keys(slim).forEach(field => {
                    if (slim[field] === '' || slim[field] === null || slim[field] === undefined) delete slim[field];
                });
                customData[key] = slim;
            });
            setLocalStorageSafely('customFriendsData', JSON.stringify(customData), '自定义角色数据');
        }


        // 气泡圆角取值表：统一由此派生，避免多处硬编码不一致
        const BUBBLE_RADIUS_MAP = {
            default: '12px',
            sharp: '4px',
            rounded: '20px'
        };
        const BUBBLE_RADIUS_LIMITS = { min: 0, max: 48, fallback: 12 };
        let currentBubbleRadius = BUBBLE_RADIUS_MAP.default;

        function normalizeBubbleRadius(value) {
            const radius = parseInt(value, 10);
            const safeRadius = Number.isNaN(radius) ? BUBBLE_RADIUS_LIMITS.fallback : radius;
            return `${Math.min(BUBBLE_RADIUS_LIMITS.max, Math.max(BUBBLE_RADIUS_LIMITS.min, safeRadius))}px`;
        }

        function getBubbleRadius(style = currentBubbleStyle) {
            if (style === 'custom') return normalizeBubbleRadius(currentBubbleRadius);
            return BUBBLE_RADIUS_MAP[style] || BUBBLE_RADIUS_MAP.default;
        }

        function syncBubbleRadiusControl() {
            if (!bubbleRadiusSlider || !bubbleRadiusValue) return;
            const radius = parseInt(getBubbleRadius(), 10);
            bubbleRadiusSlider.value = radius;
            bubbleRadiusValue.textContent = `${radius}px`;
        }

        /**
         * 把气泡形状写到根元素的 CSS 变量上。
         * 修复：过去圆角只在 appendMessageToDOM 创建气泡时以内联 style 写死，
         * 切换样式后既不会重绘已存在的气泡，也不会持久化，
         * 表现为「换了气泡样式没有立刻生效，要刷新/重进才行」。
         * 改为 CSS 变量后，所有气泡（含已渲染的）会立即响应。
         */
        function applyBubbleStyleToDocument() {
            const radius = getBubbleRadius();
            document.documentElement.style.setProperty('--bubble-radius', radius);
            // 清理历史遗留的内联圆角，让 CSS 变量重新接管
            document.querySelectorAll('.bubble').forEach(bubble => {
                if (bubble.style.borderRadius) bubble.style.borderRadius = '';
            });
        }

        function initBubbleStyleSelector() {
            if (bubbleRadiusSlider) {
                bubbleRadiusSlider.addEventListener('input', () => {
                    currentBubbleRadius = normalizeBubbleRadius(bubbleRadiusSlider.value);
                    currentBubbleStyle = 'custom';
                    syncBubbleRadiusControl();
                    updateBubbleStyleUI();
                    if (typeof saveChatSettings === 'function') saveChatSettings();
                });
            }
            const options = document.querySelectorAll('.bubble-style-option');
            options.forEach(option => {
                option.addEventListener('click', () => {
                    currentBubbleStyle = option.dataset.style || 'default';
                    currentBubbleRadius = getBubbleRadius(currentBubbleStyle);
                    syncBubbleRadiusControl();
                    updateBubbleStyleUI();
                    // 立即生效 + 立即持久化
                    applyBubbleStyleToDocument();
                    if (typeof saveChatSettings === 'function') saveChatSettings();
                    if (typeof showToast === 'function') {
                        const label = { default: '默认', sharp: '直角', rounded: '圆润' }[currentBubbleStyle] || currentBubbleStyle;
                        showToast(`气泡样式已切换为「${label}」`, 'ri-chat-3-line');
                    }
                });
            });
            // 初始化时也同步一次，保证首屏与已保存设置一致
            applyBubbleStyleToDocument();
        }

        function updateBubbleStyleUI() {
            const options = document.querySelectorAll('.bubble-style-option');
            options.forEach(option => {
                if (option.dataset.style === currentBubbleStyle) {
                    option.style.borderColor = '#e6c78a';
                    option.style.background = 'rgba(230, 199, 138, 0.1)';
                } else {
                    option.style.borderColor = '#555';
                    option.style.background = 'rgba(85, 85, 85, 0.1)';
                }
            });
            syncBubbleRadiusControl();
            // 选中态与实际渲染保持同步
            applyBubbleStyleToDocument();
        }

        window.applyBubbleStyleToDocument = applyBubbleStyleToDocument;


        selectBubbleBgBtn?.addEventListener('click', () => {
            bubbleBgUpload.click();
        });

        bubbleBgUpload?.addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (file) {
                // 气泡背景也属于「上传的图片」：勾了「不压缩图片」时必须保留原图，
                // 否则设置里写着不压缩、气泡背景仍被重编码成 JPEG，画质对不上。
                ImageTools.compress(file, 900, 0.86).then(dataUrl => {
                    currentBubbleImage = dataUrl;
                    applyBubbleBackground();
                    saveChatSettings();
                }).catch(() => {
                    const reader = new FileReader();
                    reader.onload = (evt) => {
                        currentBubbleImage = evt.target.result;
                        applyBubbleBackground();
                        saveChatSettings();
                    };
                    reader.readAsDataURL(file);
                });
            }
            bubbleBgUpload.value = '';
        });

        resetBubbleBgBtn?.addEventListener('click', () => {
            currentBubbleImage = null;
            applyBubbleBackground();
            saveChatSettings();
        });

        function applyBubbleBackground() {
            const bubbles = document.querySelectorAll('.bubble');
            bubbles.forEach(bubble => {
                if (currentBubbleImage) {
                    bubble.classList.add('has-custom-bg');
                    bubble.style.backgroundImage = `url('${currentBubbleImage}')`;
                    bubbleBgPreview.style.display = 'block';
                    bubbleBgPreview.style.backgroundImage = `url('${currentBubbleImage}')`;
                } else {
                    bubble.classList.remove('has-custom-bg');
                    bubble.style.backgroundImage = '';
                    bubbleBgPreview.style.display = 'none';
                    bubbleBgPreview.style.backgroundImage = '';
                }
            });
        }


        function updateBubbleTextInputs() {
            bubbleTextColorInput.value = currentBubbleTextStyle.color;
            bubbleFontSizeInput.value = currentBubbleTextStyle.fontSize;
            bubbleStrokeColorInput.value = currentBubbleTextStyle.strokeColor;
            bubbleStrokeWidthInput.value = currentBubbleTextStyle.strokeWidth;
            enableBubbleStrokeCheckbox.checked = currentBubbleTextStyle.enableStroke;
        }

        function saveBubbleTextStyleFromInputs() {
            currentBubbleTextStyle = {
                color: bubbleTextColorInput.value,
                fontSize: parseInt(bubbleFontSizeInput.value, 10) || 14,
                strokeColor: bubbleStrokeColorInput.value,
                strokeWidth: parseInt(bubbleStrokeWidthInput.value, 10) || 1,
                enableStroke: enableBubbleStrokeCheckbox.checked
            };
            applyBubbleTextStyleToAll();
        }

        function applyBubbleTextStyleToAll() {
            const bubbles = document.querySelectorAll('.bubble');
            bubbles.forEach(bubble => {
                applyBubbleTextStyle(bubble);
            });
        }



